        private Button CreateToolButton(ToolType tool, Geometry iconGeo, string tooltip)
        {
            var btn = new Button
            {
                Width = 34,
                Height = 34,
                Margin = new Thickness(2, 0, 2, 0),
                Background = Brushes.Transparent,
                BorderThickness = new Thickness(0),
                Cursor = Cursors.Hand,
                ToolTip = tooltip,
                Tag = tool,
                Template = CreateRoundedButtonTemplate(6)
            };

            bool isFilled = (tool == ToolType.Select);
            var icon = VectorIcons.CreateIcon(iconGeo, KerfBrand.TextWhiteBrush, isFilled ? KerfBrand.TextWhiteBrush : null, 18);
            btn.Content = icon;

            btn.Click += (s, e) => SetActiveTool(tool);
            _toolButtons[tool] = btn;
            return btn;
        }

        public void SetActiveTool(ToolType tool)
        {
            if (tool != ToolType.Pen && _activePenNode != null)
            {
                FinishPenDrawing();
            }

            if (_activeTool == ToolType.Anchor && tool != ToolType.Anchor)
            {
                if (_currentStudioMode == StudioMode.Animate && _selectedLayers.Count == 1)
                {
                    var primary = _selectedLayers[0];
                    if (primary.RenderTransform != null)
                    {
                        AutoKeyProperty(primary, PropKey.AnchorX, primary.RenderTransform.AnchorX);
                        AutoKeyProperty(primary, PropKey.AnchorY, primary.RenderTransform.AnchorY);
                        AutoKeyProperty(primary, PropKey.X, primary.X + primary.RenderTransform.TranslationX);
                        AutoKeyProperty(primary, PropKey.Y, primary.Y + primary.RenderTransform.TranslationY);
                        RefreshPropertyInspector();
                    }
                }
            }

            _activeTool = tool;
            foreach (var kvp in _toolButtons)
            {
                bool isActive = (kvp.Key == tool);
                var btn = kvp.Value;
                btn.Background = isActive
                    ? KerfBrand.MintBrush
                    : Brushes.Transparent;

                var path = btn.Content as System.Windows.Shapes.Path;
                if (path != null)
                {
                    var brush = isActive ? (Brush)KerfBrand.TextBlackBrush : (Brush)KerfBrand.TextWhiteBrush;
                    path.Stroke = brush;
                    if (kvp.Key == ToolType.Select)
                    {
                        path.Fill = brush;
                    }
                }
            }

            if (_canvasHost != null)
            {
                _canvasHost.Cursor = (tool == ToolType.Hand) ? Cursors.Hand :
                                     (tool == ToolType.Pen) ? Cursors.Pen :
                                     (tool == ToolType.Text) ? Cursors.IBeam :
                                     (tool == ToolType.Marquee || tool == ToolType.Anchor) ? Cursors.Cross : Cursors.Arrow;
            }
            RefreshCanvas();
        }

