        private void BuildClippingSection(LayerNode primary)
        {
            if (primary == null) return;
            if (primary.ClippingTargets == null) primary.ClippingTargets = new List<ClippingTargetData>();

            Action refreshClipping = () =>
            {
                if (primary != null) _sceneGraph.InvalidateNode(primary.Id);
                RefreshCanvas();
                RefreshPropertyInspector();
            };

            var page = Document != null ? Document.GetActivePage() : null;
            var otherLayers = new List<LayerNode>();
            if (page != null)
            {
                var flat = page.GetAllLayersFlat().ToList();
                for (int i = 0; i < flat.Count; i++)
                {
                    var l = flat[i];
                    if (l != null && l != primary && !string.IsNullOrEmpty(l.Id))
                    {
                        otherLayers.Add(l);
                    }
                }
            }

            var clipSourceLayers = otherLayers.Where(l => l.Type != ElementType.Frame &&
                l.Type != ElementType.ComponentInstance && l.Type != ElementType.Slice).ToList();

            Action onAdd = () =>
            {
                var clip = new ClippingTargetData
                {
                    TargetLayerId = string.Empty,
                    TargetNodeId = 0u,
                    IsInverse = false,
                    Enabled = true
                };
                var addCommand = new AddClippingTargetCommand(primary.ClippingTargets, clip, refreshClipping);
                if (History != null) History.Execute(addCommand);
                else addCommand.Execute();
                BeginClipTargetPick(primary, clip);
                RefreshPropertyInspector();
            };

            _propertyInspectorStack.Children.Add(CreateInspectorSectionWithAdd("Clipping", onAdd));

            if (primary.ClippingTargets.Count == 0)
            {
                var emptyBtn = CreateSmallButton("+ Add Clip Target", "Clip to another shape, path, or group", onAdd);
                _propertyInspectorStack.Children.Add(emptyBtn);
                return;
            }

            var clipsContainer = new StackPanel();
            for (int i = 0; i < primary.ClippingTargets.Count; i++)
            {
                int clipIdx = i;
                var clip = primary.ClippingTargets[i];
                if (clip == null) continue;

                var card = new Border
                {
                    Background = new SolidColorBrush(Color.FromRgb(24, 28, 40)),
                    BorderBrush = new SolidColorBrush(Color.FromRgb(38, 46, 66)),
                    BorderThickness = new Thickness(1),
                    CornerRadius = new CornerRadius(5),
                    Padding = new Thickness(6, 6, 6, 6),
                    Margin = new Thickness(0, 0, 0, 6)
                };

                var cardStack = new StackPanel();

                // Row 1: Target dropdown + Enabled toggle + Delete
                var topRow = new DockPanel { Margin = new Thickness(0, 0, 0, 4) };

                var delBtn = new Button
                {
                    Content = "✕",
                    Width = 18,
                    Height = 18,
                    Background = Brushes.Transparent,
                    Foreground = KerfBrand.TextMutedBrush,
                    BorderThickness = new Thickness(0),
                    Cursor = Cursors.Hand,
                    ToolTip = "Remove clipping target",
                    Padding = new Thickness(0)
                };
                delBtn.Click += (s, e) =>
                {
                    if (clipIdx >= 0 && clipIdx < primary.ClippingTargets.Count)
                    {
                        if (ReferenceEquals(_pendingClipTarget, clip))
                        {
                            _pendingClipTarget = null;
                            _clipTargetOwner = null;
                            if (_canvasHost != null) _canvasHost.Cursor = Cursors.Arrow;
                        }
                        var removeCommand = new RemoveClippingTargetCommand(primary.ClippingTargets, clip, refreshClipping);
                        if (History != null) History.Execute(removeCommand);
                        else removeCommand.Execute();
                    }
                };
                DockPanel.SetDock(delBtn, Dock.Right);
                topRow.Children.Add(delBtn);

                var enCheck = new CheckBox
                {
                    IsChecked = clip.Enabled,
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 0, 6, 0),
                    ToolTip = "Toggle clipping target"
                };
                Action<bool> setClipEnabled = enabled =>
                {
                    if (clip.Enabled == enabled) return;
                    var before = clip.Clone();
                    var after = clip.Clone();
                    after.Enabled = enabled;
                    var command = new ModifyClippingTargetCommand(clip, before, after, refreshClipping);
                    if (History != null) History.Execute(command);
                    else command.Execute();
                };
                enCheck.Checked += (s, e) => setClipEnabled(true);
                enCheck.Unchecked += (s, e) => setClipEnabled(false);
                DockPanel.SetDock(enCheck, Dock.Left);
                topRow.Children.Add(enCheck);

                var targetCombo = CreateModernComboBox(24);
                targetCombo.Items.Add(new ComboBoxItem { Content = "Pick a clip source…", Tag = string.Empty });
                int selIdx = -1;
                for (int l = 0; l < clipSourceLayers.Count; l++)
                {
                    var ol = clipSourceLayers[l];
                    string typeIcon = ol.Type == ElementType.Group ? "▧ " : (ol.Type == ElementType.Path ? "⤹ " : "◻ ");
                    targetCombo.Items.Add(new ComboBoxItem
                    {
                        Content = typeIcon + ol.Name,
                        Tag = ol.Id
                    });
                    if (string.Equals(ol.Id, clip.TargetLayerId, StringComparison.OrdinalIgnoreCase))
                    {
                        selIdx = l + 1;
                    }
                }
                targetCombo.SelectedIndex = selIdx >= 0 ? selIdx : 0;

                targetCombo.SelectionChanged += (s, e) =>
                {
                    var item = targetCombo.SelectedItem as ComboBoxItem;
                    if (item != null && item.Tag is string)
                    {
                        string selectedTargetId = (string)item.Tag;
                        if (string.IsNullOrEmpty(selectedTargetId)) return;
                        if (string.Equals(clip.TargetLayerId, selectedTargetId, StringComparison.OrdinalIgnoreCase)) return;
                        var before = clip.Clone();
                        var after = clip.Clone();
                        after.TargetLayerId = selectedTargetId;
                        after.TargetNodeId = PropertyBinder.GetNumericNodeId(selectedTargetId);
                        var command = new ModifyClippingTargetCommand(clip, before, after, refreshClipping);
                        if (History != null) History.Execute(command);
                        else command.Execute();
                    }
                };
                topRow.Children.Add(targetCombo);
                var pickBtn = new Button
                {
                    Content = ReferenceEquals(_pendingClipTarget, clip) ? "Picking…" : "Pick",
                    Height = 22,
                    MinWidth = 40,
                    Margin = new Thickness(4, 0, 0, 0),
                    Padding = new Thickness(5, 0, 5, 0),
                    Background = ReferenceEquals(_pendingClipTarget, clip) ? KerfBrand.MintBrush : KerfBrand.DarkSlateBrush,
                    Foreground = ReferenceEquals(_pendingClipTarget, clip) ? KerfBrand.TextBlackBrush : Brushes.White,
                    BorderBrush = KerfBrand.FigmaBorderBrush,
                    Cursor = Cursors.Hand,
                    ToolTip = "Pick a shape or group from the canvas"
                };
                pickBtn.Click += (s, e) =>
                {
                    if (ReferenceEquals(_pendingClipTarget, clip))
                    {
                        _pendingClipTarget = null;
                        _clipTargetOwner = null;
                        if (_canvasHost != null) _canvasHost.Cursor = Cursors.Arrow;
                    }
                    else BeginClipTargetPick(primary, clip);
                    RefreshPropertyInspector();
                };
                topRow.Children.Add(pickBtn);
                cardStack.Children.Add(topRow);

                // Row 2: Mode toggle (Inside vs Outside/Hole)
                var modeRow = new Grid { Margin = new Thickness(0, 2, 0, 0) };
                modeRow.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                modeRow.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(4) });
                modeRow.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

                var insideBtn = new Button
                {
                    Content = "Clip Inside",
                    Height = 22,
                    FontSize = 10.5,
                    Background = !clip.IsInverse ? new SolidColorBrush(Color.FromRgb(45, 55, 78)) : KerfBrand.FigmaCanvasBrush,
                    Foreground = !clip.IsInverse ? KerfBrand.MintBrush : Brushes.White,
                    BorderBrush = !clip.IsInverse ? KerfBrand.MintBrush : KerfBrand.FigmaBorderBrush,
                    BorderThickness = new Thickness(1),
                    Cursor = Cursors.Hand
                };
                insideBtn.Click += (s, e) =>
                {
                    if (!clip.IsInverse) return;
                    var before = clip.Clone();
                    var after = clip.Clone();
                    after.IsInverse = false;
                    var command = new ModifyClippingTargetCommand(clip, before, after, refreshClipping);
                    if (History != null) History.Execute(command);
                    else command.Execute();
                };
                Grid.SetColumn(insideBtn, 0);
                modeRow.Children.Add(insideBtn);

                var outsideBtn = new Button
                {
                    Content = "Clip Outside (Hole)",
                    Height = 22,
                    FontSize = 10.5,
                    Background = clip.IsInverse ? new SolidColorBrush(Color.FromRgb(45, 55, 78)) : KerfBrand.FigmaCanvasBrush,
                    Foreground = clip.IsInverse ? KerfBrand.MintBrush : Brushes.White,
                    BorderBrush = clip.IsInverse ? KerfBrand.MintBrush : KerfBrand.FigmaBorderBrush,
                    BorderThickness = new Thickness(1),
                    Cursor = Cursors.Hand
                };
                outsideBtn.Click += (s, e) =>
                {
                    if (clip.IsInverse) return;
                    var before = clip.Clone();
                    var after = clip.Clone();
                    after.IsInverse = true;
                    var command = new ModifyClippingTargetCommand(clip, before, after, refreshClipping);
                    if (History != null) History.Execute(command);
                    else command.Execute();
                };
                Grid.SetColumn(outsideBtn, 2);
                modeRow.Children.Add(outsideBtn);

                cardStack.Children.Add(modeRow);
                card.Child = cardStack;
                clipsContainer.Children.Add(card);
            }

            _propertyInspectorStack.Children.Add(clipsContainer);
        }

        private void BeginClipTargetPick(LayerNode owner, ClippingTargetData clip)
        {
            _clipTargetOwner = owner;
            _pendingClipTarget = clip;
            if (_canvasHost != null) _canvasHost.Cursor = Cursors.Cross;
        }

        private void ShowAddConstraintMenu(FrameworkElement anchor, LayerNode primary)
        {
            if (anchor == null || primary == null) return;
            var menu = new ContextMenu();
            menu.Background = KerfBrand.FigmaPanelBrush;
            menu.BorderBrush = KerfBrand.FigmaBorderBrush;
            menu.Foreground = Brushes.White;

            var types = new[]
            {
                new { Type = AnimationConstraintType.Transform, Label = "Transform" },
                new { Type = AnimationConstraintType.Distance, Label = "Distance" },
                new { Type = AnimationConstraintType.Translation, Label = "Translation" },
                new { Type = AnimationConstraintType.Scale, Label = "Scale" },
                new { Type = AnimationConstraintType.Rotation, Label = "Rotation" },
                new { Type = AnimationConstraintType.IK, Label = "IK" },
                new { Type = AnimationConstraintType.FollowPath, Label = "Follow Path" },
                new { Type = AnimationConstraintType.Scroll, Label = "Scroll" }
            };

            var page = Document != null ? Document.GetActivePage() : null;
            var otherLayers = new List<LayerNode>();
            if (page != null)
            {
                var flat = page.GetAllLayersFlat().ToList();
                for (int i = 0; i < flat.Count; i++)
                {
                    var l = flat[i];
                    if (l != null && l != primary && !string.IsNullOrEmpty(l.Id))
                    {
                        otherLayers.Add(l);
                    }
                }
            }

            for (int i = 0; i < types.Length; i++)
            {
                var entry = types[i];
                var mi = new MenuItem
                {
                    Header = entry.Label,
                    Foreground = Brushes.White,
                    FontSize = 11.5,
                    Padding = new Thickness(10, 5, 10, 5)
                };
                AnimationConstraintType cType = entry.Type;
                mi.Click += (s, e) =>
                {
                    if (primary.Constraints == null) primary.Constraints = new List<AnimationConstraintData>();
                    string defaultTarget = otherLayers.Count > 0 ? otherLayers[0].Id : string.Empty;
                    if (cType == AnimationConstraintType.FollowPath)
                    {
                        for (int pl = 0; pl < otherLayers.Count; pl++)
                        {
                            if (otherLayers[pl].Type == ElementType.Path)
                            {
                                defaultTarget = otherLayers[pl].Id;
                                break;
                            }
                        }
                    }
                    var constraint = new AnimationConstraintData
                    {
                        Type = cType,
                        TargetLayerId = defaultTarget,
                        TargetNodeId = PropertyBinder.GetNumericNodeId(defaultTarget),
                        Enabled = true,
                        Strength = 1.0,
                        ConstrainX = true,
                        ConstrainY = true,
                        OrientToPath = true,
                        DistanceMode = cType == AnimationConstraintType.Distance ? DistanceConstraintMode.Closer : DistanceConstraintMode.Exact
                    };
                    primary.Constraints.Add(constraint);
                    if (page != null) ConstraintsEngine.Solve(page);
                    InvalidateAndRefresh(primary);
                    RefreshPropertyInspector();
                };
                menu.Items.Add(mi);
            }

            menu.PlacementTarget = anchor;
            menu.Placement = PlacementMode.Bottom;
            menu.IsOpen = true;
        }

        private void BuildConstraintsSection(LayerNode primary)
        {
            if (primary == null) return;
            if (primary.Constraints == null) primary.Constraints = new List<AnimationConstraintData>();

            var page = Document != null ? Document.GetActivePage() : null;
            var otherLayers = new List<LayerNode>();
            if (page != null)
            {
                var flat = page.GetAllLayersFlat().ToList();
                for (int i = 0; i < flat.Count; i++)
                {
                    var l = flat[i];
                    if (l != null && l != primary && !string.IsNullOrEmpty(l.Id))
                    {
                        otherLayers.Add(l);
                    }
                }
            }

            _propertyInspectorStack.Children.Add(CreateInspectorSectionWithMenu("Constraints", btn => ShowAddConstraintMenu(btn, primary)));

            if (primary.Constraints.Count == 0)
            {
                Button emptyBtn = null;
                emptyBtn = CreateSmallButton("+ Add Constraint", "Add Transform, Distance, IK, Follow Path, or Scroll constraint", () => ShowAddConstraintMenu(emptyBtn, primary));
                _propertyInspectorStack.Children.Add(emptyBtn);
                return;
            }

            var constraintsContainer = new StackPanel();
            for (int i = 0; i < primary.Constraints.Count; i++)
            {
                int cIdx = i;
                var c = primary.Constraints[i];
                if (c == null) continue;

                var card = new Border
                {
                    Background = new SolidColorBrush(Color.FromRgb(24, 28, 40)),
                    BorderBrush = new SolidColorBrush(Color.FromRgb(38, 46, 66)),
                    BorderThickness = new Thickness(1),
                    CornerRadius = new CornerRadius(5),
                    Padding = new Thickness(7, 6, 7, 6),
                    Margin = new Thickness(0, 0, 0, 8)
                };

                var cardStack = new StackPanel();

                // Row 1: Type Title + Enabled Checkbox + Delete
                var topRow = new DockPanel { Margin = new Thickness(0, 0, 0, 6) };

                var delBtn = new Button
                {
                    Content = "✕",
                    Width = 18,
                    Height = 18,
                    Background = Brushes.Transparent,
                    Foreground = KerfBrand.TextMutedBrush,
                    BorderThickness = new Thickness(0),
                    Cursor = Cursors.Hand,
                    ToolTip = "Remove constraint",
                    Padding = new Thickness(0)
                };
                delBtn.Click += (s, e) =>
                {
                    if (cIdx >= 0 && cIdx < primary.Constraints.Count)
                    {
                        primary.Constraints.RemoveAt(cIdx);
                        if (page != null) ConstraintsEngine.Solve(page);
                        InvalidateAndRefresh(primary);
                        RefreshPropertyInspector();
                    }
                };
                DockPanel.SetDock(delBtn, Dock.Right);
                topRow.Children.Add(delBtn);

                var enCheck = new CheckBox
                {
                    IsChecked = c.Enabled,
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 0, 6, 0),
                    ToolTip = "Enable or disable constraint"
                };
                enCheck.Checked += (s, e) =>
                {
                    c.Enabled = true;
                    if (page != null) ConstraintsEngine.Solve(page);
                    InvalidateAndRefresh(primary);
                };
                enCheck.Unchecked += (s, e) =>
                {
                    c.Enabled = false;
                    if (page != null) ConstraintsEngine.Solve(page);
                    InvalidateAndRefresh(primary);
                };
                DockPanel.SetDock(enCheck, Dock.Left);
                topRow.Children.Add(enCheck);

                string typeTitle = c.Type.ToString();
                if (c.Type == AnimationConstraintType.FollowPath) typeTitle = "Follow Path";
                var titleBlock = new TextBlock
                {
                    Text = "✦ " + typeTitle,
                    FontWeight = FontWeights.Bold,
                    FontSize = 11.5,
                    Foreground = KerfBrand.MintBrush,
                    VerticalAlignment = VerticalAlignment.Center
                };
                topRow.Children.Add(titleBlock);
                cardStack.Children.Add(topRow);

                // Row 2: Target Selector
                var targetRow = new DockPanel { Margin = new Thickness(0, 0, 0, 4) };
                var targetLbl = new TextBlock
                {
                    Text = "Target",
                    FontSize = 10.5,
                    Foreground = KerfBrand.TextMutedBrush,
                    Width = 50,
                    VerticalAlignment = VerticalAlignment.Center
                };
                DockPanel.SetDock(targetLbl, Dock.Left);
                targetRow.Children.Add(targetLbl);

                var targetCombo = CreateModernComboBox(24);
                int selIdx = -1;
                for (int l = 0; l < otherLayers.Count; l++)
                {
                    var ol = otherLayers[l];
                    string typeIcon = ol.Type == ElementType.Frame ? "▣ " : (ol.Type == ElementType.Path ? "⤹ " : "◻ ");
                    targetCombo.Items.Add(new ComboBoxItem
                    {
                        Content = typeIcon + ol.Name,
                        Tag = ol.Id
                    });
                    if (string.Equals(ol.Id, c.TargetLayerId, StringComparison.OrdinalIgnoreCase))
                    {
                        selIdx = l;
                    }
                }
                if (selIdx >= 0) targetCombo.SelectedIndex = selIdx;
                else if (targetCombo.Items.Count > 0) targetCombo.SelectedIndex = 0;

                targetCombo.SelectionChanged += (s, e) =>
                {
                    var item = targetCombo.SelectedItem as ComboBoxItem;
                    if (item != null && item.Tag is string)
                    {
                        c.TargetLayerId = (string)item.Tag;
                        c.TargetNodeId = PropertyBinder.GetNumericNodeId(c.TargetLayerId);
                        if (page != null) ConstraintsEngine.Solve(page);
                        InvalidateAndRefresh(primary);
                    }
                };
                targetRow.Children.Add(targetCombo);
                cardStack.Children.Add(targetRow);

                // Row 3: Strength Slider / Field (0% - 100%)
                var strengthField = ScrubControls.CreateScrubField("Strength", c.Strength * 100.0, val =>
                {
                    c.Strength = Math.Max(0.0, Math.Min(100.0, val)) / 100.0;
                    if (page != null) ConstraintsEngine.Solve(page);
                    InvalidateAndRefresh(primary);
                });
                cardStack.Children.Add(strengthField);

                // Specific Options per Constraint Type
                if (c.Type == AnimationConstraintType.Transform)
                {
                    var optRow = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 4, 0, 0) };
                    var chkX = new CheckBox { Content = "X", IsChecked = c.ConstrainX, Foreground = Brushes.White, FontSize = 10, Margin = new Thickness(0, 0, 10, 0) };
                    chkX.Checked += (s, e) => { c.ConstrainX = true; if (page != null) ConstraintsEngine.Solve(page); InvalidateAndRefresh(primary); };
                    chkX.Unchecked += (s, e) => { c.ConstrainX = false; if (page != null) ConstraintsEngine.Solve(page); InvalidateAndRefresh(primary); };
                    var chkY = new CheckBox { Content = "Y", IsChecked = c.ConstrainY, Foreground = Brushes.White, FontSize = 10 };
                    chkY.Checked += (s, e) => { c.ConstrainY = true; if (page != null) ConstraintsEngine.Solve(page); InvalidateAndRefresh(primary); };
                    chkY.Unchecked += (s, e) => { c.ConstrainY = false; if (page != null) ConstraintsEngine.Solve(page); InvalidateAndRefresh(primary); };
                    optRow.Children.Add(chkX);
                    optRow.Children.Add(chkY);
                    cardStack.Children.Add(optRow);
                }
                else if (c.Type == AnimationConstraintType.Distance)
                {
                    var distRow = new DockPanel { Margin = new Thickness(0, 4, 0, 0) };
                    var modeCombo = CreateModernComboBox(22, 70);
                    modeCombo.Items.Add(new ComboBoxItem { Content = "Exact", Tag = DistanceConstraintMode.Exact });
                    modeCombo.Items.Add(new ComboBoxItem { Content = "Maximum", Tag = DistanceConstraintMode.Closer, ToolTip = "Keep the object within this distance of its target" });
                    modeCombo.Items.Add(new ComboBoxItem { Content = "Minimum", Tag = DistanceConstraintMode.Further, ToolTip = "Keep the object at least this far from its target" });
                    modeCombo.SelectedIndex = (int)c.DistanceMode;
                    modeCombo.SelectionChanged += (s, e) =>
                    {
                        var mi = modeCombo.SelectedItem as ComboBoxItem;
                        if (mi != null && mi.Tag is DistanceConstraintMode)
                        {
                            c.DistanceMode = (DistanceConstraintMode)mi.Tag;
                            if (page != null) ConstraintsEngine.Solve(page);
                            InvalidateAndRefresh(primary);
                        }
                    };
                    DockPanel.SetDock(modeCombo, Dock.Left);
                    distRow.Children.Add(modeCombo);

                    var distField = ScrubControls.CreateScrubField("Dist", c.Distance, val =>
                    {
                        c.Distance = Math.Max(0.0, val);
                        if (page != null) ConstraintsEngine.Solve(page);
                        InvalidateAndRefresh(primary);
                    });
                    distRow.Children.Add(distField);
                    cardStack.Children.Add(distRow);
                }
                else if (c.Type == AnimationConstraintType.Translation)
                {
                    var optRow = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 4, 0, 0) };
                    var chkX = new CheckBox { Content = "X", IsChecked = c.ConstrainX, Foreground = Brushes.White, FontSize = 10, Margin = new Thickness(0, 0, 10, 0) };
                    chkX.Checked += (s, e) => { c.ConstrainX = true; if (page != null) ConstraintsEngine.Solve(page); InvalidateAndRefresh(primary); };
                    chkX.Unchecked += (s, e) => { c.ConstrainX = false; if (page != null) ConstraintsEngine.Solve(page); InvalidateAndRefresh(primary); };
                    var chkY = new CheckBox { Content = "Y", IsChecked = c.ConstrainY, Foreground = Brushes.White, FontSize = 10 };
                    chkY.Checked += (s, e) => { c.ConstrainY = true; if (page != null) ConstraintsEngine.Solve(page); InvalidateAndRefresh(primary); };
                    chkY.Unchecked += (s, e) => { c.ConstrainY = false; if (page != null) ConstraintsEngine.Solve(page); InvalidateAndRefresh(primary); };
                    optRow.Children.Add(chkX);
                    optRow.Children.Add(chkY);
                    cardStack.Children.Add(optRow);
                }
                else if (c.Type == AnimationConstraintType.Scale)
                {
                    var optRow = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 4, 0, 0) };
                    var chkX = new CheckBox { Content = "Scale X", IsChecked = c.ConstrainX, Foreground = Brushes.White, FontSize = 10, Margin = new Thickness(0, 0, 10, 0) };
                    chkX.Checked += (s, e) => { c.ConstrainX = true; if (page != null) ConstraintsEngine.Solve(page); InvalidateAndRefresh(primary); };
                    chkX.Unchecked += (s, e) => { c.ConstrainX = false; if (page != null) ConstraintsEngine.Solve(page); InvalidateAndRefresh(primary); };
                    var chkY = new CheckBox { Content = "Scale Y", IsChecked = c.ConstrainY, Foreground = Brushes.White, FontSize = 10 };
                    chkY.Checked += (s, e) => { c.ConstrainY = true; if (page != null) ConstraintsEngine.Solve(page); InvalidateAndRefresh(primary); };
                    chkY.Unchecked += (s, e) => { c.ConstrainY = false; if (page != null) ConstraintsEngine.Solve(page); InvalidateAndRefresh(primary); };
                    optRow.Children.Add(chkX);
                    optRow.Children.Add(chkY);
                    cardStack.Children.Add(optRow);
                }
                else if (c.Type == AnimationConstraintType.Rotation)
                {
                    var rotField = ScrubControls.CreateScrubField("Offset ∠", c.OffsetRotation, val =>
                    {
                        c.OffsetRotation = val;
                        if (page != null) ConstraintsEngine.Solve(page);
                        InvalidateAndRefresh(primary);
                    });
                    cardStack.Children.Add(rotField);
                }
                else if (c.Type == AnimationConstraintType.IK)
                {
                    var bRow = new Grid { Margin = new Thickness(0, 4, 0, 0) };
                    bRow.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                    bRow.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(4) });
                    bRow.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

                    var b1Field = ScrubControls.CreateScrubField("Bone 1", c.BoneLength1, val =>
                    {
                        c.BoneLength1 = Math.Max(0.0, val);
                        if (page != null) ConstraintsEngine.Solve(page);
                        InvalidateAndRefresh(primary);
                    });
                    Grid.SetColumn(b1Field, 0);
                    bRow.Children.Add(b1Field);

                    var b2Field = ScrubControls.CreateScrubField("Bone 2", c.BoneLength2, val =>
                    {
                        c.BoneLength2 = Math.Max(0.0, val);
                        if (page != null) ConstraintsEngine.Solve(page);
                        InvalidateAndRefresh(primary);
                    });
                    Grid.SetColumn(b2Field, 2);
                    bRow.Children.Add(b2Field);
                    cardStack.Children.Add(bRow);

                    var chkBend = new CheckBox { Content = "Invert Bend Direction", IsChecked = c.InvertBend, Foreground = Brushes.White, FontSize = 10, Margin = new Thickness(0, 4, 0, 0) };
                    chkBend.Checked += (s, e) => { c.InvertBend = true; if (page != null) ConstraintsEngine.Solve(page); InvalidateAndRefresh(primary); };
                    chkBend.Unchecked += (s, e) => { c.InvertBend = false; if (page != null) ConstraintsEngine.Solve(page); InvalidateAndRefresh(primary); };
                    cardStack.Children.Add(chkBend);
                }
                else if (c.Type == AnimationConstraintType.FollowPath)
                {
                    var pathDistField = ScrubControls.CreateScrubField("Distance %", c.PathDistance, val =>
                    {
                        c.PathDistance = Math.Max(0.0, val);
                        if (page != null) ConstraintsEngine.Solve(page);
                        InvalidateAndRefresh(primary);
                    });
                    cardStack.Children.Add(pathDistField);

                    var chkOrient = new CheckBox { Content = "Orient / Align to Path", IsChecked = c.OrientToPath, Foreground = Brushes.White, FontSize = 10, Margin = new Thickness(0, 4, 0, 0) };
                    chkOrient.Checked += (s, e) => { c.OrientToPath = true; if (page != null) ConstraintsEngine.Solve(page); InvalidateAndRefresh(primary); };
                    chkOrient.Unchecked += (s, e) => { c.OrientToPath = false; if (page != null) ConstraintsEngine.Solve(page); InvalidateAndRefresh(primary); };
                    cardStack.Children.Add(chkOrient);

                    var pathOffField = ScrubControls.CreateScrubField("Path Offset", c.PathOffset, val =>
                    {
                        c.PathOffset = val;
                        if (page != null) ConstraintsEngine.Solve(page);
                        InvalidateAndRefresh(primary);
                    });
                    cardStack.Children.Add(pathOffField);
                }
                else if (c.Type == AnimationConstraintType.Scroll)
                {
                    var dirCombo = CreateModernComboBox(22);
                    dirCombo.Items.Add(new ComboBoxItem { Content = "Vertical", Tag = ScrollConstraintDirection.Vertical });
                    dirCombo.Items.Add(new ComboBoxItem { Content = "Horizontal", Tag = ScrollConstraintDirection.Horizontal });
                    dirCombo.Items.Add(new ComboBoxItem { Content = "Both", Tag = ScrollConstraintDirection.Both });
                    dirCombo.SelectedIndex = (int)c.ScrollDirection;
                    dirCombo.SelectionChanged += (s, e) =>
                    {
                        var mi = dirCombo.SelectedItem as ComboBoxItem;
                        if (mi != null && mi.Tag is ScrollConstraintDirection)
                        {
                            c.ScrollDirection = (ScrollConstraintDirection)mi.Tag;
                            if (page != null) ConstraintsEngine.Solve(page);
                            InvalidateAndRefresh(primary);
                        }
                    };
                    cardStack.Children.Add(dirCombo);

                    var scrollOffField = ScrubControls.CreateScrubField("Offset", c.ScrollOffset, val =>
                    {
                        c.ScrollOffset = val;
                        if (page != null) ConstraintsEngine.Solve(page);
                        InvalidateAndRefresh(primary);
                    });
                    cardStack.Children.Add(scrollOffField);
                }

                card.Child = cardStack;
                constraintsContainer.Children.Add(card);
            }

            _propertyInspectorStack.Children.Add(constraintsContainer);
        }

        private void BuildSelectionColorsSection(IEnumerable<LayerNode> roots)
        {
            var colorTargets = new Dictionary<string, List<Action<string>>>(StringComparer.OrdinalIgnoreCase);
            var visited = new HashSet<LayerNode>();
            Action<LayerNode> collect = null;
            collect = layer =>
            {
                if (layer == null || !visited.Add(layer)) return;
                if (layer.Fills != null)
                {
                    foreach (var paint in layer.Fills)
                    {
                        if (paint == null) continue;
                        if (paint.Type == PaintType.Solid && !string.IsNullOrWhiteSpace(paint.ColorHex))
                        {
                            string key = NormalizeStyleColor(paint.ColorHex);
                            if (!colorTargets.ContainsKey(key)) colorTargets[key] = new List<Action<string>>();
                            var targetPaint = paint;
                            colorTargets[key].Add(hex => targetPaint.ColorHex = hex);
                        }
                        if (paint.GradientStops != null)
                        {
                            foreach (var stop in paint.GradientStops)
                            {
                                if (stop == null || string.IsNullOrWhiteSpace(stop.ColorHex)) continue;
                                string key = NormalizeStyleColor(stop.ColorHex);
                                if (!colorTargets.ContainsKey(key)) colorTargets[key] = new List<Action<string>>();
                                var targetStop = stop;
                                colorTargets[key].Add(hex => targetStop.ColorHex = hex);
                            }
                        }
                    }
                }
                if (layer.Strokes != null)
                {
                    foreach (var stroke in layer.Strokes)
                    {
                        var paint = stroke != null ? stroke.Paint : null;
                        if (paint == null || string.IsNullOrWhiteSpace(paint.ColorHex)) continue;
                        string key = NormalizeStyleColor(paint.ColorHex);
                        if (!colorTargets.ContainsKey(key)) colorTargets[key] = new List<Action<string>>();
                        var targetPaint = paint;
                        colorTargets[key].Add(hex => targetPaint.ColorHex = hex);
                    }
                }
                if (layer.Children != null)
                {
                    foreach (var child in layer.Children) collect(child);
                }
            };
            foreach (var root in roots ?? Enumerable.Empty<LayerNode>()) collect(root);
            if (colorTargets.Count == 0) return;

            _propertyInspectorStack.Children.Add(CreateInspectorSection("Selection colors"));
            foreach (var entry in colorTargets.OrderBy(p => p.Key, StringComparer.OrdinalIgnoreCase))
            {
                string originalHex = entry.Key;
                var targets = entry.Value;
                var row = new Border
                {
                    Background = new SolidColorBrush(Color.FromRgb(35, 40, 55)),
                    BorderBrush = new SolidColorBrush(Color.FromRgb(53, 61, 80)),
                    BorderThickness = new Thickness(1),
                    CornerRadius = new CornerRadius(5),
                    Padding = new Thickness(6, 5, 8, 5),
                    Margin = new Thickness(0, 0, 0, 5),
                    Cursor = Cursors.Hand,
                    ToolTip = "Change every matching color in this selection"
                };
                var rowGrid = new Grid();
                rowGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(26) });
                rowGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                rowGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
                var swatch = new Border
                {
                    Width = 20,
                    Height = 20,
                    CornerRadius = new CornerRadius(3),
                    Background = new SolidColorBrush(GpuRenderer.ParseHexColor(originalHex, 1.0)),
                    BorderBrush = new SolidColorBrush(Color.FromRgb(85, 95, 115)),
                    BorderThickness = new Thickness(1),
                    VerticalAlignment = VerticalAlignment.Center
                };
                Grid.SetColumn(swatch, 0);
                rowGrid.Children.Add(swatch);
                var colorName = new TextBlock
                {
                    Text = GetStyleColorName(originalHex),
                    Foreground = new SolidColorBrush(Color.FromRgb(235, 238, 244)),
                    FontSize = 10.5,
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(3, 0, 6, 0)
                };
                Grid.SetColumn(colorName, 1);
                rowGrid.Children.Add(colorName);
                var hexLabel = new TextBlock
                {
                    Text = originalHex.ToUpperInvariant(),
                    Foreground = new SolidColorBrush(Color.FromRgb(145, 159, 181)),
                    FontSize = 9.5,
                    VerticalAlignment = VerticalAlignment.Center
                };
                Grid.SetColumn(hexLabel, 2);
                rowGrid.Children.Add(hexLabel);
                row.Child = rowGrid;

                Action openPicker = () => ColorPickerPopup.ShowAt(row, originalHex, newHex =>
                {
                    foreach (var update in targets) update(newHex);
                    _sceneGraph.Synchronize(Document.GetActivePage());
                    History.MarkDirty();
                    RefreshCanvas();
                    RefreshPropertyInspector();
                });
                row.MouseLeftButtonUp += (s, e) => { e.Handled = true; openPicker(); };
                _propertyInspectorStack.Children.Add(row);
            }
        }

        private static string NormalizeStyleColor(string hex)
        {
            if (string.IsNullOrWhiteSpace(hex)) return "#D9D9D9";
            var value = hex.Trim();
            if (!value.StartsWith("#", StringComparison.Ordinal)) value = "#" + value;
            return value.ToUpperInvariant();
        }

        private static string GetStyleColorName(string hex)
        {
            switch (NormalizeStyleColor(hex))
            {
                case "#D9D9D9": case "#808080": case "#888888": return "Gray";
                case "#FF7A00": case "#FF8A00": case "#F97316": case "#EA580C": return "Orange";
                case "#FF0000": case "#EF4444": case "#DC2626": return "Red";
                case "#00FF00": case "#22C55E": case "#16A34A": return "Green";
                case "#0000FF": case "#3B82F6": case "#2563EB": return "Blue";
                case "#FFFF00": case "#EAB308": case "#FACC15": return "Yellow";
                case "#800080": case "#A855F7": case "#8B5CF6": return "Purple";
                case "#FFFFFF": case "#FBFAFA": return "White";
                case "#000000": return "Black";
                default: return "Color";
            }
        }

        private Border CreateDragGripHandle()
        {
            var grip = new Border
            {
                Width = 14,
                Height = 22,
                Background = Brushes.Transparent,
                Cursor = Cursors.SizeNS,
                ToolTip = "Drag to rearrange order",
                Margin = new Thickness(0, 0, 4, 0),
                Child = new TextBlock
                {
                    Text = "⋮⋮",
                    FontSize = 11,
                    Foreground = new SolidColorBrush(Color.FromRgb(110, 125, 155)),
                    HorizontalAlignment = HorizontalAlignment.Center,
                    VerticalAlignment = VerticalAlignment.Center
                }
            };
            return grip;
        }


        private void BuildImageAdjustmentsSection(LayerNode primary)
        {
            var paint = primary.GetPrimaryImagePaint();
            if (paint == null) return;

            _propertyInspectorStack.Children.Add(CreateInspectorSection("Image Adjustments"));

            var card = new Border
            {
                Background = KerfBrand.FigmaCardBrush,
                BorderBrush = KerfBrand.FigmaBorderBrush,
                BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(6),
                Padding = new Thickness(10, 8, 10, 8),
                Margin = new Thickness(0, 0, 0, 10)
            };
            var stack = new StackPanel();

            // 1. Crop Mode & Reset Crop Buttons
            var cropRow = new Grid { Margin = new Thickness(0, 0, 0, 8) };
            cropRow.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            cropRow.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(6) });
            cropRow.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

            var cropBtn = new Button
            {
                Content = _isImageCropping ? "✓ Done Cropping" : "✂ Crop Image",
                Height = 26,
                Background = _isImageCropping ? KerfBrand.MintBrush : KerfBrand.DarkSlateBrush,
                Foreground = _isImageCropping ? KerfBrand.TextBlackBrush : KerfBrand.TextWhiteBrush,
                BorderBrush = _isImageCropping ? KerfBrand.MintBrush : KerfBrand.FigmaBorderBrush,
                BorderThickness = new Thickness(1),
                Cursor = Cursors.Hand,
                ToolTip = "Toggle interactive on-canvas crop mode",
                Template = CreateRoundedButtonTemplate(6)
            };
            cropBtn.Click += (s, e) =>
            {
                if (_isImageCropping) ExitImageCropMode();
                else EnterImageCropMode(primary);
            };
            Grid.SetColumn(cropBtn, 0);
            cropRow.Children.Add(cropBtn);

            var resetCropBtn = CreateSmallButton("Reset Crop", "Reset image crop to full size", () =>
            {
                paint.CropRect = new Rect(0, 0, 1, 1);
                _sceneGraph.InvalidateNode(primary.Id);
                History.MarkDirty();
                RefreshCanvas();
                RefreshPropertyInspector();
            });
            resetCropBtn.Height = 26;
            resetCropBtn.Width = double.NaN;
            resetCropBtn.Padding = new Thickness(6, 0, 6, 0);
            Grid.SetColumn(resetCropBtn, 2);
            cropRow.Children.Add(resetCropBtn);
            stack.Children.Add(cropRow);

            // 2. Fill Mode ComboBox (Fill, Fit, Crop, Tile)
            var modeDock = new DockPanel { Margin = new Thickness(0, 0, 0, 8) };
            var modeLbl = new TextBlock
            {
                Text = "Mode",
                FontSize = 11,
                Foreground = KerfBrand.TextMutedBrush,
                Width = 75,
                VerticalAlignment = VerticalAlignment.Center
            };
            DockPanel.SetDock(modeLbl, Dock.Left);
            modeDock.Children.Add(modeLbl);

            var modeCombo = new ComboBox
            {
                Height = 24,
                VerticalAlignment = VerticalAlignment.Center
            };
            modeCombo.Items.Add("Fill");
            modeCombo.Items.Add("Fit");
            modeCombo.Items.Add("Crop");
            modeCombo.Items.Add("Tile");
            modeCombo.SelectedItem = string.IsNullOrEmpty(paint.ImageFillMode) ? "Fill" : paint.ImageFillMode;
            modeCombo.SelectionChanged += (s, e) =>
            {
                if (modeCombo.SelectedItem != null)
                {
                    paint.ImageFillMode = modeCombo.SelectedItem.ToString();
                    _sceneGraph.InvalidateNode(primary.Id);
                    History.MarkDirty();
                    RefreshCanvas();
                }
            };
            modeDock.Children.Add(modeCombo);
            stack.Children.Add(modeDock);

            // Separator before adjustments
            var sep = CreateSeparator();
            sep.Margin = new Thickness(0, 4, 0, 8);
            stack.Children.Add(sep);

            // 3. Figma Adjustment Sliders
            stack.Children.Add(CreateImageAdjustmentRow("Exposure", paint.Exposure, -100, 100, (v) =>
            {
                paint.Exposure = Math.Round(v);
                _sceneGraph.InvalidateNode(primary.Id);
                History.MarkDirty();
                RefreshCanvas();
            }));

            stack.Children.Add(CreateImageAdjustmentRow("Contrast", paint.Contrast, -100, 100, (v) =>
            {
                paint.Contrast = Math.Round(v);
                _sceneGraph.InvalidateNode(primary.Id);
                History.MarkDirty();
                RefreshCanvas();
            }));

            stack.Children.Add(CreateImageAdjustmentRow("Saturation", paint.Saturation, -100, 100, (v) =>
            {
                paint.Saturation = Math.Round(v);
                _sceneGraph.InvalidateNode(primary.Id);
                History.MarkDirty();
                RefreshCanvas();
            }));

            stack.Children.Add(CreateImageAdjustmentRow("Temperature", paint.Temperature, -100, 100, (v) =>
            {
                paint.Temperature = Math.Round(v);
                _sceneGraph.InvalidateNode(primary.Id);
                History.MarkDirty();
                RefreshCanvas();
            }));

            stack.Children.Add(CreateImageAdjustmentRow("Tint", paint.Tint, -100, 100, (v) =>
            {
                paint.Tint = Math.Round(v);
                _sceneGraph.InvalidateNode(primary.Id);
                History.MarkDirty();
                RefreshCanvas();
            }));

            stack.Children.Add(CreateImageAdjustmentRow("Highlights", paint.Highlights, -100, 100, (v) =>
            {
                paint.Highlights = Math.Round(v);
                _sceneGraph.InvalidateNode(primary.Id);
                History.MarkDirty();
                RefreshCanvas();
            }));

            stack.Children.Add(CreateImageAdjustmentRow("Shadows", paint.Shadows, -100, 100, (v) =>
            {
                paint.Shadows = Math.Round(v);
                _sceneGraph.InvalidateNode(primary.Id);
                History.MarkDirty();
                RefreshCanvas();
            }));

            // 4. Reset All Adjustments button
            var resetAllBtn = CreateSmallButton("Reset All Adjustments", "Reset all image adjustments back to defaults", () =>
            {
                paint.Exposure = 0;
                paint.Contrast = 0;
                paint.Saturation = 0;
                paint.Temperature = 0;
                paint.Tint = 0;
                paint.Highlights = 0;
                paint.Shadows = 0;
                _sceneGraph.InvalidateNode(primary.Id);
                History.MarkDirty();
                RefreshCanvas();
                RefreshPropertyInspector();
            });
            resetAllBtn.Height = 24;
            resetAllBtn.Width = double.NaN;
            resetAllBtn.Padding = new Thickness(8, 0, 8, 0);
            resetAllBtn.Margin = new Thickness(0, 6, 0, 0);
            stack.Children.Add(resetAllBtn);

            card.Child = stack;
            _propertyInspectorStack.Children.Add(card);
        }

        private FrameworkElement CreateImageAdjustmentRow(string label, double currentVal, double min, double max, Action<double> onChanged)
        {
            var dock = new DockPanel { Margin = new Thickness(0, 0, 0, 6) };
            var lbl = new TextBlock
            {
                Text = label,
                FontSize = 11,
                Foreground = KerfBrand.TextMutedBrush,
                Width = 75,
                VerticalAlignment = VerticalAlignment.Center
            };
            DockPanel.SetDock(lbl, Dock.Left);
            dock.Children.Add(lbl);

            var valTxt = new TextBlock
            {
                Text = currentVal > 0 ? ("+" + currentVal.ToString("F0")) : currentVal.ToString("F0"),
                FontSize = 11,
                Foreground = KerfBrand.TextWhiteBrush,
                Width = 32,
                TextAlignment = TextAlignment.Right,
                VerticalAlignment = VerticalAlignment.Center,
                Margin = new Thickness(4, 0, 0, 0)
            };
            DockPanel.SetDock(valTxt, Dock.Right);
            dock.Children.Add(valTxt);

            var slider = new Slider
            {
                Minimum = min,
                Maximum = max,
                Value = currentVal,
                VerticalAlignment = VerticalAlignment.Center,
                SmallChange = 1,
                LargeChange = 10
            };
            slider.ValueChanged += (s, e) =>
            {
                valTxt.Text = slider.Value > 0 ? ("+" + slider.Value.ToString("F0")) : slider.Value.ToString("F0");
                onChanged(slider.Value);
            };
            dock.Children.Add(slider);

            return dock;
        }

        private void BuildFillsSection(LayerNode primary)
        {
            if (primary.Fills == null) primary.Fills = new List<Paint>();

            _propertyInspectorStack.Children.Add(CreateInspectorSectionWithAdd("Fills", () =>
            {
                primary.Fills.Add(Paint.Solid("#D9D9D9"));
                InvalidateAndRefresh(primary);
                RefreshPropertyInspector();
            }));

            if (primary.Fills.Count == 0)
            {
                var emptyBtn = CreateSmallButton("+ Add Fill", "Add solid or gradient fill", () =>
                {
                    primary.Fills.Add(Paint.Solid("#D9D9D9"));
                    InvalidateAndRefresh(primary);
                    RefreshPropertyInspector();
                });
                _propertyInspectorStack.Children.Add(emptyBtn);
                return;
            }

            var fillsContainer = new StackPanel();
            var fillCards = new List<Border>();
            for (int i = 0; i < primary.Fills.Count; i++)
            {
                var card = BuildFillCard(primary, primary.Fills[i], i, fillsContainer, fillCards);
                fillCards.Add(card);
                fillsContainer.Children.Add(card);
            }

            _propertyInspectorStack.Children.Add(fillsContainer);
        }

        private Border BuildFillCard(LayerNode primary, Paint fill, int fillIdx, StackPanel fillsContainer, List<Border> fillCards)
        {
            var card = new Border
            {
                Background = new SolidColorBrush(Color.FromRgb(24, 28, 40)),
                BorderBrush = new SolidColorBrush(Color.FromRgb(38, 46, 66)),
                BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(5),
                Padding = new Thickness(fill.IsExpanded ? 6 : 4, fill.IsExpanded ? 6 : 2, fill.IsExpanded ? 6 : 4, fill.IsExpanded ? 6 : 2),
                Margin = new Thickness(0, 0, 0, 6),
                RenderTransform = new TranslateTransform(0, 0)
            };

            var cardStack = new StackPanel();

            // 1. Grip Handle for Drag & Drop
            var grip = CreateDragGripHandle();
            grip.PreviewMouseLeftButtonDown += (s, e) =>
            {
                int origIndex = fillIdx;
                int currentSlot = origIndex;
                var snapshotFills = new List<Paint>(primary.Fills);
                Point startMouse = e.GetPosition(fillsContainer);

                Panel.SetZIndex(card, 100);
                card.Opacity = 0.92;
                card.BorderBrush = new SolidColorBrush(Color.FromRgb(70, 239, 177));
                grip.CaptureMouse();

                MouseEventHandler moveHandler = null;
                MouseButtonEventHandler upHandler = null;

                moveHandler = (sender, me) =>
                {
                    if (me.LeftButton != MouseButtonState.Pressed || !grip.IsMouseCaptured) return;

                    Point curMouse = me.GetPosition(fillsContainer);
                    double deltaY = curMouse.Y - startMouse.Y;

                    var trans = card.RenderTransform as TranslateTransform;
                    if (trans != null) trans.Y = deltaY;

                    int count = fillCards.Count;
                    if (count < 2) return;

                    double[] cardTops = new double[count];
                    double[] cardHeights = new double[count];
                    double accY = 0;
                    for (int k = 0; k < count; k++)
                    {
                        cardTops[k] = accY;
                        double h = fillCards[k].ActualHeight > 0 ? fillCards[k].ActualHeight : 32.0;
                        cardHeights[k] = h;
                        accY += h + 6.0;
                    }

                    double draggedCenter = cardTops[origIndex] + deltaY + cardHeights[origIndex] / 2.0;
                    int targetSlot = origIndex;
                    for (int slot = 0; slot < count; slot++)
                    {
                        if (draggedCenter < cardTops[slot] + cardHeights[slot])
                        {
                            targetSlot = slot;
                            break;
                        }
                        if (slot == count - 1)
                        {
                            targetSlot = count - 1;
                        }
                    }
                    targetSlot = Math.Max(0, Math.Min(count - 1, targetSlot));

                    if (targetSlot != currentSlot)
                    {
                        currentSlot = targetSlot;

                        // Smoothly relocate other cards just like home screen apps
                        double shiftAmt = cardHeights[origIndex] + 6.0;
                        for (int k = 0; k < count; k++)
                        {
                            if (k == origIndex) continue;

                            double targetShift = 0.0;
                            if (origIndex < currentSlot)
                            {
                                if (k > origIndex && k <= currentSlot) targetShift = -shiftAmt;
                            }
                            else if (origIndex > currentSlot)
                            {
                                if (k >= currentSlot && k < origIndex) targetShift = +shiftAmt;
                            }

                            var otherTrans = fillCards[k].RenderTransform as TranslateTransform;
                            if (otherTrans != null)
                            {
                                var anim = new DoubleAnimation
                                {
                                    To = targetShift,
                                    Duration = TimeSpan.FromMilliseconds(160),
                                    EasingFunction = new QuadraticEase { EasingMode = EasingMode.EaseOut }
                                };
                                otherTrans.BeginAnimation(TranslateTransform.YProperty, anim);
                            }
                        }

                        // Real-time canvas color update depending on new order of colors
                        var previewFills = new List<Paint>();
                        for (int k = 0; k < snapshotFills.Count; k++)
                        {
                            if (k != origIndex) previewFills.Add(snapshotFills[k]);
                        }
                        previewFills.Insert(Math.Min(previewFills.Count, currentSlot), snapshotFills[origIndex]);

                        primary.Fills = previewFills;
                        InvalidateAndRefresh(primary);
                    }
                };

                upHandler = (sender, ue) =>
                {
                    grip.PreviewMouseMove -= moveHandler;
                    grip.PreviewMouseLeftButtonUp -= upHandler;
                    grip.ReleaseMouseCapture();

                    card.Opacity = 1.0;
                    card.BorderBrush = new SolidColorBrush(Color.FromRgb(38, 46, 66));
                    Panel.SetZIndex(card, 0);

                    // Final commit
                    var finalFills = new List<Paint>();
                    for (int k = 0; k < snapshotFills.Count; k++)
                    {
                        if (k != origIndex) finalFills.Add(snapshotFills[k]);
                    }
                    finalFills.Insert(Math.Min(finalFills.Count, currentSlot), snapshotFills[origIndex]);

                    primary.Fills = finalFills;
                    InvalidateAndRefresh(primary);
                    RefreshPropertyInspector();
                };

                grip.PreviewMouseMove += moveHandler;
                grip.PreviewMouseLeftButtonUp += upHandler;
            };

            // 2. Swatch
            var swatch = new Border
            {
                Width = 20,
                Height = 20,
                CornerRadius = new CornerRadius(3),
                BorderBrush = new SolidColorBrush(Color.FromRgb(60, 70, 95)),
                BorderThickness = new Thickness(1),
                Margin = new Thickness(2, 0, 6, 0),
                Cursor = Cursors.Hand,
                ToolTip = "Choose fill color/gradient"
            };
            if (fill.Type == PaintType.Solid)
            {
                swatch.Background = new SolidColorBrush(GpuRenderer.ParseHexColor(fill.ColorHex, fill.Opacity));
            }
            else if (fill.Type == PaintType.LinearGradient)
            {
                var lgb = new LinearGradientBrush { StartPoint = new Point(0, 0), EndPoint = new Point(1, 0) };
                GpuRenderer.PopulateGradientStops(lgb.GradientStops, fill);
                swatch.Background = lgb;
            }
            else
            {
                var rgb = new RadialGradientBrush { Center = new Point(0.5, 0.5), GradientOrigin = new Point(0.5, 0.5), RadiusX = 0.5, RadiusY = 0.5 };
                GpuRenderer.PopulateGradientStops(rgb.GradientStops, fill);
                swatch.Background = rgb;
            }

            Action openColorOrExpand = new Action(() =>
            {
                if (fill.Type != PaintType.Solid)
                {
                    // Automatic expansion for gradient options!
                    fill.IsExpanded = true;
                    SetEditingGradient(primary, fill);
                    InvalidateAndRefresh(primary);
                    RefreshPropertyInspector();
                }
                else
                {
                    ColorPickerPopup.ShowAt(swatch, fill.ColorHex ?? "#D9D9D9", newHex =>
                    {
                        fill.ColorHex = newHex;
                        InvalidateAndRefresh(primary);
                        RefreshPropertyInspector();
                    });
                }
            });

            swatch.MouseLeftButtonUp += (s, e) =>
            {
                e.Handled = true;
                openColorOrExpand();
            };

            // 3. Eye Button
            var eyeBtn = new Button
            {
                Template = CreateRoundedButtonTemplate(4),
                Content = fill.Enabled ? "👁" : "—",
                FontSize = 10,
                Width = 20,
                Height = 20,
                Background = fill.Enabled ? new SolidColorBrush(Color.FromRgb(35, 42, 60)) : Brushes.Transparent,
                Foreground = fill.Enabled ? Brushes.White : new SolidColorBrush(Color.FromRgb(100, 110, 130)),
                BorderThickness = new Thickness(0),
                Cursor = Cursors.Hand,
                ToolTip = fill.Enabled ? "Disable fill" : "Enable fill",
                Margin = new Thickness(2, 0, 2, 0)
            };
            eyeBtn.Click += (s, e) =>
            {
                fill.Enabled = !fill.Enabled;
                InvalidateAndRefresh(primary);
                RefreshPropertyInspector();
            };

            // 4. Chevron Button
            var chevronBtn = new Button
            {
                Template = CreateRoundedButtonTemplate(4),
                Content = fill.IsExpanded ? "▼" : "▶",
                FontSize = 8.5,
                Width = 18,
                Height = 20,
                Background = Brushes.Transparent,
                Foreground = new SolidColorBrush(Color.FromRgb(140, 160, 195)),
                BorderThickness = new Thickness(0),
                Cursor = Cursors.Hand,
                ToolTip = fill.IsExpanded ? "Collapse fill attributes" : "Expand all fill options"
            };
            chevronBtn.Click += (s, e) =>
            {
                fill.IsExpanded = !fill.IsExpanded;
                if (fill.IsExpanded && fill.Type != PaintType.Solid)
                {
                    SetEditingGradient(primary, fill);
                }
                RefreshPropertyInspector();
            };

            // 5. Delete Button
            var delBtn = new Button
            {
                Template = CreateRoundedButtonTemplate(4),
                Content = "✕",
                FontSize = 9.5,
                Width = 18,
                Height = 20,
                Background = Brushes.Transparent,
                Foreground = new SolidColorBrush(Color.FromRgb(140, 150, 170)),
                BorderThickness = new Thickness(0),
                Cursor = Cursors.Hand,
                ToolTip = "Remove fill"
            };
            delBtn.Click += (s, e) =>
            {
                if (fillIdx < primary.Fills.Count)
                {
                    primary.Fills.RemoveAt(fillIdx);
                    InvalidateAndRefresh(primary);
                    RefreshPropertyInspector();
                }
            };

            if (!fill.IsExpanded)
            {
                // SINGLE LINE LIST ITEM (Compact view with editable color only)
                var row = new DockPanel { LastChildFill = true, Height = 22 };
                DockPanel.SetDock(grip, Dock.Left);
                row.Children.Add(grip);

                DockPanel.SetDock(swatch, Dock.Left);
                row.Children.Add(swatch);

                DockPanel.SetDock(delBtn, Dock.Right);
                row.Children.Add(delBtn);

                DockPanel.SetDock(chevronBtn, Dock.Right);
                row.Children.Add(chevronBtn);

                DockPanel.SetDock(eyeBtn, Dock.Right);
                row.Children.Add(eyeBtn);

                var opText = new TextBlock
                {
                    Text = Math.Round(fill.Opacity * 100) + "%",
                    FontSize = 10,
                    Foreground = new SolidColorBrush(Color.FromRgb(140, 160, 195)),
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(4, 0, 6, 0),
                    Width = 36,
                    TextAlignment = TextAlignment.Right,
                    Cursor = Cursors.Hand,
                    ToolTip = "Click to edit opacity"
                };
                opText.MouseLeftButtonUp += (s, e) =>
                {
                    fill.IsExpanded = true;
                    RefreshPropertyInspector();
                };
                DockPanel.SetDock(opText, Dock.Right);
                row.Children.Add(opText);

                string labelText = (fill.Type == PaintType.Solid)
                    ? (fill.ColorHex ?? "#D9D9D9").ToUpper()
                    : ((fill.Type == PaintType.LinearGradient) ? "Linear Gradient" : "Radial Gradient");

                var labelBlock = new TextBlock
                {
                    Text = labelText,
                    FontSize = 10,
                    FontWeight = (fill.Type == PaintType.Solid) ? FontWeights.Normal : FontWeights.SemiBold,
                    Foreground = (fill.Type == PaintType.Solid) ? new SolidColorBrush(Color.FromRgb(215, 225, 245)) : new SolidColorBrush(Color.FromRgb(56, 189, 248)),
                    VerticalAlignment = VerticalAlignment.Center,
                    Cursor = Cursors.Hand,
                    ToolTip = (fill.Type != PaintType.Solid) ? "Click to open gradient options" : "Click to choose color"
                };
                labelBlock.MouseLeftButtonUp += (s, e) =>
                {
                    e.Handled = true;
                    openColorOrExpand();
                };
                row.Children.Add(labelBlock);

                card.Child = row;
                return card;
            }

            // EXPANDED VIEW WITH ALL OPTIONS
            var topRow = new DockPanel { LastChildFill = true, Margin = new Thickness(0, 0, 0, 6) };
            DockPanel.SetDock(grip, Dock.Left);
            topRow.Children.Add(grip);

            DockPanel.SetDock(swatch, Dock.Left);
            topRow.Children.Add(swatch);

            DockPanel.SetDock(delBtn, Dock.Right);
            topRow.Children.Add(delBtn);

            DockPanel.SetDock(chevronBtn, Dock.Right);
            topRow.Children.Add(chevronBtn);

            DockPanel.SetDock(eyeBtn, Dock.Right);
            topRow.Children.Add(eyeBtn);

            var typeCombo = CreateModernComboBox(22);
            typeCombo.Margin = new Thickness(2, 0, 4, 0);
            typeCombo.Items.Add(CreateModernComboBoxItem("Solid"));
            typeCombo.Items.Add(CreateModernComboBoxItem("Linear Gradient"));
            typeCombo.Items.Add(CreateModernComboBoxItem("Radial Gradient"));
            typeCombo.SelectedIndex = (fill.Type == PaintType.LinearGradient) ? 1 : (fill.Type == PaintType.RadialGradient ? 2 : 0);
            typeCombo.SelectionChanged += (s, e) =>
            {
                if (typeCombo.SelectedIndex == 1)
                {
                    fill.Type = PaintType.LinearGradient;
                    if (fill.GradientStops == null || fill.GradientStops.Count == 0)
                    {
                        fill.GradientStops = new List<GradientStopData>
                        {
                            new GradientStopData(0.0, fill.ColorHex ?? "#D9D9D9", 1.0),
                            new GradientStopData(1.0, "#4B5563", 1.0)
                        };
                    }
                    fill.IsExpanded = true;
                    SetEditingGradient(primary, fill);
                }
                else if (typeCombo.SelectedIndex == 2)
                {
                    fill.Type = PaintType.RadialGradient;
                    if (fill.GradientStops == null || fill.GradientStops.Count == 0)
                    {
                        fill.GradientStops = new List<GradientStopData>
                        {
                            new GradientStopData(0.0, fill.ColorHex ?? "#D9D9D9", 1.0),
                            new GradientStopData(1.0, "#1F2937", 1.0)
                        };
                    }
                    fill.IsExpanded = true;
                    SetEditingGradient(primary, fill);
                }
                else
                {
                    fill.Type = PaintType.Solid;
                    if (_editingGradientPaint == fill) ClearEditingGradient();
                }
                InvalidateAndRefresh(primary);
                RefreshPropertyInspector();
            };
            topRow.Children.Add(typeCombo);
            cardStack.Children.Add(topRow);

            var opRow = ScrubControls.CreateSmoothSlider("Opacity", Math.Round(fill.Opacity * 100), 0, 100, val =>
            {
                fill.Opacity = val / 100.0;
                InvalidateAndRefresh(primary);
            }, "%");
            cardStack.Children.Add(opRow);

            if (fill.Type == PaintType.LinearGradient || fill.Type == PaintType.RadialGradient)
            {
                bool isEditingThis = (_editingGradientPaint == fill && _editingGradientLayer == primary);

                var toggleRow = new DockPanel { Margin = new Thickness(0, 2, 0, 4) };
                var rollerBtn = new Button
                {
                    Template = CreateRoundedButtonTemplate(6),
                    Content = isEditingThis ? "● Canvas Roller Active [Done]" : "✏ Edit on Canvas",
                    FontSize = 10,
                    FontWeight = FontWeights.SemiBold,
                    Height = 22,
                    Background = isEditingThis ? new SolidColorBrush(Color.FromRgb(20, 50, 110)) : new SolidColorBrush(Color.FromRgb(30, 36, 52)),
                    Foreground = isEditingThis ? new SolidColorBrush(Color.FromRgb(56, 189, 248)) : new SolidColorBrush(Color.FromRgb(150, 165, 195)),
                    BorderBrush = isEditingThis ? new SolidColorBrush(Color.FromRgb(56, 189, 248)) : new SolidColorBrush(Color.FromRgb(48, 58, 80)),
                    BorderThickness = new Thickness(1),
                    Cursor = Cursors.Hand,
                    Padding = new Thickness(6, 0, 6, 0),
                    ToolTip = isEditingThis ? "Click to exit on-canvas gradient editing (or press Esc)" : "Activate Figma on-canvas gradient handles & rollers"
                };

                GradientRampControl rampCtrl = null;
                rollerBtn.Click += (s, e) =>
                {
                    if (_editingGradientPaint == fill)
                        ClearEditingGradient();
                    else
                        SetEditingGradient(primary, fill, rampCtrl);
                    RefreshPropertyInspector();
                };
                toggleRow.Children.Add(rollerBtn);
                cardStack.Children.Add(toggleRow);

                rampCtrl = new GradientRampControl(fill, () =>
                {
                    SetEditingGradient(primary, fill, rampCtrl);
                    InvalidateAndRefresh(primary);
                }, () =>
                {
                    SetEditingGradient(primary, fill, rampCtrl);
                    InvalidateAndRefresh(primary);
                    RefreshPropertyInspector();
                });

                rampCtrl.PreviewMouseDown += (s, e) =>
                {
                    if (_editingGradientPaint != fill)
                    {
                        SetEditingGradient(primary, fill, rampCtrl);
                        RefreshPropertyInspector();
                    }
                };

                cardStack.Children.Add(rampCtrl);
            }

            card.Child = cardStack;
            return card;
        }

        private void BuildStrokesSection(LayerNode primary)
        {
            if (primary.Strokes == null) primary.Strokes = new List<StrokeData>();

            _propertyInspectorStack.Children.Add(CreateInspectorSectionWithAdd("Strokes", () =>
            {
                primary.Strokes.Add(new StrokeData { Paint = Paint.Solid("#000000"), Width = 1.0, Enabled = true });
                InvalidateAndRefresh(primary);
                RefreshPropertyInspector();
            }));

            if (primary.Strokes.Count == 0)
            {
                var emptyBtn = CreateSmallButton("+ Add Stroke", "Add border stroke", () =>
                {
                    primary.Strokes.Add(new StrokeData { Paint = Paint.Solid("#000000"), Width = 1.0, Enabled = true });
                    InvalidateAndRefresh(primary);
                    RefreshPropertyInspector();
                });
                _propertyInspectorStack.Children.Add(emptyBtn);
                return;
            }

            var strokesContainer = new StackPanel();
            var strokeCards = new List<Border>();
            for (int i = 0; i < primary.Strokes.Count; i++)
            {
                var card = BuildStrokeCard(primary, primary.Strokes[i], i, strokesContainer, strokeCards);
                strokeCards.Add(card);
                strokesContainer.Children.Add(card);
            }

            _propertyInspectorStack.Children.Add(strokesContainer);
        }

        private Border BuildStrokeCard(LayerNode primary, StrokeData stroke, int strokeIdx, StackPanel strokesContainer, List<Border> strokeCards)
        {
            if (stroke.Paint == null) stroke.Paint = Paint.Solid("#000000");

            var card = new Border
            {
                Background = new SolidColorBrush(Color.FromRgb(24, 28, 40)),
                BorderBrush = new SolidColorBrush(Color.FromRgb(38, 46, 66)),
                BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(5),
                Padding = new Thickness(stroke.IsExpanded ? 6 : 4, stroke.IsExpanded ? 6 : 2, stroke.IsExpanded ? 6 : 4, stroke.IsExpanded ? 6 : 2),
                Margin = new Thickness(0, 0, 0, 6),
                RenderTransform = new TranslateTransform(0, 0)
            };

            var cardStack = new StackPanel();

            // 1. Grip Handle
            var grip = CreateDragGripHandle();
            grip.PreviewMouseLeftButtonDown += (s, e) =>
            {
                int origIndex = strokeIdx;
                int currentSlot = origIndex;
                var snapshotStrokes = new List<StrokeData>(primary.Strokes);
                Point startMouse = e.GetPosition(strokesContainer);

                Panel.SetZIndex(card, 100);
                card.Opacity = 0.92;
                card.BorderBrush = new SolidColorBrush(Color.FromRgb(70, 239, 177));
                grip.CaptureMouse();

                MouseEventHandler moveHandler = null;
                MouseButtonEventHandler upHandler = null;

                moveHandler = (sender, me) =>
                {
                    if (me.LeftButton != MouseButtonState.Pressed || !grip.IsMouseCaptured) return;

                    Point curMouse = me.GetPosition(strokesContainer);
                    double deltaY = curMouse.Y - startMouse.Y;

                    var trans = card.RenderTransform as TranslateTransform;
                    if (trans != null) trans.Y = deltaY;

                    int count = strokeCards.Count;
                    if (count < 2) return;

                    double[] cardTops = new double[count];
                    double[] cardHeights = new double[count];
                    double accY = 0;
                    for (int k = 0; k < count; k++)
                    {
                        cardTops[k] = accY;
                        double h = strokeCards[k].ActualHeight > 0 ? strokeCards[k].ActualHeight : 32.0;
                        cardHeights[k] = h;
                        accY += h + 6.0;
                    }

                    double draggedCenter = cardTops[origIndex] + deltaY + cardHeights[origIndex] / 2.0;
                    int targetSlot = origIndex;
                    for (int slot = 0; slot < count; slot++)
                    {
                        if (draggedCenter < cardTops[slot] + cardHeights[slot])
                        {
                            targetSlot = slot;
                            break;
                        }
                        if (slot == count - 1)
                        {
                            targetSlot = count - 1;
                        }
                    }
                    targetSlot = Math.Max(0, Math.Min(count - 1, targetSlot));

                    if (targetSlot != currentSlot)
                    {
                        currentSlot = targetSlot;

                        // Smoothly relocate other cards just like home screen apps
                        double shiftAmt = cardHeights[origIndex] + 6.0;
                        for (int k = 0; k < count; k++)
                        {
                            if (k == origIndex) continue;

                            double targetShift = 0.0;
                            if (origIndex < currentSlot)
                            {
                                if (k > origIndex && k <= currentSlot) targetShift = -shiftAmt;
                            }
                            else if (origIndex > currentSlot)
                            {
                                if (k >= currentSlot && k < origIndex) targetShift = +shiftAmt;
                            }

                            var otherTrans = strokeCards[k].RenderTransform as TranslateTransform;
                            if (otherTrans != null)
                            {
                                var anim = new DoubleAnimation
                                {
                                    To = targetShift,
                                    Duration = TimeSpan.FromMilliseconds(160),
                                    EasingFunction = new QuadraticEase { EasingMode = EasingMode.EaseOut }
                                };
                                otherTrans.BeginAnimation(TranslateTransform.YProperty, anim);
                            }
                        }

                        // Real-time canvas stroke update depending on new order of strokes
                        var previewStrokes = new List<StrokeData>();
                        for (int k = 0; k < snapshotStrokes.Count; k++)
                        {
                            if (k != origIndex) previewStrokes.Add(snapshotStrokes[k]);
                        }
                        previewStrokes.Insert(Math.Min(previewStrokes.Count, currentSlot), snapshotStrokes[origIndex]);

                        primary.Strokes = previewStrokes;
                        InvalidateAndRefresh(primary);
                    }
                };

                upHandler = (sender, ue) =>
                {
                    grip.PreviewMouseMove -= moveHandler;
                    grip.PreviewMouseLeftButtonUp -= upHandler;
                    grip.ReleaseMouseCapture();

                    card.Opacity = 1.0;
                    card.BorderBrush = new SolidColorBrush(Color.FromRgb(38, 46, 66));
                    Panel.SetZIndex(card, 0);

                    // Final commit
                    var finalStrokes = new List<StrokeData>();
                    for (int k = 0; k < snapshotStrokes.Count; k++)
                    {
                        if (k != origIndex) finalStrokes.Add(snapshotStrokes[k]);
                    }
                    finalStrokes.Insert(Math.Min(finalStrokes.Count, currentSlot), snapshotStrokes[origIndex]);

                    primary.Strokes = finalStrokes;
                    InvalidateAndRefresh(primary);
                    RefreshPropertyInspector();
                };

                grip.PreviewMouseMove += moveHandler;
                grip.PreviewMouseLeftButtonUp += upHandler;
            };

            // 2. Swatch
            var swatch = new Border
            {
                Width = 20,
                Height = 20,
                CornerRadius = new CornerRadius(3),
                BorderBrush = new SolidColorBrush(Color.FromRgb(60, 70, 95)),
                BorderThickness = new Thickness(1),
                Margin = new Thickness(2, 0, 6, 0),
                Cursor = Cursors.Hand,
                ToolTip = "Choose stroke color/gradient"
            };
            if (stroke.Paint.Type == PaintType.Solid)
            {
                swatch.Background = new SolidColorBrush(GpuRenderer.ParseHexColor(stroke.Paint.ColorHex, stroke.Paint.Opacity));
            }
            else if (stroke.Paint.Type == PaintType.LinearGradient)
            {
                var lgb = new LinearGradientBrush { StartPoint = new Point(0, 0), EndPoint = new Point(1, 0) };
                GpuRenderer.PopulateGradientStops(lgb.GradientStops, stroke.Paint);
                swatch.Background = lgb;
            }
            else
            {
                var rgb = new RadialGradientBrush { Center = new Point(0.5, 0.5), GradientOrigin = new Point(0.5, 0.5), RadiusX = 0.5, RadiusY = 0.5 };
                GpuRenderer.PopulateGradientStops(rgb.GradientStops, stroke.Paint);
                swatch.Background = rgb;
            }

            Action openStrokeColorOrExpand = new Action(() =>
            {
                if (stroke.Paint.Type != PaintType.Solid)
                {
                    stroke.IsExpanded = true;
                    SetEditingGradient(primary, stroke.Paint);
                    InvalidateAndRefresh(primary);
                    RefreshPropertyInspector();
                }
                else
                {
                    ColorPickerPopup.ShowAt(swatch, stroke.Paint.ColorHex ?? "#000000", newHex =>
                    {
                        stroke.Paint.ColorHex = newHex;
                        InvalidateAndRefresh(primary);
                        RefreshPropertyInspector();
                    });
                }
            });

            swatch.MouseLeftButtonUp += (s, e) =>
            {
                e.Handled = true;
                openStrokeColorOrExpand();
            };

            // 3. Eye Button
            var eyeBtn = new Button
            {
                Template = CreateRoundedButtonTemplate(4),
                Content = stroke.Enabled ? "👁" : "—",
                FontSize = 10,
                Width = 20,
                Height = 20,
                Background = stroke.Enabled ? new SolidColorBrush(Color.FromRgb(35, 42, 60)) : Brushes.Transparent,
                Foreground = stroke.Enabled ? Brushes.White : new SolidColorBrush(Color.FromRgb(100, 110, 130)),
                BorderThickness = new Thickness(0),
                Cursor = Cursors.Hand,
                ToolTip = stroke.Enabled ? "Disable stroke" : "Enable stroke",
                Margin = new Thickness(2, 0, 2, 0)
            };
            eyeBtn.Click += (s, e) =>
            {
                stroke.Enabled = !stroke.Enabled;
                InvalidateAndRefresh(primary);
                RefreshPropertyInspector();
            };

            // 4. Chevron Button
            var chevronBtn = new Button
            {
                Template = CreateRoundedButtonTemplate(4),
                Content = stroke.IsExpanded ? "▼" : "▶",
                FontSize = 8.5,
                Width = 18,
                Height = 20,
                Background = Brushes.Transparent,
                Foreground = new SolidColorBrush(Color.FromRgb(140, 160, 195)),
                BorderThickness = new Thickness(0),
                Cursor = Cursors.Hand,
                ToolTip = stroke.IsExpanded ? "Collapse stroke attributes" : "Expand all stroke options"
            };
            chevronBtn.Click += (s, e) =>
            {
                stroke.IsExpanded = !stroke.IsExpanded;
                if (stroke.IsExpanded && stroke.Paint.Type != PaintType.Solid)
                {
                    SetEditingGradient(primary, stroke.Paint);
                }
                RefreshPropertyInspector();
            };

            // 5. Delete Button
            var delBtn = new Button
            {
                Template = CreateRoundedButtonTemplate(4),
                Content = "✕",
                FontSize = 9.5,
                Width = 18,
                Height = 20,
                Background = Brushes.Transparent,
                Foreground = new SolidColorBrush(Color.FromRgb(140, 150, 170)),
                BorderThickness = new Thickness(0),
                Cursor = Cursors.Hand,
                ToolTip = "Remove stroke"
            };
            delBtn.Click += (s, e) =>
            {
                if (strokeIdx < primary.Strokes.Count)
                {
                    primary.Strokes.RemoveAt(strokeIdx);
                    InvalidateAndRefresh(primary);
                    RefreshPropertyInspector();
                }
            };

            if (!stroke.IsExpanded)
            {
                // SINGLE LINE LIST ITEM (Compact view with editable color only)
                var row = new DockPanel { LastChildFill = true, Height = 22 };
                DockPanel.SetDock(grip, Dock.Left);
                row.Children.Add(grip);

                DockPanel.SetDock(swatch, Dock.Left);
                row.Children.Add(swatch);

                DockPanel.SetDock(delBtn, Dock.Right);
                row.Children.Add(delBtn);

                DockPanel.SetDock(chevronBtn, Dock.Right);
                row.Children.Add(chevronBtn);

                DockPanel.SetDock(eyeBtn, Dock.Right);
                row.Children.Add(eyeBtn);

                var wText = new TextBlock
                {
                    Text = Math.Round(stroke.Width, 1) + "px",
                    FontSize = 10,
                    Foreground = new SolidColorBrush(Color.FromRgb(140, 160, 195)),
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(4, 0, 6, 0),
                    Width = 36,
                    TextAlignment = TextAlignment.Right,
                    Cursor = Cursors.Hand,
                    ToolTip = "Click to edit stroke options"
                };
                wText.MouseLeftButtonUp += (s, e) =>
                {
                    stroke.IsExpanded = true;
                    RefreshPropertyInspector();
                };
                DockPanel.SetDock(wText, Dock.Right);
                row.Children.Add(wText);

                string labelText = (stroke.Paint.Type == PaintType.Solid)
                    ? (stroke.Paint.ColorHex ?? "#000000").ToUpper()
                    : ((stroke.Paint.Type == PaintType.LinearGradient) ? "Linear Gradient" : "Radial Gradient");

                var labelBlock = new TextBlock
                {
                    Text = labelText,
                    FontSize = 10,
                    FontWeight = (stroke.Paint.Type == PaintType.Solid) ? FontWeights.Normal : FontWeights.SemiBold,
                    Foreground = (stroke.Paint.Type == PaintType.Solid) ? new SolidColorBrush(Color.FromRgb(215, 225, 245)) : new SolidColorBrush(Color.FromRgb(56, 189, 248)),
                    VerticalAlignment = VerticalAlignment.Center,
                    Cursor = Cursors.Hand,
                    ToolTip = (stroke.Paint.Type != PaintType.Solid) ? "Click to open gradient options" : "Click to choose color"
                };
                labelBlock.MouseLeftButtonUp += (s, e) =>
                {
                    e.Handled = true;
                    openStrokeColorOrExpand();
                };
                row.Children.Add(labelBlock);

                card.Child = row;
                return card;
            }

            // EXPANDED VIEW WITH ALL OPTIONS
            var topRow = new DockPanel { LastChildFill = true, Margin = new Thickness(0, 0, 0, 6) };
            DockPanel.SetDock(grip, Dock.Left);
            topRow.Children.Add(grip);

            DockPanel.SetDock(swatch, Dock.Left);
            topRow.Children.Add(swatch);

            DockPanel.SetDock(delBtn, Dock.Right);
            topRow.Children.Add(delBtn);

            DockPanel.SetDock(chevronBtn, Dock.Right);
            topRow.Children.Add(chevronBtn);

            DockPanel.SetDock(eyeBtn, Dock.Right);
            topRow.Children.Add(eyeBtn);

            var strokeTypeCombo = CreateModernComboBox(22, 65);
            strokeTypeCombo.Margin = new Thickness(2, 0, 4, 0);
            strokeTypeCombo.Items.Add(CreateModernComboBoxItem("Solid"));
            strokeTypeCombo.Items.Add(CreateModernComboBoxItem("Linear"));
            strokeTypeCombo.Items.Add(CreateModernComboBoxItem("Radial"));
            strokeTypeCombo.SelectedIndex = (stroke.Paint.Type == PaintType.LinearGradient) ? 1 : (stroke.Paint.Type == PaintType.RadialGradient ? 2 : 0);
            strokeTypeCombo.SelectionChanged += (s, e) =>
            {
                if (strokeTypeCombo.SelectedIndex == 1)
                {
                    stroke.Paint.Type = PaintType.LinearGradient;
                    if (stroke.Paint.GradientStops == null || stroke.Paint.GradientStops.Count == 0)
                    {
                        stroke.Paint.GradientStops = new List<GradientStopData>
                        {
                            new GradientStopData(0.0, stroke.Paint.ColorHex ?? "#000000", 1.0),
                            new GradientStopData(1.0, "#6366F1", 1.0)
                        };
                    }
                    stroke.IsExpanded = true;
                    SetEditingGradient(primary, stroke.Paint);
                }
                else if (strokeTypeCombo.SelectedIndex == 2)
                {
                    stroke.Paint.Type = PaintType.RadialGradient;
                    if (stroke.Paint.GradientStops == null || stroke.Paint.GradientStops.Count == 0)
                    {
                        stroke.Paint.GradientStops = new List<GradientStopData>
                        {
                            new GradientStopData(0.0, stroke.Paint.ColorHex ?? "#000000", 1.0),
                            new GradientStopData(1.0, "#38BDF8", 1.0)
                        };
                    }
                    stroke.IsExpanded = true;
                    SetEditingGradient(primary, stroke.Paint);
                }
                else
                {
                    stroke.Paint.Type = PaintType.Solid;
                    if (_editingGradientPaint == stroke.Paint) ClearEditingGradient();
                }
                InvalidateAndRefresh(primary);
                RefreshPropertyInspector();
            };
            DockPanel.SetDock(strokeTypeCombo, Dock.Left);
            topRow.Children.Add(strokeTypeCombo);

            double startStrokeW = stroke.Width;
            var widthField = ScrubControls.CreateScrubField("Width", stroke.Width, val =>
            {
                stroke.Width = Math.Max(0, val);
                stroke.Enabled = (stroke.Width > 0);
                InvalidateAndRefresh(primary);
                if (_currentStudioMode == StudioMode.Animate)
                {
                    AutoKeyPropertyLivePreview(primary, PropKey.StrokeWidth, stroke.Width);
                }
            }, min: 0, max: 200, suffix: "px", onDragComplete: () =>
            {
                double finalW = stroke.Width;
                if (Math.Abs(finalW - startStrokeW) > 1e-6)
                {
                    if (_currentStudioMode == StudioMode.Animate)
                    {
                        CommitKeyframeValueChange(primary, PropKey.StrokeWidth, startStrokeW, finalW);
                    }
                    startStrokeW = finalW;
                }
            });
            topRow.Children.Add(CreateAnimatedPropertyField(widthField, primary, PropKey.StrokeWidth));

            cardStack.Children.Add(topRow);

            if (stroke.Paint.Type == PaintType.LinearGradient || stroke.Paint.Type == PaintType.RadialGradient)
            {
                bool isEditingThis = (_editingGradientPaint == stroke.Paint && _editingGradientLayer == primary);

                var toggleRow = new DockPanel { Margin = new Thickness(0, 2, 0, 4) };
                var rollerBtn = new Button
                {
                    Template = CreateRoundedButtonTemplate(6),
                    Content = isEditingThis ? "● Canvas Roller Active [Done]" : "✏ Edit on Canvas",
                    FontSize = 10,
                    FontWeight = FontWeights.SemiBold,
                    Height = 22,
                    Background = isEditingThis ? new SolidColorBrush(Color.FromRgb(20, 50, 110)) : new SolidColorBrush(Color.FromRgb(30, 36, 52)),
                    Foreground = isEditingThis ? new SolidColorBrush(Color.FromRgb(56, 189, 248)) : new SolidColorBrush(Color.FromRgb(150, 165, 195)),
                    BorderBrush = isEditingThis ? new SolidColorBrush(Color.FromRgb(56, 189, 248)) : new SolidColorBrush(Color.FromRgb(48, 58, 80)),
                    BorderThickness = new Thickness(1),
                    Cursor = Cursors.Hand,
                    Padding = new Thickness(6, 0, 6, 0),
                    ToolTip = isEditingThis ? "Click to exit on-canvas gradient editing (or press Esc)" : "Activate Figma on-canvas gradient handles & rollers"
                };

                GradientRampControl strokeRamp = null;
                rollerBtn.Click += (s, e) =>
                {
                    if (_editingGradientPaint == stroke.Paint)
                        ClearEditingGradient();
                    else
                        SetEditingGradient(primary, stroke.Paint, strokeRamp);
                    RefreshPropertyInspector();
                };
                toggleRow.Children.Add(rollerBtn);
                cardStack.Children.Add(toggleRow);

                strokeRamp = new GradientRampControl(stroke.Paint, () =>
                {
                    SetEditingGradient(primary, stroke.Paint, strokeRamp);
                    InvalidateAndRefresh(primary);
                }, () =>
                {
                    SetEditingGradient(primary, stroke.Paint, strokeRamp);
                    InvalidateAndRefresh(primary);
                    RefreshPropertyInspector();
                });

                strokeRamp.PreviewMouseDown += (s, e) =>
                {
                    if (_editingGradientPaint != stroke.Paint)
                    {
                        SetEditingGradient(primary, stroke.Paint, strokeRamp);
                        RefreshPropertyInspector();
                    }
                };

                cardStack.Children.Add(strokeRamp);
            }

            // Alignment & Cap row
            var alignRow = new Grid { Margin = new Thickness(0, 4, 0, 0) };
            alignRow.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            alignRow.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(4) });
            alignRow.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

            var alignCombo = CreateModernComboBox(22);
            alignCombo.Items.Add(CreateModernComboBoxItem("Center"));
            alignCombo.Items.Add(CreateModernComboBoxItem("Inside"));
            alignCombo.Items.Add(CreateModernComboBoxItem("Outside"));
            alignCombo.SelectedIndex = (stroke.Alignment == StrokeAlignment.Inside) ? 1 : (stroke.Alignment == StrokeAlignment.Outside ? 2 : 0);
            alignCombo.SelectionChanged += (s, e) =>
            {
                if (alignCombo.SelectedIndex == 1) stroke.Alignment = StrokeAlignment.Inside;
                else if (alignCombo.SelectedIndex == 2) stroke.Alignment = StrokeAlignment.Outside;
                else stroke.Alignment = StrokeAlignment.Center;
                InvalidateAndRefresh(primary);
            };
            Grid.SetColumn(alignCombo, 0);
            alignRow.Children.Add(alignCombo);

            var capCombo = CreateModernComboBox(22);
            capCombo.Items.Add(CreateModernComboBoxItem("Flat Cap"));
            capCombo.Items.Add(CreateModernComboBoxItem("Round Cap"));
            capCombo.Items.Add(CreateModernComboBoxItem("Square Cap"));
            capCombo.SelectedIndex = (stroke.Cap == StrokeCap.Round) ? 1 : (stroke.Cap == StrokeCap.Square ? 2 : 0);
            capCombo.SelectionChanged += (s, e) =>
            {
                if (capCombo.SelectedIndex == 1) stroke.Cap = StrokeCap.Round;
                else if (capCombo.SelectedIndex == 2) stroke.Cap = StrokeCap.Square;
                else stroke.Cap = StrokeCap.Flat;
                InvalidateAndRefresh(primary);
            };
            Grid.SetColumn(capCombo, 2);
            alignRow.Children.Add(capCombo);

            cardStack.Children.Add(alignRow);

            // --- STROKE EFFECTS COLLAPSIBLE PANEL ---
            bool isTrimmed = (stroke.TrimStart > 0.001 || stroke.TrimEnd < 0.999 || Math.Abs(stroke.TrimOffset) > 0.001);
            bool isTapered = (stroke.TaperStart > 0.001 || stroke.TaperEnd > 0.001 || stroke.TaperStartWidth > 0.001 || stroke.TaperEndWidth > 0.001);
            bool isEffectUsed = isTrimmed || isTapered;
            bool isEffectsExpanded = stroke.IsEffectsExpanded.HasValue ? stroke.IsEffectsExpanded.Value : isEffectUsed;

            var effectsToggleRow = new Border
            {
                Margin = new Thickness(0, 6, 0, 2),
                Padding = new Thickness(6, 4, 6, 4),
                Background = new SolidColorBrush(Color.FromRgb(26, 32, 46)),
                CornerRadius = new CornerRadius(4),
                Cursor = Cursors.Hand
            };

            var toggleGrid = new Grid();
            toggleGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            toggleGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            toggleGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

            var arrowText = new TextBlock
            {
                Text = isEffectsExpanded ? "▼" : "▶",
                FontSize = 8.5,
                Foreground = new SolidColorBrush(Color.FromRgb(140, 160, 195)),
                Margin = new Thickness(0, 0, 6, 0),
                VerticalAlignment = VerticalAlignment.Center
            };
            Grid.SetColumn(arrowText, 0);
            toggleGrid.Children.Add(arrowText);

            var effectsTitle = new TextBlock
            {
                Text = "STROKE EFFECTS",
                FontSize = 9.5,
                FontWeight = FontWeights.SemiBold,
                Foreground = isEffectUsed ? new SolidColorBrush(Color.FromRgb(70, 239, 177)) : new SolidColorBrush(Color.FromRgb(140, 160, 195)),
                VerticalAlignment = VerticalAlignment.Center
            };
            Grid.SetColumn(effectsTitle, 1);
            toggleGrid.Children.Add(effectsTitle);

            if (isEffectUsed)
            {
                var rightStack = new StackPanel { Orientation = Orientation.Horizontal };
                var activeBadge = new Border
                {
                    Background = new SolidColorBrush(Color.FromArgb(50, 70, 239, 177)),
                    BorderBrush = new SolidColorBrush(Color.FromRgb(70, 239, 177)),
                    BorderThickness = new Thickness(1),
                    CornerRadius = new CornerRadius(3),
                    Padding = new Thickness(4, 1, 4, 1),
                    Margin = new Thickness(0, 0, 4, 0),
                    VerticalAlignment = VerticalAlignment.Center,
                    Child = new TextBlock
                    {
                        Text = "Active",
                        FontSize = 8,
                        FontWeight = FontWeights.SemiBold,
                        Foreground = new SolidColorBrush(Color.FromRgb(70, 239, 177))
                    }
                };
                rightStack.Children.Add(activeBadge);

                var resetAllBtn = new Button
                {
                    Template = CreateRoundedButtonTemplate(3),
                    Content = "Reset",
                    FontSize = 9,
                    Height = 16,
                    Padding = new Thickness(4, 0, 4, 0),
                    Background = new SolidColorBrush(Color.FromRgb(35, 42, 60)),
                    Foreground = new SolidColorBrush(Color.FromRgb(140, 160, 195)),
                    BorderThickness = new Thickness(0),
                    Cursor = Cursors.Hand,
                    ToolTip = "Reset all trim path and taper effects"
                };
                resetAllBtn.Click += (s, e) =>
                {
                    stroke.TrimStart = 0.0;
                    stroke.TrimEnd = 1.0;
                    stroke.TrimOffset = 0.0;
                    stroke.TaperStart = 0.0;
                    stroke.TaperEnd = 0.0;
                    stroke.TaperStartWidth = 0.0;
                    stroke.TaperEndWidth = 0.0;
                    stroke.IsEffectsExpanded = false;
                    InvalidateAndRefresh(primary);
                    RefreshPropertyInspector();
                };
                rightStack.Children.Add(resetAllBtn);

                Grid.SetColumn(rightStack, 2);
                toggleGrid.Children.Add(rightStack);
            }

            effectsToggleRow.Child = toggleGrid;
            effectsToggleRow.MouseLeftButtonDown += (s, e) =>
            {
                stroke.IsEffectsExpanded = !isEffectsExpanded;
                RefreshPropertyInspector();
            };

            cardStack.Children.Add(effectsToggleRow);

            if (isEffectsExpanded)
            {
                var effectsContainer = new StackPanel { Margin = new Thickness(6, 4, 0, 2) };

                // --- TRIM PATH CONTROLS ---
                var trimHeader = new Grid { Margin = new Thickness(0, 6, 0, 4) };
                trimHeader.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                trimHeader.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

                var trimTitle = new TextBlock
                {
                    Text = "TRIM PATH",
                    FontSize = 9.5,
                    FontWeight = FontWeights.SemiBold,
                    Foreground = new SolidColorBrush(Color.FromRgb(130, 145, 175)),
                    VerticalAlignment = VerticalAlignment.Center
                };
                Grid.SetColumn(trimTitle, 0);
                trimHeader.Children.Add(trimTitle);

                if (isTrimmed)
                {
                    var resetTrimBtn = new Button
                    {
                        Template = CreateRoundedButtonTemplate(3),
                        Content = "Reset",
                        FontSize = 9,
                        Height = 16,
                        Padding = new Thickness(4, 0, 4, 0),
                        Background = new SolidColorBrush(Color.FromRgb(35, 42, 60)),
                        Foreground = new SolidColorBrush(Color.FromRgb(140, 160, 195)),
                        BorderThickness = new Thickness(0),
                        Cursor = Cursors.Hand,
                        ToolTip = "Reset trim path to full outline (0% - 100%)"
                    };
                    resetTrimBtn.Click += (s, e) =>
                    {
                        stroke.TrimStart = 0.0;
                        stroke.TrimEnd = 1.0;
                        stroke.TrimOffset = 0.0;
                        if (stroke.TaperStart <= 0.001 && stroke.TaperEnd <= 0.001 && stroke.TaperStartWidth <= 0.001 && stroke.TaperEndWidth <= 0.001)
                        {
                            stroke.IsEffectsExpanded = false;
                        }
                        InvalidateAndRefresh(primary);
                        RefreshPropertyInspector();
                    };
                    Grid.SetColumn(resetTrimBtn, 1);
                    trimHeader.Children.Add(resetTrimBtn);
                }
                effectsContainer.Children.Add(trimHeader);

                var trimStartEndGrid = new Grid { Margin = new Thickness(0, 0, 0, 4) };
                trimStartEndGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                trimStartEndGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(4) });
                trimStartEndGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

                double startTrimS = stroke.TrimStart;
                var trimStartField = ScrubControls.CreateScrubField("Start", Math.Round(stroke.TrimStart * 100.0, 1), new Action<double>(val =>
                {
                    stroke.TrimStart = Math.Max(0.0, Math.Min(100.0, val)) / 100.0;
                    InvalidateAndRefresh(primary);
                    if (_currentStudioMode == StudioMode.Animate)
                    {
                        AutoKeyPropertyLivePreview(primary, PropKey.StrokeTrimStart, stroke.TrimStart);
                    }
                }), 0.0, 100.0, 1.0, "%", "Trim Start percentage", 1, new Action(() =>
                {
                    double finalTrimS = stroke.TrimStart;
                    if (Math.Abs(finalTrimS - startTrimS) > 1e-6)
                    {
                        if (_currentStudioMode == StudioMode.Animate)
                        {
                            CommitKeyframeValueChange(primary, PropKey.StrokeTrimStart, startTrimS, finalTrimS);
                        }
                        startTrimS = finalTrimS;
                    }
                }));
                var animTrimStart = CreateAnimatedPropertyField(trimStartField, primary, PropKey.StrokeTrimStart);
                Grid.SetColumn(animTrimStart, 0);
                trimStartEndGrid.Children.Add(animTrimStart);

                double startTrimE = stroke.TrimEnd;
                var trimEndField = ScrubControls.CreateScrubField("End", Math.Round(stroke.TrimEnd * 100.0, 1), new Action<double>(val =>
                {
                    stroke.TrimEnd = Math.Max(0.0, Math.Min(100.0, val)) / 100.0;
                    InvalidateAndRefresh(primary);
                    if (_currentStudioMode == StudioMode.Animate)
                    {
                        AutoKeyPropertyLivePreview(primary, PropKey.StrokeTrimEnd, stroke.TrimEnd);
                    }
                }), 0.0, 100.0, 1.0, "%", "Trim End percentage", 1, new Action(() =>
                {
                    double finalTrimE = stroke.TrimEnd;
                    if (Math.Abs(finalTrimE - startTrimE) > 1e-6)
                    {
                        if (_currentStudioMode == StudioMode.Animate)
                        {
                            CommitKeyframeValueChange(primary, PropKey.StrokeTrimEnd, startTrimE, finalTrimE);
                        }
                        startTrimE = finalTrimE;
                    }
                }));
                var animTrimEnd = CreateAnimatedPropertyField(trimEndField, primary, PropKey.StrokeTrimEnd);
                Grid.SetColumn(animTrimEnd, 2);
                trimStartEndGrid.Children.Add(animTrimEnd);

                effectsContainer.Children.Add(trimStartEndGrid);

                double startTrimOff = stroke.TrimOffset;
                var trimOffsetField = ScrubControls.CreateScrubField("Offset", Math.Round(stroke.TrimOffset * 100.0, 1), new Action<double>(val =>
                {
                    stroke.TrimOffset = val / 100.0;
                    InvalidateAndRefresh(primary);
                    if (_currentStudioMode == StudioMode.Animate)
                    {
                        AutoKeyPropertyLivePreview(primary, PropKey.StrokeTrimOffset, stroke.TrimOffset);
                    }
                }), -360.0, 360.0, 1.0, "%", "Trim Offset shift percentage", 1, new Action(() =>
                {
                    double finalTrimOff = stroke.TrimOffset;
                    if (Math.Abs(finalTrimOff - startTrimOff) > 1e-6)
                    {
                        if (_currentStudioMode == StudioMode.Animate)
                        {
                            CommitKeyframeValueChange(primary, PropKey.StrokeTrimOffset, startTrimOff, finalTrimOff);
                        }
                        startTrimOff = finalTrimOff;
                    }
                }));
                var animTrimOffset = CreateAnimatedPropertyField(trimOffsetField, primary, PropKey.StrokeTrimOffset);
                effectsContainer.Children.Add(animTrimOffset);

                // --- STROKE TAPER CONTROLS ---
                var taperHeader = new Grid { Margin = new Thickness(0, 6, 0, 4) };
                taperHeader.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                taperHeader.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

                var taperTitle = new TextBlock
                {
                    Text = "STROKE TAPER",
                    FontSize = 9.5,
                    FontWeight = FontWeights.SemiBold,
                    Foreground = new SolidColorBrush(Color.FromRgb(130, 145, 175)),
                    VerticalAlignment = VerticalAlignment.Center
                };
                Grid.SetColumn(taperTitle, 0);
                taperHeader.Children.Add(taperTitle);

                if (isTapered)
                {
                    var resetTaperBtn = new Button
                    {
                        Template = CreateRoundedButtonTemplate(3),
                        Content = "Reset",
                        FontSize = 9,
                        Height = 16,
                        Padding = new Thickness(4, 0, 4, 0),
                        Background = new SolidColorBrush(Color.FromRgb(35, 42, 60)),
                        Foreground = new SolidColorBrush(Color.FromRgb(140, 160, 195)),
                        BorderThickness = new Thickness(0),
                        Cursor = Cursors.Hand,
                        ToolTip = "Reset taper lengths and tips to uniform stroke"
                    };
                    resetTaperBtn.Click += (s, e) =>
                    {
                        stroke.TaperStart = 0.0;
                        stroke.TaperEnd = 0.0;
                        stroke.TaperStartWidth = 0.0;
                        stroke.TaperEndWidth = 0.0;
                        if (stroke.TrimStart <= 0.001 && stroke.TrimEnd >= 0.999 && Math.Abs(stroke.TrimOffset) <= 0.001)
                        {
                            stroke.IsEffectsExpanded = false;
                        }
                        InvalidateAndRefresh(primary);
                        RefreshPropertyInspector();
                    };
                    Grid.SetColumn(resetTaperBtn, 1);
                    taperHeader.Children.Add(resetTaperBtn);
                }
                effectsContainer.Children.Add(taperHeader);

                var taperGrid = new Grid { Margin = new Thickness(0, 0, 0, 4) };
                taperGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                taperGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(4) });
                taperGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

                double startTaperS = stroke.TaperStart;
                var taperStartField = ScrubControls.CreateScrubField("Start Length", Math.Round(stroke.TaperStart * 100.0, 1), new Action<double>(val =>
                {
                    stroke.TaperStart = Math.Max(0.0, Math.Min(100.0, val)) / 100.0;
                    InvalidateAndRefresh(primary);
                    if (_currentStudioMode == StudioMode.Animate)
                    {
                        AutoKeyPropertyLivePreview(primary, PropKey.StrokeTaperStart, stroke.TaperStart);
                    }
                }), 0.0, 100.0, 1.0, "%", "Taper Start length fraction", 1, new Action(() =>
                {
                    double finalTaperS = stroke.TaperStart;
                    if (Math.Abs(finalTaperS - startTaperS) > 1e-6)
                    {
                        if (_currentStudioMode == StudioMode.Animate)
                        {
                            CommitKeyframeValueChange(primary, PropKey.StrokeTaperStart, startTaperS, finalTaperS);
                        }
                        startTaperS = finalTaperS;
                    }
                }));
                var animTaperStart = CreateAnimatedPropertyField(taperStartField, primary, PropKey.StrokeTaperStart);
                Grid.SetColumn(animTaperStart, 0);
                taperGrid.Children.Add(animTaperStart);

                double startTaperE = stroke.TaperEnd;
                var taperEndField = ScrubControls.CreateScrubField("End Length", Math.Round(stroke.TaperEnd * 100.0, 1), new Action<double>(val =>
                {
                    stroke.TaperEnd = Math.Max(0.0, Math.Min(100.0, val)) / 100.0;
                    InvalidateAndRefresh(primary);
                    if (_currentStudioMode == StudioMode.Animate)
                    {
                        AutoKeyPropertyLivePreview(primary, PropKey.StrokeTaperEnd, stroke.TaperEnd);
                    }
                }), 0.0, 100.0, 1.0, "%", "Taper End length fraction", 1, new Action(() =>
                {
                    double finalTaperE = stroke.TaperEnd;
                    if (Math.Abs(finalTaperE - startTaperE) > 1e-6)
                    {
                        if (_currentStudioMode == StudioMode.Animate)
                        {
                            CommitKeyframeValueChange(primary, PropKey.StrokeTaperEnd, startTaperE, finalTaperE);
                        }
                        startTaperE = finalTaperE;
                    }
                }));
                var animTaperEnd = CreateAnimatedPropertyField(taperEndField, primary, PropKey.StrokeTaperEnd);
                Grid.SetColumn(animTaperEnd, 2);
                taperGrid.Children.Add(animTaperEnd);

                effectsContainer.Children.Add(taperGrid);

                var taperTipGrid = new Grid { Margin = new Thickness(0, 0, 0, 4) };
                taperTipGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                taperTipGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(4) });
                taperTipGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

                var startTipField = ScrubControls.CreateScrubField("Start Tip", Math.Round(stroke.TaperStartWidth * 100.0, 1), new Action<double>(val =>
                {
                    stroke.TaperStartWidth = Math.Max(0.0, Math.Min(100.0, val)) / 100.0;
                    InvalidateAndRefresh(primary);
                }), 0.0, 100.0, 1.0, "%", "Start tip thickness fraction (0% = sharp point)");
                Grid.SetColumn(startTipField, 0);
                taperTipGrid.Children.Add(startTipField);

                var endTipField = ScrubControls.CreateScrubField("End Tip", Math.Round(stroke.TaperEndWidth * 100.0, 1), new Action<double>(val =>
                {
                    stroke.TaperEndWidth = Math.Max(0.0, Math.Min(100.0, val)) / 100.0;
                    InvalidateAndRefresh(primary);
                }), 0.0, 100.0, 1.0, "%", "End tip thickness fraction (0% = sharp point)");
                Grid.SetColumn(endTipField, 2);
                taperTipGrid.Children.Add(endTipField);

                effectsContainer.Children.Add(taperTipGrid);

                cardStack.Children.Add(effectsContainer);
            }

            card.Child = cardStack;
            return card;
        }

        private FrameworkElement CreateFigCraftColorRow(string hexVal, double opacityVal, Action<string> onHexChange, Action<double> onOpacityChange)
        {
            var dock = new DockPanel { Margin = new Thickness(0, 0, 0, 6) };

            var swatch = new Border
            {
                Width = 20,
                Height = 20,
                CornerRadius = new CornerRadius(4),
                Background = new SolidColorBrush(GpuRenderer.ParseHexColor(hexVal, 1.0)),
                BorderBrush = new SolidColorBrush(Color.FromRgb(65, 75, 102)),
                BorderThickness = new Thickness(1),
                Margin = new Thickness(0, 0, 6, 0),
                Cursor = Cursors.Hand,
                ToolTip = "Color Picker"
            };
            DockPanel.SetDock(swatch, Dock.Left);
            dock.Children.Add(swatch);

            var opField = ScrubControls.CreateScrubField("", Math.Round(opacityVal * 100), new Action<double>(val =>
            {
                if (onOpacityChange != null) onOpacityChange(Math.Max(0.0, Math.Min(100.0, val)) / 100.0);
            }), 0, 100, 1.0, "%", "Opacity (%)");
            opField.Width = 60;
            DockPanel.SetDock(opField, Dock.Right);
            dock.Children.Add(opField);

            var tbBorder = new Border
            {
                Height = 22,
                Background = new SolidColorBrush(Color.FromRgb(26, 30, 44)),
                BorderBrush = new SolidColorBrush(Color.FromRgb(48, 56, 78)),
                BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(4),
                Margin = new Thickness(0, 0, 6, 0)
            };
            var tb = new TextBox
            {
                Text = hexVal,
                FontSize = 11,
                Background = Brushes.Transparent,
                Foreground = Brushes.White,
                BorderThickness = new Thickness(0),
                Padding = new Thickness(6, 1, 6, 1),
                VerticalContentAlignment = VerticalAlignment.Center
            };
            tbBorder.Child = tb;

            swatch.MouseLeftButtonUp += (s, e) =>
            {
                e.Handled = true;
                ColorPickerPopup.ShowAt(swatch, tb.Text, newHex =>
                {
                    tb.Text = newHex;
                    swatch.Background = new SolidColorBrush(GpuRenderer.ParseHexColor(newHex, 1.0));
                    if (onHexChange != null) onHexChange(newHex);
                });
            };

            tb.TextChanged += (s, e) =>
            {
                if (tb.Text.StartsWith("#") && (tb.Text.Length == 7 || tb.Text.Length == 4 || tb.Text.Length == 9))
                {
                    swatch.Background = new SolidColorBrush(GpuRenderer.ParseHexColor(tb.Text, 1.0));
                    if (onHexChange != null) onHexChange(tb.Text);
                }
            };

            dock.Children.Add(tbBorder);
            return dock;
        }

        private void BuildEffectsSection(LayerNode primary)
        {
            if (primary.Effects == null) primary.Effects = new List<EffectData>();

            Action addDefaultEffect = () =>
            {
                var newFx = new EffectData
                {
                    Type = EffectType.DropShadow,
                    Enabled = true,
                    IsExpanded = true,
                    ColorHex = "#000000",
                    Opacity = 0.25,
                    OffsetX = 0,
                    OffsetY = 4,
                    Blur = 8,
                    Spread = 0
                };
                newFx.UpdatePolarFromOffsets();
                primary.Effects.Add(newFx);
                History.MarkDirty();
                InvalidateAndRefresh(primary);
                RefreshPropertyInspector();
            };

            // Section Header: "Effects" with [Styles ❖] and [Add +] buttons matching FigCraft
            var headerDock = new DockPanel { Margin = new Thickness(0, 12, 0, 8) };
            var headerTitle = new TextBlock
            {
                Text = "Effects",
                FontSize = 12,
                FontWeight = FontWeights.SemiBold,
                Foreground = new SolidColorBrush(Color.FromRgb(140, 150, 175)),
                VerticalAlignment = VerticalAlignment.Center
            };
            DockPanel.SetDock(headerTitle, Dock.Left);
            headerDock.Children.Add(headerTitle);

            var addBtn = new Button
            {
                Template = CreateRoundedButtonTemplate(4),
                Content = "+",
                FontSize = 14,
                FontWeight = FontWeights.Bold,
                Width = 22,
                Height = 22,
                Background = new SolidColorBrush(Color.FromRgb(35, 42, 60)),
                Foreground = Brushes.White,
                BorderBrush = new SolidColorBrush(Color.FromRgb(55, 65, 90)),
                BorderThickness = new Thickness(1),
                Cursor = Cursors.Hand,
                ToolTip = "Add effect"
            };
            addBtn.Click += (s, e) => addDefaultEffect();
            DockPanel.SetDock(addBtn, Dock.Right);
            headerDock.Children.Add(addBtn);

            var stylesBtn = new Button
            {
                Template = CreateRoundedButtonTemplate(4),
                Content = "❖",
                FontSize = 11,
                Width = 22,
                Height = 22,
                Background = Brushes.Transparent,
                Foreground = new SolidColorBrush(Color.FromRgb(140, 150, 175)),
                BorderThickness = new Thickness(0),
                Cursor = Cursors.Hand,
                Margin = new Thickness(0, 0, 4, 0),
                ToolTip = "Effect Styles"
            };
            DockPanel.SetDock(stylesBtn, Dock.Right);
            headerDock.Children.Add(stylesBtn);

            _propertyInspectorStack.Children.Add(headerDock);

            if (primary.Effects.Count == 0)
            {
                var emptyBtn = CreateSmallButton("+ Add Effect", "Add drop shadow, inner shadow, glass, noise, or blur", () => addDefaultEffect());
                _propertyInspectorStack.Children.Add(emptyBtn);
                return;
            }

            for (int i = 0; i < primary.Effects.Count; i++)
            {
                int fxIndex = i;
                var fx = primary.Effects[fxIndex];

                var card = new Border
                {
                    Background = new SolidColorBrush(Color.FromRgb(34, 39, 54)), // FigCraft dark card background
                    BorderBrush = new SolidColorBrush(Color.FromRgb(48, 55, 78)),
                    BorderThickness = new Thickness(1),
                    CornerRadius = new CornerRadius(6),
                    Padding = new Thickness(6),
                    Margin = new Thickness(0, 0, 0, 8)
                };

                var cardStack = new StackPanel();

                // 32px Row Header: [✨ Settings Toggle] [Dropdown ComboBox] [👁 Visibility] [— Remove]
                var headerRow = new DockPanel { Height = 28, LastChildFill = true, Margin = new Thickness(0, 0, 0, fx.IsExpanded ? 8 : 0) };

                // Left Settings Toggle Button (FigCraft: Icon::Effects, active highlight when open)
                var settingsBtn = new Button
                {
                    Template = CreateRoundedButtonTemplate(4),
                    Content = "✨",
                    FontSize = 11,
                    Width = 24,
                    Height = 24,
                    Background = fx.IsExpanded ? new SolidColorBrush(Color.FromRgb(55, 66, 95)) : Brushes.Transparent,
                    Foreground = fx.IsExpanded ? Brushes.White : new SolidColorBrush(Color.FromRgb(150, 165, 195)),
                    BorderBrush = fx.IsExpanded ? new SolidColorBrush(Color.FromRgb(75, 90, 125)) : Brushes.Transparent,
                    BorderThickness = new Thickness(fx.IsExpanded ? 1 : 0),
                    Cursor = Cursors.Hand,
                    ToolTip = "Effect settings"
                };
                settingsBtn.Click += (s, e) =>
                {
                    fx.IsExpanded = !fx.IsExpanded;
                    RefreshPropertyInspector();
                };
                DockPanel.SetDock(settingsBtn, Dock.Left);
                headerRow.Children.Add(settingsBtn);

                // Right tight-end: [— Remove] then [👁 Visibility]
                var delBtn = new Button
                {
                    Template = CreateRoundedButtonTemplate(4),
                    Content = "—",
                    FontSize = 12,
                    FontWeight = FontWeights.Bold,
                    Width = 22,
                    Height = 22,
                    Background = Brushes.Transparent,
                    Foreground = new SolidColorBrush(Color.FromRgb(180, 190, 210)),
                    BorderThickness = new Thickness(0),
                    Cursor = Cursors.Hand,
                    ToolTip = "Remove effect",
                    Margin = new Thickness(2, 0, 0, 0)
                };
                delBtn.Click += (s, e) =>
                {
                    if (fxIndex < primary.Effects.Count)
                    {
                        primary.Effects.RemoveAt(fxIndex);
                        History.MarkDirty();
                        InvalidateAndRefresh(primary);
                        RefreshPropertyInspector();
                    }
                };
                DockPanel.SetDock(delBtn, Dock.Right);
                headerRow.Children.Add(delBtn);

                var eyeBtn = new Button
                {
                    Template = CreateRoundedButtonTemplate(4),
                    Content = fx.Enabled ? "👁" : "—",
                    FontSize = 10,
                    Width = 22,
                    Height = 22,
                    Background = fx.Enabled ? new SolidColorBrush(Color.FromRgb(42, 50, 72)) : Brushes.Transparent,
                    Foreground = fx.Enabled ? Brushes.White : new SolidColorBrush(Color.FromRgb(110, 120, 140)),
                    BorderThickness = new Thickness(0),
                    Cursor = Cursors.Hand,
                    ToolTip = fx.Enabled ? "Disable effect" : "Enable effect"
                };
                eyeBtn.Click += (s, e) =>
                {
                    fx.Enabled = !fx.Enabled;
                    History.MarkDirty();
                    InvalidateAndRefresh(primary);
                    RefreshPropertyInspector();
                };
                DockPanel.SetDock(eyeBtn, Dock.Right);
                headerRow.Children.Add(eyeBtn);

                // Center: Type Dropdown ComboBox (fills available width)
                var typeCombo = CreateModernComboBox(22);
                typeCombo.Margin = new Thickness(4, 0, 4, 0);
                typeCombo.Items.Add(CreateModernComboBoxItem("Drop shadow", EffectType.DropShadow));
                typeCombo.Items.Add(CreateModernComboBoxItem("Inner shadow", EffectType.InnerShadow));
                typeCombo.Items.Add(CreateModernComboBoxItem("Layer blur", EffectType.LayerBlur));
                typeCombo.Items.Add(CreateModernComboBoxItem("Background blur", EffectType.BackgroundBlur));
                typeCombo.Items.Add(CreateModernComboBoxItem("Noise", EffectType.Grain));
                typeCombo.Items.Add(CreateModernComboBoxItem("Glass", EffectType.LiquidGlass));

                for (int c = 0; c < typeCombo.Items.Count; c++)
                {
                    var item = typeCombo.Items[c] as ComboBoxItem;
                    if (item != null && (EffectType)item.Tag == fx.Type)
                    {
                        typeCombo.SelectedIndex = c;
                        break;
                    }
                }
                if (typeCombo.SelectedIndex < 0) typeCombo.SelectedIndex = 0;

                typeCombo.SelectionChanged += (s, e) =>
                {
                    var sel = typeCombo.SelectedItem as ComboBoxItem;
                    if (sel != null && sel.Tag is EffectType)
                    {
                        var newType = (EffectType)sel.Tag;
                        if (fx.Type != newType)
                        {
                            fx.Type = newType;
                            if (newType == EffectType.LiquidGlass)
                            {
                                fx.EnsureGlassDefaults();
                                fx.ColorHex = "#FFFFFF";
                                fx.Opacity = 0.15;
                            }
                            else if (newType == EffectType.Grain)
                            {
                                fx.Scale = 1.0;
                                fx.Intensity = 0.25;
                                fx.ColorHex = "#FFFFFF";
                                fx.Opacity = 0.25;
                            }
                            else if (newType == EffectType.LayerBlur || newType == EffectType.BackgroundBlur)
                            {
                                if (fx.Blur <= 0) fx.Blur = 8;
                            }
                            History.MarkDirty();
                            InvalidateAndRefresh(primary);
                            RefreshPropertyInspector();
                        }
                    }
                };
                headerRow.Children.Add(typeCombo);
                cardStack.Children.Add(headerRow);

                // Expanded Settings Sub-panel (matching FigCraft)
                if (fx.IsExpanded)
                {
                    var settingsStack = new StackPanel();

                    // Helper to create 50/50 two-column rows
                    Func<FrameworkElement, FrameworkElement, Grid> makeTwoCol = (left, right) =>
                    {
                        var g = new Grid { Margin = new Thickness(0, 0, 0, 6) };
                        g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                        g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(6) });
                        g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                        Grid.SetColumn(left, 0);
                        Grid.SetColumn(right, 2);
                        g.Children.Add(left);
                        g.Children.Add(right);
                        return g;
                    };

                    switch (fx.Type)
                    {
                        case EffectType.LiquidGlass:
                        {
                            fx.EnsureGlassDefaults();

                            // Row 1: Light (°) | Intensity (%)
                            var lightField = ScrubControls.CreateScrubField("Light", fx.LightAngle, new Action<double>(val =>
                            {
                                double deg = (val % 360.0);
                                if (deg > 180.0) deg -= 360.0;
                                else if (deg < -180.0) deg += 360.0;
                                fx.LightAngle = Math.Round(deg, 1);
                                History.MarkDirty();
                                InvalidateAndRefresh(primary);
                            }), -180, 180, 1.0, "°", "Where the light comes from (-180° to 180°)");

                            var intField = ScrubControls.CreateScrubField("Intensity", Math.Round(fx.LightIntensity * 100), new Action<double>(val =>
                            {
                                fx.LightIntensity = Math.Max(0.0, Math.Min(100.0, val)) / 100.0;
                                History.MarkDirty();
                                InvalidateAndRefresh(primary);
                            }), 0, 100, 1.0, "%", "Brightness of the edge highlights (0-100%)");

                            settingsStack.Children.Add(makeTwoCol(lightField, intField));

                            // Row 2: Refraction (%) | Depth (px)
                            var refrField = ScrubControls.CreateScrubField("Refraction", Math.Round(fx.Refraction * 100), new Action<double>(val =>
                            {
                                fx.Refraction = Math.Max(0.0, Math.Min(100.0, val)) / 100.0;
                                History.MarkDirty();
                                InvalidateAndRefresh(primary);
                            }), 0, 100, 1.0, "%", "How strongly the curved edge bends the backdrop (0-100%)");

                            var depthField = ScrubControls.CreateScrubField("Depth", fx.Depth, new Action<double>(val =>
                            {
                                fx.Depth = Math.Max(1.0, Math.Min(1000.0, val));
                                History.MarkDirty();
                                InvalidateAndRefresh(primary);
                            }), 1, 1000, 1.0, "px", "How far the curved edge reaches in from the border (1-1000px)");

                            settingsStack.Children.Add(makeTwoCol(refrField, depthField));

                            // Row 3: Dispersion (%) | Frost (px)
                            var dispField = ScrubControls.CreateScrubField("Dispersion", Math.Round(fx.Dispersion * 100), new Action<double>(val =>
                            {
                                fx.Dispersion = Math.Max(0.0, Math.Min(100.0, val)) / 100.0;
                                History.MarkDirty();
                                InvalidateAndRefresh(primary);
                            }), 0, 100, 1.0, "%", "Colour splitting along the curved edge (0-100%)");

                            var frostField = ScrubControls.CreateScrubField("Frost", fx.Frost, new Action<double>(val =>
                            {
                                fx.Frost = Math.Max(0.0, Math.Min(100.0, val));
                                History.MarkDirty();
                                InvalidateAndRefresh(primary);
                            }), 0, 100, 1.0, "px", "Blur of the backdrop (0-100px)");

                            settingsStack.Children.Add(makeTwoCol(dispField, frostField));

                            // Row 4: Splay (%)
                            var splayField = ScrubControls.CreateScrubField("Splay", Math.Round(fx.Splay * 100), new Action<double>(val =>
                            {
                                fx.Splay = Math.Max(0.0, Math.Min(100.0, val)) / 100.0;
                                History.MarkDirty();
                                InvalidateAndRefresh(primary);
                            }), 0, 100, 1.0, "%", "Bend direction: towards core (0%) to away from center (100%)");
                            settingsStack.Children.Add(splayField);

                            // Row 5: Tint Color Swatch + Hex + Opacity %
                            string gColor = string.IsNullOrEmpty(fx.ColorHex) ? "#FFFFFF" : fx.ColorHex;
                            var colorRow = CreateFigCraftColorRow(gColor, fx.Opacity, new Action<string>(hex =>
                            {
                                fx.ColorHex = hex;
                                History.MarkDirty();
                                InvalidateAndRefresh(primary);
                            }), new Action<double>(op =>
                            {
                                fx.Opacity = op;
                                History.MarkDirty();
                                InvalidateAndRefresh(primary);
                            }));
                            settingsStack.Children.Add(colorRow);
                            break;
                        }

                        case EffectType.DropShadow:
                        case EffectType.InnerShadow:
                        {
                            bool isDrop = (fx.Type == EffectType.DropShadow);

                            // Row 1: X | Y
                            var xBox = ScrubControls.CreateScrubField("X", fx.OffsetX, new Action<double>(val =>
                            {
                                fx.OffsetX = val;
                                fx.UpdatePolarFromOffsets();
                                History.MarkDirty();
                                InvalidateAndRefresh(primary);
                            }), -500, 500, 1.0, "px", "Offset X (px)");

                            var yBox = ScrubControls.CreateScrubField("Y", fx.OffsetY, new Action<double>(val =>
                            {
                                fx.OffsetY = val;
                                fx.UpdatePolarFromOffsets();
                                History.MarkDirty();
                                InvalidateAndRefresh(primary);
                            }), -500, 500, 1.0, "px", "Offset Y (px)");

                            settingsStack.Children.Add(makeTwoCol(xBox, yBox));

                            // Row 2: Blur | Spread
                            var blurBox = ScrubControls.CreateScrubField("Blur", fx.Blur, new Action<double>(val =>
                            {
                                fx.Blur = Math.Max(0, val);
                                History.MarkDirty();
                                InvalidateAndRefresh(primary);
                            }), 0, 200, 1.0, "px", "Blur Radius (px)");

                            var spreadBox = ScrubControls.CreateScrubField("Spread", fx.Spread, new Action<double>(val =>
                            {
                                fx.Spread = val;
                                History.MarkDirty();
                                InvalidateAndRefresh(primary);
                            }), -50, 100, 1.0, "px", "Shadow Spread (px)");

                            settingsStack.Children.Add(makeTwoCol(blurBox, spreadBox));

                            // Row 3: Color Swatch + Hex + Opacity %
                            string sColor = string.IsNullOrEmpty(fx.ColorHex) ? "#000000" : fx.ColorHex;
                            var colorRow = CreateFigCraftColorRow(sColor, fx.Opacity, new Action<string>(hex =>
                            {
                                fx.ColorHex = hex;
                                History.MarkDirty();
                                InvalidateAndRefresh(primary);
                            }), new Action<double>(op =>
                            {
                                fx.Opacity = op;
                                History.MarkDirty();
                                InvalidateAndRefresh(primary);
                            }));
                            settingsStack.Children.Add(colorRow);

                            // Row 4 (Drop Shadow only): Show behind transparent areas
                            if (isDrop)
                            {
                                var chk = new CheckBox
                                {
                                    Content = "Show behind transparent areas",
                                    IsChecked = fx.ShowBehind,
                                    Foreground = new SolidColorBrush(Color.FromRgb(160, 175, 205)),
                                    FontSize = 11,
                                    Margin = new Thickness(2, 4, 0, 4)
                                };
                                chk.Click += (s, e) =>
                                {
                                    fx.ShowBehind = (chk.IsChecked == true);
                                    History.MarkDirty();
                                    InvalidateAndRefresh(primary);
                                };
                                settingsStack.Children.Add(chk);
                            }
                            break;
                        }

                        case EffectType.LayerBlur:
                        case EffectType.BackgroundBlur:
                        {
                            var blurBox = ScrubControls.CreateScrubField("Blur", fx.Blur > 0 ? fx.Blur : 8, new Action<double>(val =>
                            {
                                fx.Blur = Math.Max(0, val);
                                History.MarkDirty();
                                InvalidateAndRefresh(primary);
                            }), 0, 200, 1.0, "px", "Blur Radius (px)");
                            settingsStack.Children.Add(blurBox);

                            if (fx.Type == EffectType.BackgroundBlur)
                            {
                                string bColor = string.IsNullOrEmpty(fx.ColorHex) ? "#FFFFFF" : fx.ColorHex;
                                var colorRow = CreateFigCraftColorRow(bColor, fx.Opacity, new Action<string>(hex =>
                                {
                                    fx.ColorHex = hex;
                                    History.MarkDirty();
                                    InvalidateAndRefresh(primary);
                                }), new Action<double>(op =>
                                {
                                    fx.Opacity = op;
                                    History.MarkDirty();
                                    InvalidateAndRefresh(primary);
                                }));
                                settingsStack.Children.Add(colorRow);
                            }
                            break;
                        }

                        case EffectType.Grain:
                        {
                            var sizeBox = ScrubControls.CreateScrubField("Size", fx.Scale > 0 ? fx.Scale : 1.0, new Action<double>(val =>
                            {
                                fx.Scale = Math.Max(0.1, Math.Min(100.0, val));
                                History.MarkDirty();
                                InvalidateAndRefresh(primary);
                            }), 0.1, 100.0, 0.1, "", "Noise grain size");

                            var denBox = ScrubControls.CreateScrubField("Density", Math.Round(fx.Intensity * 100), new Action<double>(val =>
                            {
                                fx.Intensity = Math.Max(0.0, Math.Min(100.0, val)) / 100.0;
                                History.MarkDirty();
                                InvalidateAndRefresh(primary);
                            }), 0, 100, 1.0, "%", "Noise density (%)");

                            settingsStack.Children.Add(makeTwoCol(sizeBox, denBox));

                            string gColor = string.IsNullOrEmpty(fx.ColorHex) ? "#FFFFFF" : fx.ColorHex;
                            var colorRow = CreateFigCraftColorRow(gColor, fx.Opacity, new Action<string>(hex =>
                            {
                                fx.ColorHex = hex;
                                History.MarkDirty();
                                InvalidateAndRefresh(primary);
                            }), new Action<double>(op =>
                            {
                                fx.Opacity = op;
                                History.MarkDirty();
                                InvalidateAndRefresh(primary);
                            }));
                            settingsStack.Children.Add(colorRow);
                            break;
                        }
                    }

                    cardStack.Children.Add(settingsStack);
                }

                card.Child = cardStack;
                _propertyInspectorStack.Children.Add(card);
            }
        }

        private void BuildTypographySection(LayerNode primary)
        {
            _propertyInspectorStack.Children.Add(CreateInspectorSection("Typography"));
            var typo = primary.Typography ?? new TypographyData();
            primary.Typography = typo;

            // Direct text edit prompt button
            var editPromptBtn = CreateSmallButton("✎ Edit Text on Canvas (Double-Click)", "Edit text in-place", () =>
            {
                StartInPlaceTextEditing(primary);
            });
            editPromptBtn.Margin = new Thickness(0, 0, 0, 6);
            _propertyInspectorStack.Children.Add(editPromptBtn);

            // 1. System Font Family dropdown
            var fontLabel = new TextBlock
            {
                Text = "Font Family",
                FontSize = 10,
                Foreground = new SolidColorBrush(Color.FromRgb(130, 140, 160)),
                Margin = new Thickness(0, 2, 0, 2)
            };
            _propertyInspectorStack.Children.Add(fontLabel);

            var fontCombo = CreateModernComboBox(26);
            fontCombo.Margin = new Thickness(0, 0, 0, 6);

            // Populate with system font families
            try
            {
                var sysFonts = Fonts.SystemFontFamilies.Select(f => f.Source).OrderBy(s => s).ToList();
                foreach (var fn in sysFonts)
                {
                    fontCombo.Items.Add(fn);
                }
                if (!string.IsNullOrEmpty(typo.FontFamily) && fontCombo.Items.Contains(typo.FontFamily))
                {
                    fontCombo.SelectedItem = typo.FontFamily;
                }
                else
                {
                    fontCombo.SelectedItem = "Segoe UI";
                }
            }
            catch
            {
                fontCombo.Items.Add("Segoe UI");
                fontCombo.Items.Add("Arial");
                fontCombo.Items.Add("Consolas");
                fontCombo.SelectedItem = "Segoe UI";
            }

            fontCombo.SelectionChanged += (s, e) =>
            {
                if (fontCombo.SelectedItem != null)
                {
                    typo.FontFamily = fontCombo.SelectedItem.ToString();
                    InvalidateAndRefresh(primary);
                }
            };
            _propertyInspectorStack.Children.Add(fontCombo);

            // 2. Weight and Italic Style
            var styleGrid = new Grid { Margin = new Thickness(0, 0, 0, 6) };
            styleGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            styleGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(4) });
            styleGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(32) });

            var weightCombo = CreateModernComboBox(26);
            var weights = new int[] { 100, 300, 400, 500, 600, 700, 800, 900 };
            var weightNames = new string[] { "Thin (100)", "Light (300)", "Regular (400)", "Medium (500)", "SemiBold (600)", "Bold (700)", "ExtraBold (800)", "Black (900)" };
            for (int wi = 0; wi < weights.Length; wi++) weightCombo.Items.Add(weightNames[wi]);

            int selWeightIdx = Array.IndexOf(weights, typo.FontWeight);
            weightCombo.SelectedIndex = selWeightIdx >= 0 ? selWeightIdx : 2; // Default Regular
            weightCombo.SelectionChanged += (s, e) =>
            {
                if (weightCombo.SelectedIndex >= 0 && weightCombo.SelectedIndex < weights.Length)
                {
                    typo.FontWeight = weights[weightCombo.SelectedIndex];
                    InvalidateAndRefresh(primary);
                }
            };
            Grid.SetColumn(weightCombo, 0);
            styleGrid.Children.Add(weightCombo);

            var italicBtn = new Button
            {
                Template = CreateRoundedButtonTemplate(5),
                Content = "I",
                FontStyle = FontStyles.Italic,
                FontWeight = FontWeights.Bold,
                FontSize = 12,
                Height = 24,
                Background = typo.IsItalic ? new SolidColorBrush(Color.FromRgb(56, 189, 248)) : new SolidColorBrush(Color.FromRgb(35, 42, 60)),
                Foreground = typo.IsItalic ? Brushes.Black : Brushes.White,
                BorderThickness = new Thickness(1),
                BorderBrush = new SolidColorBrush(Color.FromRgb(45, 54, 78)),
                Cursor = Cursors.Hand,
                ToolTip = "Italic toggle"
            };
            italicBtn.Click += (s, e) =>
            {
                typo.IsItalic = !typo.IsItalic;
                InvalidateAndRefresh(primary);
                RefreshPropertyInspector();
            };
            Grid.SetColumn(italicBtn, 2);
            styleGrid.Children.Add(italicBtn);
            _propertyInspectorStack.Children.Add(styleGrid);

            // 3. Numeric Fields: Font Size, Line Height
            var numGrid = new Grid { Margin = new Thickness(0, 0, 0, 6) };
            numGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            numGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(4) });
            numGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

            var sizeField = ScrubControls.CreateScrubField("Size", typo.FontSize, val =>
            {
                typo.FontSize = Math.Max(6, val);
                InvalidateAndRefresh(primary);
            }, min: 6, max: 200, suffix: "px");
            Grid.SetColumn(sizeField, 0);
            numGrid.Children.Add(sizeField);

            var lhField = ScrubControls.CreateScrubField("Line H", typo.LineHeight, val =>
            {
                typo.LineHeight = Math.Max(0.5, val);
                InvalidateAndRefresh(primary);
            }, min: 0.5, max: 5.0, suffix: "x");
            Grid.SetColumn(lhField, 2);
            numGrid.Children.Add(lhField);
            _propertyInspectorStack.Children.Add(numGrid);

            // 4. Horizontal Alignment Segment
            var hAlignLabel = new TextBlock
            {
                Text = "Text Align",
                FontSize = 10,
                Foreground = new SolidColorBrush(Color.FromRgb(130, 140, 160)),
                Margin = new Thickness(0, 2, 0, 2)
            };
            _propertyInspectorStack.Children.Add(hAlignLabel);

            var hAlignRow = new Grid { Margin = new Thickness(0, 0, 0, 6) };
            for (int i = 0; i < 4; i++) hAlignRow.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

            string[] hSymbols = new string[] { "⫷", "≡", "⫸", "⬌" };
            string[] hTips = new string[] { "Align Left", "Align Center", "Align Right", "Justify" };
            TextAlign[] hVals = new TextAlign[] { TextAlign.Left, TextAlign.Center, TextAlign.Right, TextAlign.Justify };

            for (int i = 0; i < 4; i++)
            {
                TextAlign tv = hVals[i];
                bool isSel = (typo.Align == tv);
                var btn = new Button
                {
                    Content = hSymbols[i],
                    ToolTip = hTips[i],
                    Height = 24,
                    FontSize = 11,
                    Background = isSel ? new SolidColorBrush(Color.FromRgb(56, 189, 248)) : new SolidColorBrush(Color.FromRgb(32, 38, 54)),
                    Foreground = isSel ? Brushes.Black : Brushes.White,
                    BorderBrush = new SolidColorBrush(Color.FromRgb(45, 54, 78)),
                    BorderThickness = new Thickness(1),
                    Cursor = Cursors.Hand,
                    Template = CreateRoundedButtonTemplate(5)
                };
                btn.Click += (s, e) =>
                {
                    typo.Align = tv;
                    InvalidateAndRefresh(primary);
                    RefreshPropertyInspector();
                };
                Grid.SetColumn(btn, i);
                hAlignRow.Children.Add(btn);
            }
            _propertyInspectorStack.Children.Add(hAlignRow);

            // 5. Vertical Alignment Segment
            var vAlignLabel = new TextBlock
            {
                Text = "Vertical Align",
                FontSize = 10,
                Foreground = new SolidColorBrush(Color.FromRgb(130, 140, 160)),
                Margin = new Thickness(0, 2, 0, 2)
            };
            _propertyInspectorStack.Children.Add(vAlignLabel);

            var vAlignRow = new Grid { Margin = new Thickness(0, 0, 0, 6) };
            for (int i = 0; i < 3; i++) vAlignRow.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

            string[] vSymbols = new string[] { "⤒ Top", "⬍ Middle", "⤓ Bottom" };
            VerticalAlign[] vVals = new VerticalAlign[] { VerticalAlign.Top, VerticalAlign.Middle, VerticalAlign.Bottom };

            for (int i = 0; i < 3; i++)
            {
                VerticalAlign vv = vVals[i];
                bool isSel = (typo.VerticalAlign == vv);
                var btn = new Button
                {
                    Content = vSymbols[i],
                    Height = 24,
                    FontSize = 10,
                    Background = isSel ? new SolidColorBrush(Color.FromRgb(56, 189, 248)) : new SolidColorBrush(Color.FromRgb(32, 38, 54)),
                    Foreground = isSel ? Brushes.Black : Brushes.White,
                    BorderBrush = new SolidColorBrush(Color.FromRgb(45, 54, 78)),
                    BorderThickness = new Thickness(1),
                    Cursor = Cursors.Hand,
                    Template = CreateRoundedButtonTemplate(5)
                };
                btn.Click += (s, e) =>
                {
                    typo.VerticalAlign = vv;
                    InvalidateAndRefresh(primary);
                    RefreshPropertyInspector();
                };
                Grid.SetColumn(btn, i);
                vAlignRow.Children.Add(btn);
            }
            _propertyInspectorStack.Children.Add(vAlignRow);

            // 6. Resizing Mode (Figma Text Dynamics: Auto Width, Auto Height, Fixed Size)
            var resizeLabel = new TextBlock
            {
                Text = "Resizing",
                FontSize = 10,
                Foreground = new SolidColorBrush(Color.FromRgb(130, 140, 160)),
                Margin = new Thickness(0, 2, 0, 2)
            };
            _propertyInspectorStack.Children.Add(resizeLabel);

            var resizeRow = new Grid { Margin = new Thickness(0, 0, 0, 6) };
            for (int i = 0; i < 3; i++) resizeRow.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

            string[] rSymbols = new string[] { "↔ Auto W", "↕ Auto H", "⏹ Fixed" };
            string[] rTips = new string[] { "Auto Width: width hugs text (single line)", "Auto Height: fixed width, height hugs wrapped lines", "Fixed Size: text clips / overflows fixed bounds" };
            TextAutoResize[] rVals = new TextAutoResize[] { TextAutoResize.AutoWidth, TextAutoResize.AutoHeight, TextAutoResize.Fixed };

            for (int i = 0; i < 3; i++)
            {
                TextAutoResize rv = rVals[i];
                bool isSel = (typo.AutoResize == rv);
                var btn = new Button
                {
                    Content = rSymbols[i],
                    ToolTip = rTips[i],
                    Height = 24,
                    FontSize = 10,
                    Background = isSel ? new SolidColorBrush(Color.FromRgb(56, 189, 248)) : new SolidColorBrush(Color.FromRgb(32, 38, 54)),
                    Foreground = isSel ? Brushes.Black : Brushes.White,
                    BorderBrush = new SolidColorBrush(Color.FromRgb(45, 54, 78)),
                    BorderThickness = new Thickness(1),
                    Cursor = Cursors.Hand,
                    Template = CreateRoundedButtonTemplate(5)
                };
                btn.Click += (s, e) =>
                {
                    typo.AutoResize = rv;
                    InvalidateAndRefresh(primary);
                    RefreshPropertyInspector();
                };
                Grid.SetColumn(btn, i);
                resizeRow.Children.Add(btn);
            }
            _propertyInspectorStack.Children.Add(resizeRow);

            // 7. Decorations & Casing
            var decorLabel = new TextBlock
            {
                Text = "Decoration & Case",
                FontSize = 10,
                Foreground = new SolidColorBrush(Color.FromRgb(130, 140, 160)),
                Margin = new Thickness(0, 2, 0, 2)
            };
            _propertyInspectorStack.Children.Add(decorLabel);

            var decorRow = new Grid { Margin = new Thickness(0, 0, 0, 6) };
            decorRow.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            decorRow.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(4) });
            decorRow.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

            var decorCombo = CreateModernComboBox(24);
            decorCombo.Items.Add(CreateModernComboBoxItem("None"));
            decorCombo.Items.Add(CreateModernComboBoxItem("Underline"));
            decorCombo.Items.Add(CreateModernComboBoxItem("Strikethrough"));
            decorCombo.SelectedIndex = (typo.Decoration == TextDecorationMode.Underline) ? 1 : (typo.Decoration == TextDecorationMode.Strikethrough ? 2 : 0);
            decorCombo.SelectionChanged += (s, e) =>
            {
                if (decorCombo.SelectedIndex == 1) typo.Decoration = TextDecorationMode.Underline;
                else if (decorCombo.SelectedIndex == 2) typo.Decoration = TextDecorationMode.Strikethrough;
                else typo.Decoration = TextDecorationMode.None;
                InvalidateAndRefresh(primary);
            };
            Grid.SetColumn(decorCombo, 0);
            decorRow.Children.Add(decorCombo);

            var caseCombo = CreateModernComboBox(24);
            caseCombo.Items.Add(CreateModernComboBoxItem("As-Is"));
            caseCombo.Items.Add(CreateModernComboBoxItem("UPPERCASE"));
            caseCombo.Items.Add(CreateModernComboBoxItem("lowercase"));
            caseCombo.Items.Add(CreateModernComboBoxItem("Title Case"));
            caseCombo.SelectedIndex = (typo.Case == TextCase.Upper) ? 1 : (typo.Case == TextCase.Lower ? 2 : (typo.Case == TextCase.Title ? 3 : 0));
            caseCombo.SelectionChanged += (s, e) =>
            {
                if (caseCombo.SelectedIndex == 1) typo.Case = TextCase.Upper;
                else if (caseCombo.SelectedIndex == 2) typo.Case = TextCase.Lower;
                else if (caseCombo.SelectedIndex == 3) typo.Case = TextCase.Title;
                else typo.Case = TextCase.Original;
                InvalidateAndRefresh(primary);
            };
            Grid.SetColumn(caseCombo, 2);
            decorRow.Children.Add(caseCombo);
            _propertyInspectorStack.Children.Add(decorRow);
        }

        public void StartInPlaceTextEditing(LayerNode node)
        {
            if (node == null || node.Type != ElementType.Text) return;
            if (_isEditingText) EndInPlaceTextEditing(commit: true);

            _isEditingText = true;
            _editingTextNode = node;
            _initialTypographyBeforeEdit = node.Typography != null ? node.Typography.Clone() : new TypographyData();
            _initialTextBoundsBeforeEdit = node.GetBounds();

            var typo = node.Typography ?? new TypographyData();
            node.Typography = typo;

            Point screenPt = CanvasToScreen(new Point(node.X, node.Y));
            double w = Math.Max(100.0, node.Width * _zoomScale + 20);
            double h = Math.Max(40.0, node.Height * _zoomScale + 20);

            _inPlaceTextEditor = new TextBox
            {
                Text = typo.Text,
                FontFamily = new FontFamily(string.IsNullOrEmpty(typo.FontFamily) ? "Segoe UI" : typo.FontFamily),
                FontSize = Math.Max(10.0, typo.FontSize * _zoomScale),
                FontWeight = FontWeight.FromOpenTypeWeight(Math.Max(100, Math.Min(900, typo.FontWeight))),
                FontStyle = typo.IsItalic ? FontStyles.Italic : FontStyles.Normal,
                Background = new SolidColorBrush(Color.FromArgb(240, 20, 24, 36)),
                Foreground = Brushes.White,
                BorderBrush = new SolidColorBrush(Color.FromRgb(56, 189, 248)),
                BorderThickness = new Thickness(1.5),
                Padding = new Thickness(6),
                AcceptsReturn = true,
                TextWrapping = (typo.AutoResize == TextAutoResize.AutoWidth) ? TextWrapping.NoWrap : TextWrapping.Wrap,
                HorizontalAlignment = HorizontalAlignment.Left,
                VerticalAlignment = VerticalAlignment.Top,
                Width = w,
                Height = h,
                Margin = new Thickness(screenPt.X - 4, screenPt.Y - 4, 0, 0)
            };

            switch (typo.Align)
            {
                case TextAlign.Center: _inPlaceTextEditor.TextAlignment = TextAlignment.Center; break;
                case TextAlign.Right: _inPlaceTextEditor.TextAlignment = TextAlignment.Right; break;
                case TextAlign.Justify: _inPlaceTextEditor.TextAlignment = TextAlignment.Justify; break;
                default: _inPlaceTextEditor.TextAlignment = TextAlignment.Left; break;
            }

            _inPlaceTextEditor.TextChanged += (s, e) =>
            {
                typo.Text = _inPlaceTextEditor.Text;
                var typeFace = new Typeface(_inPlaceTextEditor.FontFamily, _inPlaceTextEditor.FontStyle, _inPlaceTextEditor.FontWeight, FontStretches.Normal);
                var ft = new FormattedText(
                    string.IsNullOrEmpty(typo.Text) ? " " : typo.Text,
                    CultureInfo.CurrentCulture,
                    FlowDirection.LeftToRight,
                    typeFace,
                    typo.FontSize,
                    Brushes.White);

                if (typo.AutoResize == TextAutoResize.AutoWidth)
                {
                    node.Width = Math.Max(20.0, ft.WidthIncludingTrailingWhitespace);
                    node.Height = Math.Max(16.0, ft.Height);
                    _inPlaceTextEditor.Width = Math.Max(100.0, node.Width * _zoomScale + 20);
                    _inPlaceTextEditor.Height = Math.Max(40.0, node.Height * _zoomScale + 20);
                }
                else if (typo.AutoResize == TextAutoResize.AutoHeight)
                {
                    ft.MaxTextWidth = Math.Max(1.0, node.Width);
                    node.Height = Math.Max(16.0, ft.Height);
                    _inPlaceTextEditor.Height = Math.Max(40.0, node.Height * _zoomScale + 20);
                }
                _sceneGraph.InvalidateNode(node.Id);
                RefreshCanvas();
            };

            _inPlaceTextEditor.KeyDown += (s, e) =>
            {
                if (e.Key == Key.Escape)
                {
                    EndInPlaceTextEditing(commit: true);
                    e.Handled = true;
                }
                else if (e.Key == Key.Enter && (Keyboard.IsKeyDown(Key.LeftCtrl) || Keyboard.IsKeyDown(Key.RightCtrl)))
                {
                    EndInPlaceTextEditing(commit: true);
                    e.Handled = true;
                }
            };

            _inPlaceTextEditor.LostFocus += (s, e) =>
            {
                EndInPlaceTextEditing(commit: true);
            };

            if (_canvasContainer != null)
            {
                _canvasContainer.Children.Add(_inPlaceTextEditor);
                _inPlaceTextEditor.Focus();
                _inPlaceTextEditor.SelectAll();
            }
        }

        public void EndInPlaceTextEditing(bool commit)
        {
            if (!_isEditingText) return;
            _isEditingText = false;

            if (_inPlaceTextEditor != null && _canvasContainer != null)
            {
                _canvasContainer.Children.Remove(_inPlaceTextEditor);
                _inPlaceTextEditor = null;
            }

            if (_editingTextNode != null)
            {
                var curBounds = _editingTextNode.GetBounds();
                if (commit && _initialTypographyBeforeEdit != null)
                {
                    var cmd = new ModifyTypographyCommand(
                        _editingTextNode,
                        _initialTypographyBeforeEdit,
                        _editingTextNode.Typography.Clone(),
                        _initialTextBoundsBeforeEdit,
                        curBounds,
                        () =>
                        {
                            _sceneGraph.InvalidateNode(_editingTextNode.Id);
                            RefreshCanvas();
                            RefreshPropertyInspector();
                        });
                    History.Execute(cmd);
                }
                _sceneGraph.InvalidateNode(_editingTextNode.Id);
            }

            _editingTextNode = null;
            _initialTypographyBeforeEdit = null;
            RefreshCanvas();
            RefreshPropertyInspector();
            Focus();
        }

        private FrameworkElement CreateNumberField(string label, double val, Action<double> onChanged)
        {
            var dock = new DockPanel { Margin = new Thickness(0, 0, 0, 4) };
            var lbl = new TextBlock
            {
                Text = label,
                FontSize = 11,
                Foreground = new SolidColorBrush(Color.FromRgb(130, 140, 160)),
                Width = 48,
                VerticalAlignment = VerticalAlignment.Center
            };
            DockPanel.SetDock(lbl, Dock.Left);
            dock.Children.Add(lbl);

            var border = new Border
            {
                Height = 26,
                Background = new SolidColorBrush(Color.FromRgb(26, 30, 44)),
                BorderBrush = new SolidColorBrush(Color.FromRgb(45, 54, 76)),
                BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(5)
            };
            var tb = new TextBox
            {
                Text = val.ToString("F0"),
                FontSize = 12,
                Background = Brushes.Transparent,
                Foreground = Brushes.White,
                BorderThickness = new Thickness(0),
                Padding = new Thickness(6, 2, 6, 2),
                VerticalContentAlignment = VerticalAlignment.Center
            };
            tb.LostFocus += (s, e) =>
            {
                double d;
                if (double.TryParse(tb.Text, out d)) onChanged(d);
            };
            tb.KeyDown += (s, e) =>
            {
                if (e.Key == Key.Enter)
                {
                    double d;
                    if (double.TryParse(tb.Text, out d)) onChanged(d);
                }
            };
            border.Child = tb;
            dock.Children.Add(border);
            return dock;
        }



        private FrameworkElement CreateColorRow(string label, string hex, Action<string> onChanged)
        {
            var dock = new DockPanel { Margin = new Thickness(0, 0, 0, 6) };
            bool isShort = (label != null && label.Length <= 2);
            var lbl = new TextBlock
            {
                Text = label,
                FontSize = isShort ? 12 : 11,
                Foreground = new SolidColorBrush(Color.FromRgb(130, 140, 160)),
                Width = isShort ? 24 : 48,
                TextAlignment = isShort ? TextAlignment.Center : TextAlignment.Left,
                VerticalAlignment = VerticalAlignment.Center,
                ToolTip = isShort ? "Color Tint" : label
            };
            DockPanel.SetDock(lbl, Dock.Left);
            dock.Children.Add(lbl);

            var swatch = new Border
            {
                Width = 24,
                Height = 24,
                CornerRadius = new CornerRadius(4),
                Background = new SolidColorBrush(GpuRenderer.ParseHexColor(hex, 1.0)),
                BorderBrush = new SolidColorBrush(Color.FromRgb(60, 70, 95)),
                BorderThickness = new Thickness(1),
                Margin = new Thickness(0, 0, 8, 0),
                Cursor = Cursors.Hand,
                ToolTip = "Click to open interactive Color Picker"
            };
            DockPanel.SetDock(swatch, Dock.Left);
            dock.Children.Add(swatch);

            var tbBorder = new Border
            {
                Height = 26,
                Background = new SolidColorBrush(Color.FromRgb(26, 30, 44)),
                BorderBrush = new SolidColorBrush(Color.FromRgb(45, 54, 76)),
                BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(5)
            };
            var tb = new TextBox
            {
                Text = hex,
                FontSize = 12,
                Background = Brushes.Transparent,
                Foreground = Brushes.White,
                BorderThickness = new Thickness(0),
                Padding = new Thickness(6, 2, 6, 2),
                VerticalContentAlignment = VerticalAlignment.Center
            };
            tbBorder.Child = tb;

            swatch.MouseLeftButtonUp += (s, e) =>
            {
                e.Handled = true;
                ColorPickerPopup.ShowAt(swatch, tb.Text, newHex =>
                {
                    tb.Text = newHex;
                    swatch.Background = new SolidColorBrush(GpuRenderer.ParseHexColor(newHex, 1.0));
                    if (onChanged != null) onChanged(newHex);
                });
            };

            tb.TextChanged += (s, e) =>
            {
                if (tb.Text.StartsWith("#") && (tb.Text.Length == 7 || tb.Text.Length == 4 || tb.Text.Length == 9))
                {
                    swatch.Background = new SolidColorBrush(GpuRenderer.ParseHexColor(tb.Text, 1.0));
                    if (onChanged != null) onChanged(tb.Text);
                }
            };

            dock.Children.Add(tbBorder);
            return dock;
        }

        private FrameworkElement CreateSliderRow(string label, double val, Action<double> onChanged)
        {
            var dock = new DockPanel { Margin = new Thickness(0, 0, 0, 6) };
            var lbl = new TextBlock
