        private void RefreshStateMachineValidationBadge()
        {
            if (_stateMachineValidationBadge == null || _timelineController == null || _timelineController.ActiveStateMachine == null) return;
            var sm = _timelineController.ActiveStateMachine;
            if (sm.Definition == null) return;
            var result = StateMachineValidator.Validate(sm.Definition, sm.Clips);
            var errors = new List<ValidationIssue>();
            var warnings = new List<ValidationIssue>();
            if (result.Issues != null)
            {
                for (int i = 0; i < result.Issues.Count; i++)
                {
                    var iss = result.Issues[i];
                    if (iss == null) continue;
                    if (iss.Severity == ValidationSeverity.Error) errors.Add(iss);
                    else if (iss.Severity == ValidationSeverity.Warning) warnings.Add(iss);
                }
            }

            if (errors.Count > 0)
            {
                _stateMachineValidationBadge.Text = string.Format("⚠ {0} Error{1}", errors.Count, errors.Count > 1 ? "s" : "");
                _stateMachineValidationBadge.Foreground = new SolidColorBrush(Color.FromRgb(239, 68, 68));
                _stateMachineValidationBadge.Background = new SolidColorBrush(Color.FromArgb(50, 239, 68, 68));
                var errorMessages = new List<string>();
                for (int i = 0; i < errors.Count; i++)
                {
                    errorMessages.Add("• " + errors[i].Message);
                }
                _stateMachineValidationBadge.ToolTip = string.Join(Environment.NewLine, errorMessages.ToArray());
            }
            else if (warnings.Count > 0)
            {
                _stateMachineValidationBadge.Text = string.Format("⚠ {0} Warning{1}", warnings.Count, warnings.Count > 1 ? "s" : "");
                _stateMachineValidationBadge.Foreground = new SolidColorBrush(Color.FromRgb(245, 158, 11));
                _stateMachineValidationBadge.Background = new SolidColorBrush(Color.FromArgb(50, 245, 158, 11));
                var warnMessages = new List<string>();
                for (int i = 0; i < warnings.Count; i++)
                {
                    warnMessages.Add("• " + warnings[i].Message);
                }
                _stateMachineValidationBadge.ToolTip = string.Join(Environment.NewLine, warnMessages.ToArray());
            }
            else
            {
                _stateMachineValidationBadge.Text = "✓ Valid";
                _stateMachineValidationBadge.Foreground = KerfBrand.MintBrush;
                _stateMachineValidationBadge.Background = new SolidColorBrush(Color.FromArgb(40, 0, 245, 160));
                _stateMachineValidationBadge.ToolTip = "State machine graph is valid with no diagnostics issues.";
            }
        }

        private static List<ConditionGroup> CloneConditionGroups(IEnumerable<ConditionGroup> groups)
        {
            var list = new List<ConditionGroup>();
            if (groups != null)
            {
                foreach (var g in groups)
                {
                    if (g != null) list.Add(g.Clone());
                }
            }
            return list;
        }

        private void RefreshStateMachineInspector()
        {
            if (_stateMachineInspectorContent == null) return;
            _stateMachineInspectorContent.Children.Clear();

            var sm = _timelineController != null ? _timelineController.ActiveStateMachine : null;
            if (sm == null || sm.Definition == null || sm.Definition.Layers == null || sm.Definition.Layers.Count == 0) return;
            var layer = sm.Definition.Layers[0];

            if (_selectedGraphStateIndex >= 0 && _selectedGraphStateIndex < layer.States.Count && layer.States[_selectedGraphStateIndex] != null)
            {
                var state = layer.States[_selectedGraphStateIndex];
                int stateIndex = _selectedGraphStateIndex;

                var card = new Border
                {
                    Background = KerfBrand.FigmaCardBrush,
                    BorderBrush = KerfBrand.FigmaBorderBrush,
                    BorderThickness = new Thickness(1),
                    CornerRadius = new CornerRadius(6),
                    Padding = new Thickness(10)
                };
                var sp = new StackPanel();

                // Header with Kind Badge
                var headerDock = new DockPanel { Margin = new Thickness(0, 0, 0, 10), LastChildFill = false };
                var titleText = new TextBlock
                {
                    Text = "STATE NODE",
                    FontSize = 10,
                    FontWeight = FontWeights.Bold,
                    Foreground = KerfBrand.TextMutedBrush,
                    VerticalAlignment = VerticalAlignment.Center
                };
                DockPanel.SetDock(titleText, Dock.Left);
                headerDock.Children.Add(titleText);

                SolidColorBrush kindBrush;
                if (state.Kind == StateKind.Entry) kindBrush = KerfBrand.MintBrush;
                else if (state.Kind == StateKind.Any) kindBrush = new SolidColorBrush(Color.FromRgb(139, 92, 246));
                else if (state.Kind == StateKind.Exit) kindBrush = new SolidColorBrush(Color.FromRgb(239, 68, 68));
                else kindBrush = new SolidColorBrush(Color.FromRgb(59, 130, 246));

                var kindBadge = new Border
                {
                    Background = kindBrush,
                    CornerRadius = new CornerRadius(4),
                    Padding = new Thickness(6, 2, 6, 2),
                    VerticalAlignment = VerticalAlignment.Center
                };
                kindBadge.Child = new TextBlock
                {
                    Text = state.Kind.ToString().ToUpperInvariant(),
                    FontSize = 9,
                    FontWeight = FontWeights.Bold,
                    Foreground = (state.Kind == StateKind.Entry) ? KerfBrand.TextBlackBrush : Brushes.White
                };
                DockPanel.SetDock(kindBadge, Dock.Right);
                headerDock.Children.Add(kindBadge);
                sp.Children.Add(headerDock);

                // State Name Field
                var nameBox = new TextBox
                {
                    Text = state.Name,
                    Height = 26,
                    Padding = new Thickness(6, 3, 6, 3),
                    Background = KerfBrand.FigmaCanvasBrush,
                    Foreground = Brushes.White,
                    BorderBrush = KerfBrand.FigmaBorderBrush,
                    FontSize = 11
                };
                Action commitStateName = () =>
                {
                    string newName = nameBox.Text.Trim();
                    if (!string.IsNullOrEmpty(newName) && !string.Equals(newName, state.Name, StringComparison.Ordinal))
                    {
                        var cmd = new RenameStateNodeCommand(state, state.Name, newName, () =>
                        {
                            BuildStateMachineStatesGraph();
                            RefreshStateMachineInspector();
                        });
                        if (History != null) History.Execute(cmd);
                        else cmd.Execute();
                    }
                };
                nameBox.LostKeyboardFocus += (s, e) => commitStateName();
                nameBox.KeyDown += (s, e) => { if (e.Key == Key.Enter) { commitStateName(); Keyboard.ClearFocus(); } };
                sp.Children.Add(CreateTransitionFormRow("Name", nameBox));

                // Animation Clip Dropdown (if Animation node)
                if (state.Kind == StateKind.Animation)
                {
                    var clipBox = CreateModernComboBox(26);
                    int selIdx = -1;
                    var clipsList = (sm.Clips != null && sm.Clips.Count > 0) ? sm.Clips : (Document != null && Document.Animation != null ? Document.Animation.Clips : null);
                    if (clipsList != null)
                    {
                        for (int c = 0; c < clipsList.Count; c++)
                        {
                            var clip = clipsList[c];
                            if (clip == null) continue;
                            var item = new ComboBoxItem { Content = clip.Name, Tag = c };
                            clipBox.Items.Add(item);
                            if (c == state.ClipIndex) selIdx = clipBox.Items.Count - 1;
                        }
                    }
                    if (selIdx >= 0) clipBox.SelectedIndex = selIdx;
                    else if (clipBox.Items.Count > 0) clipBox.SelectedIndex = 0;
                    clipBox.SelectionChanged += (s, e) =>
                    {
                        var selItem = clipBox.SelectedItem as ComboBoxItem;
                        if (selItem != null && selItem.Tag is int)
                        {
                            state.ClipIndex = (int)selItem.Tag;
                            BuildStateMachineStatesGraph();
                            if (History != null) History.MarkDirty();
                        }
                    };
                    sp.Children.Add(CreateTransitionFormRow("Clip", clipBox));

                    // Speed Scrub
                    var speedBox = new TextBox
                    {
                        Text = state.Speed.ToString("0.##", CultureInfo.InvariantCulture),
                        Height = 26,
                        Padding = new Thickness(6, 3, 6, 3),
                        Background = KerfBrand.FigmaCanvasBrush,
                        Foreground = Brushes.White,
                        BorderBrush = KerfBrand.FigmaBorderBrush,
                        FontSize = 11
                    };
                    Action commitSpeed = () =>
                    {
                        double spd;
                        if (double.TryParse(speedBox.Text, NumberStyles.Float, CultureInfo.InvariantCulture, out spd))
                        {
                            state.Speed = Math.Max(0.1, Math.Min(10.0, spd));
                            speedBox.Text = state.Speed.ToString("0.##", CultureInfo.InvariantCulture);
                            if (History != null) History.MarkDirty();
                        }
                    };
                    speedBox.LostKeyboardFocus += (s, e) => commitSpeed();
                    speedBox.KeyDown += (s, e) => { if (e.Key == Key.Enter) { commitSpeed(); Keyboard.ClearFocus(); } };
                    sp.Children.Add(CreateTransitionFormRow("Speed", speedBox));

                    // Playback Behaviour (Loop, Once, PingPong)
                    var loopCombo = CreateModernComboBox(26);
                    loopCombo.Items.Add(new ComboBoxItem { Content = "Loop (Continuous)", Tag = LoopMode.Loop });
                    loopCombo.Items.Add(new ComboBoxItem { Content = "Once (Hold at end)", Tag = LoopMode.OneShot });
                    loopCombo.Items.Add(new ComboBoxItem { Content = "PingPong (Back & forth)", Tag = LoopMode.PingPong });
                    loopCombo.SelectedIndex = state.LoopMode == LoopMode.Loop ? 0 : (state.LoopMode == LoopMode.PingPong ? 2 : 1);
                    loopCombo.SelectionChanged += (s, e) =>
                    {
                        var selItem = loopCombo.SelectedItem as ComboBoxItem;
                        if (selItem != null && selItem.Tag is LoopMode)
                        {
                            var mode = (LoopMode)selItem.Tag;
                            if (state.LoopMode == mode) return;
                            var before = new StateSnapshot(state);
                            var after = before.Clone();
                            after.LoopMode = mode;
                            after.Loop = mode != LoopMode.OneShot;
                            var command = new ModifyStateNodeCommand(state, before, after, () =>
                            {
                                if (History != null) History.MarkDirty();
                                RefreshStateMachineInspector();
                                BuildStateMachineStatesGraph();
                            });
                            if (History != null) History.Execute(command); else command.Execute();
                        }
                    };
                    sp.Children.Add(CreateTransitionFormRow("Playback", loopCombo));
                }

                // Delete State Button (for non-Entry states)
                if (state.Kind != StateKind.Entry)
                {
                    var delBtn = KerfBrand.CreateSecondaryButton("Delete State", () =>
                    {
                        var cmd = new DeleteStateNodesCommand(layer, state, () =>
                        {
                            _selectedGraphStateIndex = -1;
                            _selectedGraphStateIndices.Clear();
                            _selectedGraphTransition = null;
                            BuildStateMachineStatesGraph();
                            BuildStateMachineAnimationsList();
                            RefreshStateMachineInspector();
                            RefreshStateMachineValidationBadge();
                        });
                        if (History != null) History.Execute(cmd);
                        else cmd.Execute();
                    }, 4);
                    delBtn.Height = 24;
                    delBtn.Margin = new Thickness(0, 8, 0, 0);
                    sp.Children.Add(delBtn);
                }

                card.Child = sp;
                _stateMachineInspectorContent.Children.Add(card);
            }
            else if (_selectedGraphTransition != null)
            {
                var trans = _selectedGraphTransition;
                var transLayer = _selectedGraphTransitionLayer ?? layer;

                var card = new Border
                {
                    Background = KerfBrand.FigmaCardBrush,
                    BorderBrush = KerfBrand.FigmaBorderBrush,
                    BorderThickness = new Thickness(1),
                    CornerRadius = new CornerRadius(6),
                    Padding = new Thickness(10)
                };
                var sp = new StackPanel();

                // Header
                var fromState = (trans.FromState >= 0 && trans.FromState < transLayer.States.Count) ? transLayer.States[trans.FromState] : null;
                var toState = (trans.ToState >= 0 && trans.ToState < transLayer.States.Count) ? transLayer.States[trans.ToState] : null;
                string fromName = fromState != null ? fromState.Name : "From";
                string toName = toState != null ? toState.Name : "To";

                var headerText = new TextBlock
                {
                    Text = string.Format("TRANSITION: {0} ➔ {1}", fromName, toName),
                    FontSize = 10,
                    FontWeight = FontWeights.Bold,
                    Foreground = KerfBrand.MintBrush,
                    Margin = new Thickness(0, 0, 0, 10),
                    TextWrapping = TextWrapping.Wrap
                };
                sp.Children.Add(headerText);

                // Duration Scrub
                var durBox = new TextBox
                {
                    Text = trans.Duration.ToString("0.##", CultureInfo.InvariantCulture),
                    Height = 26,
                    Padding = new Thickness(6, 3, 6, 3),
                    Background = KerfBrand.FigmaCanvasBrush,
                    Foreground = Brushes.White,
                    BorderBrush = KerfBrand.FigmaBorderBrush,
                    FontSize = 11
                };
                Action commitDuration = () =>
                {
                    double d;
                    if (double.TryParse(durBox.Text, NumberStyles.Float, CultureInfo.InvariantCulture, out d))
                    {
                        d = Math.Max(0.0, d);
                        if (Math.Abs(d - trans.Duration) > 0.001)
                        {
                            var oldSnap = new TransitionSnapshot(trans);
                            var newSnap = new TransitionSnapshot(trans) { Duration = d };
                            var cmd = new ModifyTransitionCommand(trans, oldSnap, newSnap, () =>
                            {
                                BuildStateMachineStatesGraph();
                                RefreshStateMachineInspector();
                            });
                            if (History != null) History.Execute(cmd);
                            else cmd.Execute();
                        }
                    }
                };
                durBox.LostKeyboardFocus += (s, e) => commitDuration();
                durBox.KeyDown += (s, e) => { if (e.Key == Key.Enter) { commitDuration(); Keyboard.ClearFocus(); } };
                sp.Children.Add(CreateTransitionFormRow("Blend (s)", durBox));

                // Easing Mode
                var easeBox = CreateModernComboBox(26);
                foreach (InterpMode m in new[] { InterpMode.Hold, InterpMode.Linear, InterpMode.Cubic })
                    easeBox.Items.Add(new ComboBoxItem { Content = m.ToString(), Tag = m });
                easeBox.SelectedIndex = (int)trans.Interpolation;
                easeBox.SelectionChanged += (s, e) =>
                {
                    var item = easeBox.SelectedItem as ComboBoxItem;
                    if (item != null && item.Tag is InterpMode)
                    {
                        var mode = (InterpMode)item.Tag;
                        if (mode != trans.Interpolation)
                        {
                            var oldSnap = new TransitionSnapshot(trans);
                            var newSnap = new TransitionSnapshot(trans) { Interpolation = mode };
                            var cmd = new ModifyTransitionCommand(trans, oldSnap, newSnap, () =>
                            {
                                BuildStateMachineStatesGraph();
                            });
                            if (History != null) History.Execute(cmd);
                            else cmd.Execute();
                        }
                    }
                };
                sp.Children.Add(CreateTransitionFormRow("Easing", easeBox));

                // Exit Time Toggle
                var exitCheck = new CheckBox
                {
                    Content = "Has Exit Time",
                    IsChecked = trans.ExitTime.HasValue,
                    Foreground = Brushes.White,
                    FontSize = 11,
                    Margin = new Thickness(0, 4, 0, 4),
                    Cursor = Cursors.Hand
                };
                exitCheck.Click += (s, e) =>
                {
                    var oldSnap = new TransitionSnapshot(trans);
                    var newSnap = new TransitionSnapshot(trans);
                    newSnap.ExitTime = (exitCheck.IsChecked == true) ? (double?)0.9 : null;
                    var cmd = new ModifyTransitionCommand(trans, oldSnap, newSnap, () =>
                    {
                        RefreshStateMachineInspector();
                    });
                    if (History != null) History.Execute(cmd);
                    else cmd.Execute();
                };
                sp.Children.Add(exitCheck);

                if (trans.ExitTime.HasValue)
                {
                    var exitSliderDock = new DockPanel { Margin = new Thickness(0, 0, 0, 6) };
                    var exitValText = new TextBlock
                    {
                        Text = trans.ExitTime.Value.ToString("0.00", CultureInfo.InvariantCulture),
                        FontSize = 10,
                        Foreground = KerfBrand.MintBrush,
                        Width = 32,
                        TextAlignment = TextAlignment.Right,
                        VerticalAlignment = VerticalAlignment.Center
                    };
                    DockPanel.SetDock(exitValText, Dock.Right);
                    exitSliderDock.Children.Add(exitValText);

                    var exitSlider = new Slider
                    {
                        Minimum = 0.0,
                        Maximum = 1.0,
                        Value = trans.ExitTime.Value,
                        SmallChange = 0.05,
                        LargeChange = 0.1,
                        VerticalAlignment = VerticalAlignment.Center,
                        Margin = new Thickness(0, 0, 8, 0)
                    };
                    exitSlider.ValueChanged += (s, e) =>
                    {
                        exitValText.Text = exitSlider.Value.ToString("0.00", CultureInfo.InvariantCulture);
                    };
                    exitSlider.PreviewMouseUp += (s, e) =>
                    {
                        double val = Math.Max(0.0, Math.Min(1.0, exitSlider.Value));
                        if (Math.Abs(val - (trans.ExitTime ?? 0.0)) > 0.01)
                        {
                            var oldSnap = new TransitionSnapshot(trans);
                            var newSnap = new TransitionSnapshot(trans) { ExitTime = val };
                            var cmd = new ModifyTransitionCommand(trans, oldSnap, newSnap, () => { RefreshStateMachineInspector(); });
                            if (History != null) History.Execute(cmd);
                            else cmd.Execute();
                        }
                    };
                    exitSliderDock.Children.Add(exitSlider);
                    sp.Children.Add(exitSliderDock);
                }

                // Interruption Toggle
                var intCheck = new CheckBox
                {
                    Content = "Can Interrupt",
                    IsChecked = trans.Interrupt,
                    Foreground = Brushes.White,
                    FontSize = 11,
                    Margin = new Thickness(0, 0, 0, 8),
                    Cursor = Cursors.Hand
                };
                intCheck.Click += (s, e) =>
                {
                    var oldSnap = new TransitionSnapshot(trans);
                    var newSnap = new TransitionSnapshot(trans) { Interrupt = (intCheck.IsChecked == true) };
                    var cmd = new ModifyTransitionCommand(trans, oldSnap, newSnap, () => { });
                    if (History != null) History.Execute(cmd);
                    else cmd.Execute();
                };
                sp.Children.Add(intCheck);

                // Compound Condition Group Builder (D-03)
                var condHeaderDock = new DockPanel { Margin = new Thickness(0, 10, 0, 6) };
                var condTitle = new TextBlock
                {
                    Text = "CONDITIONS (OR of ANDs)",
                    FontSize = 9.5,
                    FontWeight = FontWeights.Bold,
                    Foreground = KerfBrand.TextMutedBrush,
                    VerticalAlignment = VerticalAlignment.Center
                };
                DockPanel.SetDock(condTitle, Dock.Left);
                condHeaderDock.Children.Add(condTitle);
                sp.Children.Add(condHeaderDock);

                if (trans.ConditionGroups == null) trans.ConditionGroups = new List<ConditionGroup>();

                for (int g = 0; g < trans.ConditionGroups.Count; g++)
                {
                    int groupIndex = g;
                    var group = trans.ConditionGroups[g];
                    if (group == null) continue;

                    if (g > 0)
                    {
                        var orDock = new DockPanel { Margin = new Thickness(0, 4, 0, 4), LastChildFill = false };
                        var orBadge = new Border
                        {
                            Background = new SolidColorBrush(Color.FromRgb(39, 44, 57)),
                            BorderBrush = new SolidColorBrush(Color.FromRgb(139, 92, 246)),
                            BorderThickness = new Thickness(1),
                            CornerRadius = new CornerRadius(10),
                            Padding = new Thickness(8, 2, 8, 2),
                            HorizontalAlignment = HorizontalAlignment.Center
                        };
                        orBadge.Child = new TextBlock
                        {
                            Text = "OR",
                            FontSize = 8.5,
                            FontWeight = FontWeights.Bold,
                            Foreground = new SolidColorBrush(Color.FromRgb(196, 181, 253))
                        };
                        orDock.Children.Add(orBadge);
                        sp.Children.Add(orDock);
                    }

                    var grpCard = new Border
                    {
                        Background = new SolidColorBrush(Color.FromRgb(24, 27, 34)),
                        BorderBrush = KerfBrand.FigmaBorderBrush,
                        BorderThickness = new Thickness(1),
                        CornerRadius = new CornerRadius(5),
                        Padding = new Thickness(6),
                        Margin = new Thickness(0, 0, 0, 4)
                    };
                    var grpStack = new StackPanel();

                    var grpHeader = new DockPanel { Margin = new Thickness(0, 0, 0, 4), LastChildFill = true };
                    var grpLabel = new TextBlock
                    {
                        Text = string.Format("GROUP {0}", groupIndex + 1),
                        FontSize = 8.5,
                        FontWeight = FontWeights.SemiBold,
                        Foreground = KerfBrand.TextMutedBrush,
                        VerticalAlignment = VerticalAlignment.Center
                    };
                    DockPanel.SetDock(grpLabel, Dock.Left);
                    grpHeader.Children.Add(grpLabel);

                    var delGrpBtn = new Border
                    {
                        Width = 16,
                        Height = 16,
                        Background = Brushes.Transparent,
                        Cursor = Cursors.Hand,
                        ToolTip = "Remove Condition Group",
                        VerticalAlignment = VerticalAlignment.Center
                    };
                    var delGrpText = new TextBlock
                    {
                        Text = "×",
                        FontSize = 13,
                        Foreground = new SolidColorBrush(Color.FromRgb(140, 150, 165)),
                        HorizontalAlignment = HorizontalAlignment.Center,
                        VerticalAlignment = VerticalAlignment.Center
                    };
                    delGrpBtn.Child = delGrpText;
                    delGrpBtn.MouseEnter += (s, e) => { delGrpText.Foreground = new SolidColorBrush(Color.FromRgb(239, 68, 68)); };
                    delGrpBtn.MouseLeave += (s, e) => { delGrpText.Foreground = new SolidColorBrush(Color.FromRgb(140, 150, 165)); };
                    delGrpBtn.MouseLeftButtonDown += (s, e) =>
                    {
                        var oldGroups = CloneConditionGroups(trans.ConditionGroups);
                        var newGroups = CloneConditionGroups(trans.ConditionGroups);
                        if (groupIndex >= 0 && groupIndex < newGroups.Count)
                        {
                            newGroups.RemoveAt(groupIndex);
                            var cmd = new ModifyConditionGroupsCommand(trans, oldGroups, newGroups, () =>
                            {
                                BuildStateMachineStatesGraph();
                                RefreshStateMachineInspector();
                            });
                            if (History != null) History.Execute(cmd);
                            else cmd.Execute();
                        }
                    };
                    DockPanel.SetDock(delGrpBtn, Dock.Right);
                    grpHeader.Children.Add(delGrpBtn);
                    grpStack.Children.Add(grpHeader);

                    if (group.Conditions == null) group.Conditions = new List<TransitionCondition>();

                    for (int c = 0; c < group.Conditions.Count; c++)
                    {
                        int conditionIndex = c;
                        var cond = group.Conditions[c];
                        if (cond == null) continue;

                        if (conditionIndex > 0)
                        {
                            var andBadge = new Border
                            {
                                Background = new SolidColorBrush(Color.FromRgb(30, 41, 59)),
                                CornerRadius = new CornerRadius(3),
                                Padding = new Thickness(4, 1, 4, 1),
                                Margin = new Thickness(0, 2, 0, 2),
                                HorizontalAlignment = HorizontalAlignment.Center
                            };
                            andBadge.Child = new TextBlock
                            {
                                Text = "AND",
                                FontSize = 7.5,
                                FontWeight = FontWeights.Bold,
                                Foreground = new SolidColorBrush(Color.FromRgb(148, 163, 184))
                            };
                            grpStack.Children.Add(andBadge);
                        }

                        var condRow = new DockPanel { Margin = new Thickness(0, 2, 0, 2), LastChildFill = true };

                        var delCondBtn = new Border
                        {
                            Width = 16,
                            Height = 16,
                            Background = Brushes.Transparent,
                            Cursor = Cursors.Hand,
                            ToolTip = "Remove condition",
                            VerticalAlignment = VerticalAlignment.Center,
                            Margin = new Thickness(2, 0, 0, 0)
                        };
                        var delCondText = new TextBlock
                        {
                            Text = "×",
                            FontSize = 12,
                            Foreground = new SolidColorBrush(Color.FromRgb(140, 150, 165)),
                            HorizontalAlignment = HorizontalAlignment.Center,
                            VerticalAlignment = VerticalAlignment.Center
                        };
                        delCondBtn.Child = delCondText;
                        delCondBtn.MouseEnter += (s, e) => { delCondText.Foreground = new SolidColorBrush(Color.FromRgb(239, 68, 68)); };
                        delCondBtn.MouseLeave += (s, e) => { delCondText.Foreground = new SolidColorBrush(Color.FromRgb(140, 150, 165)); };
                        delCondBtn.MouseLeftButtonDown += (s, e) =>
                        {
                            var oldGroups = CloneConditionGroups(trans.ConditionGroups);
                            var newGroups = CloneConditionGroups(trans.ConditionGroups);
                            if (groupIndex < newGroups.Count && conditionIndex < newGroups[groupIndex].Conditions.Count)
                            {
                                newGroups[groupIndex].Conditions.RemoveAt(conditionIndex);
                                var cmd = new ModifyConditionGroupsCommand(trans, oldGroups, newGroups, () =>
                                {
                                    BuildStateMachineStatesGraph();
                                    RefreshStateMachineInspector();
                                });
                                if (History != null) History.Execute(cmd);
                                else cmd.Execute();
                            }
                        };
                        DockPanel.SetDock(delCondBtn, Dock.Right);
                        condRow.Children.Add(delCondBtn);

                        var inBox = CreateModernComboBox(22);
                        inBox.FontSize = 10;
                        inBox.Width = 78;
                        DockPanel.SetDock(inBox, Dock.Left);

                        int selInIdx = -1;
                        MachineInput activeInput = null;
                        if (sm.Definition != null && sm.Definition.Inputs != null)
                        {
                            for (int i = 0; i < sm.Definition.Inputs.Count; i++)
                            {
                                var inp = sm.Definition.Inputs[i];
                                if (inp == null || inp.Kind == InputKind.Folder) continue;
                                string prefix = (inp.Kind == InputKind.Trigger) ? "⚡ " : (inp.Kind == InputKind.Bool ? "⏻ " : "🎚 ");
                                var item = new ComboBoxItem { Content = prefix + inp.Name, Tag = inp.InputId };
                                inBox.Items.Add(item);
                                if (string.Equals(cond.InputId, inp.InputId, StringComparison.Ordinal) ||
                                    string.Equals(cond.PropertyName, inp.Name, StringComparison.OrdinalIgnoreCase) ||
                                    cond.InputIndex == i)
                                {
                                    selInIdx = inBox.Items.Count - 1;
                                    activeInput = inp;
                                }
                            }
                        }
                        if (selInIdx >= 0) inBox.SelectedIndex = selInIdx;
                        else if (inBox.Items.Count > 0)
                        {
                            inBox.SelectedIndex = 0;
                            var firstInputItem = inBox.Items[0] as ComboBoxItem;
                            if (firstInputItem != null && firstInputItem.Tag is string && sm.Definition != null)
                                activeInput = sm.Definition.FindInputById((string)firstInputItem.Tag);
                        }

                        inBox.SelectionChanged += (s, e) =>
                        {
                            var selItem = inBox.SelectedItem as ComboBoxItem;
                            if (selItem != null && selItem.Tag is string)
                            {
                                string chosenId = (string)selItem.Tag;
                                var chosenIn = sm.Definition != null ? sm.Definition.FindInputById(chosenId) : null;
                                if (chosenIn != null)
                                {
                                    var oldGroups = CloneConditionGroups(trans.ConditionGroups);
                                    var newGroups = CloneConditionGroups(trans.ConditionGroups);
                                    if (groupIndex < newGroups.Count && conditionIndex < newGroups[groupIndex].Conditions.Count)
                                    {
                                        var targetC = newGroups[groupIndex].Conditions[conditionIndex];
                                        targetC.InputId = chosenIn.InputId;
                                        targetC.PropertyName = chosenIn.Name;
                                        targetC.InputIndex = sm.Definition.Inputs.IndexOf(chosenIn);
                                        if (chosenIn.Kind == InputKind.Bool && targetC.Value == 0.0)
                                        {
                                            targetC.Value = 1.0;
                                        }
                                        var cmd = new ModifyConditionGroupsCommand(trans, oldGroups, newGroups, () =>
                                        {
                                            BuildStateMachineStatesGraph();
                                            RefreshStateMachineInspector();
                                        });
                                        if (History != null) History.Execute(cmd);
                                        else cmd.Execute();
                                    }
                                }
                            }
                        };
                        condRow.Children.Add(inBox);

                        if (activeInput != null && activeInput.Kind == InputKind.Trigger)
                        {
                            var trgLabel = new Border
                            {
                                Background = new SolidColorBrush(Color.FromArgb(40, 139, 92, 246)),
                                CornerRadius = new CornerRadius(3),
                                Padding = new Thickness(6, 2, 6, 2),
                                Margin = new Thickness(4, 0, 0, 0),
                                HorizontalAlignment = HorizontalAlignment.Left
                            };
                            trgLabel.Child = new TextBlock
                            {
                                Text = "Fires",
                                FontSize = 9.5,
                                FontWeight = FontWeights.SemiBold,
                                Foreground = new SolidColorBrush(Color.FromRgb(196, 181, 253))
                            };
                            condRow.Children.Add(trgLabel);
                        }
                        else
                        {
                            var opBox = CreateModernComboBox(22);
                            opBox.FontSize = 10;
                            opBox.Width = 44;
                            opBox.Margin = new Thickness(4, 0, 0, 0);
                            DockPanel.SetDock(opBox, Dock.Left);

                            ConditionOp[] ops = new[] { ConditionOp.Eq, ConditionOp.Ne, ConditionOp.Lt, ConditionOp.Le, ConditionOp.Gt, ConditionOp.Ge };
                            string[] opSymbols = new[] { "==", "!=", "<", "<=", ">", ">=" };
                            for (int o = 0; o < ops.Length; o++)
                            {
                                opBox.Items.Add(new ComboBoxItem { Content = opSymbols[o], Tag = ops[o] });
                                if (cond.Op == ops[o]) opBox.SelectedIndex = o;
                            }
                            if (opBox.SelectedIndex < 0) opBox.SelectedIndex = 0;

                            opBox.SelectionChanged += (s, e) =>
                            {
                                var selItem = opBox.SelectedItem as ComboBoxItem;
                                if (selItem != null && selItem.Tag is ConditionOp)
                                {
                                    var chosenOp = (ConditionOp)selItem.Tag;
                                    if (chosenOp != cond.Op)
                                    {
                                        var oldGroups = CloneConditionGroups(trans.ConditionGroups);
                                        var newGroups = CloneConditionGroups(trans.ConditionGroups);
                                        if (groupIndex < newGroups.Count && conditionIndex < newGroups[groupIndex].Conditions.Count)
                                        {
                                            newGroups[groupIndex].Conditions[conditionIndex].Op = chosenOp;
                                            var cmd = new ModifyConditionGroupsCommand(trans, oldGroups, newGroups, () =>
                                            {
                                                BuildStateMachineStatesGraph();
                                                RefreshStateMachineInspector();
                                            });
                                            if (History != null) History.Execute(cmd);
                                            else cmd.Execute();
                                        }
                                    }
                                }
                            };
                            condRow.Children.Add(opBox);

                            if (activeInput != null && activeInput.Kind == InputKind.Bool)
                            {
                                var boolBox = CreateModernComboBox(22);
                                boolBox.FontSize = 10;
                                boolBox.Margin = new Thickness(4, 0, 0, 0);
                                boolBox.Items.Add(new ComboBoxItem { Content = "true", Tag = 1.0 });
                                boolBox.Items.Add(new ComboBoxItem { Content = "false", Tag = 0.0 });
                                boolBox.SelectedIndex = (cond.Value > 0.5) ? 0 : 1;
                                boolBox.SelectionChanged += (s, e) =>
                                {
                                    var selItem = boolBox.SelectedItem as ComboBoxItem;
                                    if (selItem != null && selItem.Tag is double)
                                    {
                                        double bVal = (double)selItem.Tag;
                                        if (Math.Abs(bVal - cond.Value) > 0.001)
                                        {
                                            var oldGroups = CloneConditionGroups(trans.ConditionGroups);
                                            var newGroups = CloneConditionGroups(trans.ConditionGroups);
                                            if (groupIndex < newGroups.Count && conditionIndex < newGroups[groupIndex].Conditions.Count)
                                            {
                                                newGroups[groupIndex].Conditions[conditionIndex].Value = bVal;
                                                var cmd = new ModifyConditionGroupsCommand(trans, oldGroups, newGroups, () =>
                                                {
                                                    BuildStateMachineStatesGraph();
                                                    RefreshStateMachineInspector();
                                                });
                                                if (History != null) History.Execute(cmd);
                                                else cmd.Execute();
                                            }
                                        }
                                    }
                                };
                                condRow.Children.Add(boolBox);
                            }
                            else
                            {
                                var valBox = new TextBox
                                {
                                    Text = cond.Value.ToString("0.##", CultureInfo.InvariantCulture),
                                    Height = 22,
                                    Padding = new Thickness(4, 1, 4, 1),
                                    Margin = new Thickness(4, 0, 0, 0),
                                    Background = KerfBrand.FigmaCanvasBrush,
                                    Foreground = Brushes.White,
                                    BorderBrush = KerfBrand.FigmaBorderBrush,
                                    FontSize = 10
                                };
                                Action commitCondVal = () =>
                                {
                                    double parsed;
                                    if (double.TryParse(valBox.Text, NumberStyles.Float, CultureInfo.InvariantCulture, out parsed))
                                    {
                                        if (Math.Abs(parsed - cond.Value) > 0.001)
                                        {
                                            var oldGroups = CloneConditionGroups(trans.ConditionGroups);
                                            var newGroups = CloneConditionGroups(trans.ConditionGroups);
                                            if (groupIndex < newGroups.Count && conditionIndex < newGroups[groupIndex].Conditions.Count)
                                            {
                                                newGroups[groupIndex].Conditions[conditionIndex].Value = parsed;
                                                var cmd = new ModifyConditionGroupsCommand(trans, oldGroups, newGroups, () =>
                                                {
                                                    BuildStateMachineStatesGraph();
                                                    RefreshStateMachineInspector();
                                                });
                                                if (History != null) History.Execute(cmd);
                                                else cmd.Execute();
                                            }
                                        }
                                    }
                                };
                                valBox.LostKeyboardFocus += (s, e) => commitCondVal();
                                valBox.KeyDown += (s, e) => { if (e.Key == Key.Enter) { commitCondVal(); Keyboard.ClearFocus(); } };
                                condRow.Children.Add(valBox);
                            }
                        }

                        grpStack.Children.Add(condRow);
                    }

                    var addCondBtn = new Border
                    {
                        Background = Brushes.Transparent,
                        BorderBrush = KerfBrand.FigmaBorderBrush,
                        BorderThickness = new Thickness(1),
                        CornerRadius = new CornerRadius(3),
                        Padding = new Thickness(6, 2, 6, 2),
                        Margin = new Thickness(0, 4, 0, 0),
                        Cursor = Cursors.Hand,
                        HorizontalAlignment = HorizontalAlignment.Left
                    };
                    addCondBtn.Child = new TextBlock
                    {
                        Text = "+ Add Condition",
                        FontSize = 9.5,
                        FontWeight = FontWeights.Medium,
                        Foreground = KerfBrand.MintBrush
                    };
                    addCondBtn.MouseLeftButtonDown += (s, e) =>
                    {
                        var oldGroups = CloneConditionGroups(trans.ConditionGroups);
                        var newGroups = CloneConditionGroups(trans.ConditionGroups);
                        if (groupIndex < newGroups.Count)
                        {
                            var firstInput = sm.Definition != null && sm.Definition.Inputs != null
                                ? sm.Definition.Inputs.FirstOrDefault(input => input != null && input.Kind != InputKind.Folder) : null;
                            string firstId = firstInput != null ? firstInput.InputId : null;
                            string firstName = firstInput != null ? firstInput.Name : null;
                            double defaultCondVal = (firstInput != null && firstInput.Kind == InputKind.Bool) ? 1.0 : 0.0;
                            if (firstInput != null && firstInput.Kind == InputKind.Bool && layer != null && layer.Transitions != null)
                            {
                                for (int ti = 0; ti < layer.Transitions.Count; ti++)
                                {
                                    var opp = layer.Transitions[ti];
                                    if (opp != null && opp.FromState == trans.ToState && opp.ToState == trans.FromState && opp.ConditionGroups != null)
                                    {
                                        for (int gi = 0; gi < opp.ConditionGroups.Count; gi++)
                                        {
                                            var grp = opp.ConditionGroups[gi];
                                            if (grp != null && grp.Conditions != null)
                                            {
                                                for (int ci = 0; ci < grp.Conditions.Count; ci++)
                                                {
                                                    if (grp.Conditions[ci] != null && grp.Conditions[ci].Value > 0.5)
                                                    {
                                                        defaultCondVal = 0.0;
                                                        break;
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                            newGroups[groupIndex].Conditions.Add(new TransitionCondition(firstId, ConditionOp.Eq, defaultCondVal, true) { PropertyName = firstName });
                            var cmd = new ModifyConditionGroupsCommand(trans, oldGroups, newGroups, () =>
                            {
                                BuildStateMachineStatesGraph();
                                RefreshStateMachineInspector();
                            });
                            if (History != null) History.Execute(cmd);
                            else cmd.Execute();
                        }
                    };
                    grpStack.Children.Add(addCondBtn);

                    grpCard.Child = grpStack;
                    sp.Children.Add(grpCard);
                }

                // + Add Condition Group (OR) button
                var addGrpBtn = new Border
                {
                    Background = new SolidColorBrush(Color.FromArgb(20, 139, 92, 246)),
                    BorderBrush = new SolidColorBrush(Color.FromArgb(80, 139, 92, 246)),
                    BorderThickness = new Thickness(1),
                    CornerRadius = new CornerRadius(4),
                    Padding = new Thickness(8, 4, 8, 4),
                    Margin = new Thickness(0, 6, 0, 8),
                    Cursor = Cursors.Hand,
                    HorizontalAlignment = HorizontalAlignment.Stretch
                };
                addGrpBtn.Child = new TextBlock
                {
                    Text = "+ Add Condition Group (OR)",
                    FontSize = 10,
                    FontWeight = FontWeights.SemiBold,
                    Foreground = new SolidColorBrush(Color.FromRgb(196, 181, 253)),
                    HorizontalAlignment = HorizontalAlignment.Center
                };
                addGrpBtn.MouseLeftButtonDown += (s, e) =>
                {
                    var oldGroups = CloneConditionGroups(trans.ConditionGroups);
                    var newGroups = CloneConditionGroups(trans.ConditionGroups);
                    var newGrp = new ConditionGroup();
                    if (sm.Definition != null && sm.Definition.Inputs != null && sm.Definition.Inputs.Any(input => input != null && input.Kind != InputKind.Folder))
                    {
                        var firstInp = sm.Definition.Inputs.FirstOrDefault(input => input != null && input.Kind != InputKind.Folder);
                        double defaultCondVal = (firstInp != null && firstInp.Kind == InputKind.Bool) ? 1.0 : 0.0;
                        if (firstInp != null && firstInp.Kind == InputKind.Bool && layer != null && layer.Transitions != null)
                        {
                            for (int ti = 0; ti < layer.Transitions.Count; ti++)
                            {
                                var opp = layer.Transitions[ti];
                                if (opp != null && opp.FromState == trans.ToState && opp.ToState == trans.FromState && opp.ConditionGroups != null)
                                {
                                    for (int gi = 0; gi < opp.ConditionGroups.Count; gi++)
                                    {
                                        var grp = opp.ConditionGroups[gi];
                                        if (grp != null && grp.Conditions != null)
                                        {
                                            for (int ci = 0; ci < grp.Conditions.Count; ci++)
                                            {
                                                if (grp.Conditions[ci] != null && grp.Conditions[ci].Value > 0.5)
                                                {
                                                    defaultCondVal = 0.0;
                                                    break;
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                        newGrp.Conditions.Add(new TransitionCondition(firstInp.InputId, ConditionOp.Eq, defaultCondVal, true) { PropertyName = firstInp.Name });
                    }
                    newGroups.Add(newGrp);
                    var cmd = new ModifyConditionGroupsCommand(trans, oldGroups, newGroups, () =>
                    {
                        BuildStateMachineStatesGraph();
                        RefreshStateMachineInspector();
                    });
                    if (History != null) History.Execute(cmd);
                    else cmd.Execute();
                };
                sp.Children.Add(addGrpBtn);

                // Delete Transition Button
                var delTransBtn = KerfBrand.CreateSecondaryButton("Delete Transition", () =>
                {
                    var cmd = new DeleteTransitionsCommand(transLayer, trans, () =>
                    {
                        _selectedGraphTransition = null;
                        _selectedGraphTransitionLayer = null;
                        BuildStateMachineStatesGraph();
                        RefreshStateMachineInspector();
                        RefreshStateMachineValidationBadge();
                    });
                    if (History != null) History.Execute(cmd);
                    else cmd.Execute();
                }, 4);
                delTransBtn.Height = 24;
                delTransBtn.Margin = new Thickness(0, 6, 0, 0);
                sp.Children.Add(delTransBtn);

                card.Child = sp;
                _stateMachineInspectorContent.Children.Add(card);
            }
            else
            {
                // General Properties
                var card = new Border
                {
                    Background = KerfBrand.FigmaCardBrush,
                    BorderBrush = KerfBrand.FigmaBorderBrush,
                    BorderThickness = new Thickness(1),
                    CornerRadius = new CornerRadius(6),
                    Padding = new Thickness(10)
                };
                var sp = new StackPanel();

                var title = new TextBlock
                {
                    Text = "GRAPH PROPERTIES",
                    FontSize = 10,
                    FontWeight = FontWeights.Bold,
                    Foreground = KerfBrand.TextMutedBrush,
                    Margin = new Thickness(0, 0, 0, 10)
                };
                sp.Children.Add(title);

                sp.Children.Add(new TextBlock { Text = "Layer: " + layer.Name, FontSize = 11, Foreground = Brushes.White, Margin = new Thickness(0, 0, 0, 4) });
                sp.Children.Add(new TextBlock { Text = string.Format("States: {0}", layer.States != null ? layer.States.Count : 0), FontSize = 11, Foreground = KerfBrand.TextMutedBrush, Margin = new Thickness(0, 0, 0, 4) });
                sp.Children.Add(new TextBlock { Text = string.Format("Transitions: {0}", layer.Transitions != null ? layer.Transitions.Count : 0), FontSize = 11, Foreground = KerfBrand.TextMutedBrush, Margin = new Thickness(0, 0, 0, 4) });
                sp.Children.Add(new TextBlock { Text = string.Format("Inputs: {0}", sm.Definition.Inputs != null ? sm.Definition.Inputs.Count : 0), FontSize = 11, Foreground = KerfBrand.TextMutedBrush, Margin = new Thickness(0, 0, 0, 10) });

                sp.Children.Add(new TextBlock { Text = "Select a state node or transition in the graph to inspect and edit its properties.", FontSize = 10, Foreground = new SolidColorBrush(Color.FromRgb(100, 116, 139)), TextWrapping = TextWrapping.Wrap });

                card.Child = sp;
                _stateMachineInspectorContent.Children.Add(card);
            }
        }

        private void BuildStateMachineAnimationsList()
        {
            if (_stateMachineAnimationsStack == null) return;
            _stateMachineAnimationsStack.Children.Clear();

            if (Document == null || Document.Animation == null) return;
            if (Document.Animation.Clips == null) Document.Animation.Clips = new List<Clip>();
            if (Document.Animation.Clips.Count == 0)
            {
                var defaultClip = new Clip(100, "Default Animation", Math.Max(0.1, _timelineController != null ? _timelineController.Duration : 2.0), 60.0, LoopMode.OneShot);
                Document.Animation.Clips.Add(defaultClip);
                if (_timelineController != null) _timelineController.ActiveClip = defaultClip;
            }

            var sm = EnsureStateMachineRuntime();
            var layer = (sm != null && sm.Definition != null && sm.Definition.Layers != null && sm.Definition.Layers.Count > 0) ? sm.Definition.Layers[0] : null;

            var usedClipIndices = new HashSet<int>();
            if (layer != null && layer.States != null)
            {
                for (int s = 0; s < layer.States.Count; s++)
                {
                    var st = layer.States[s];
                    if (st != null && st.Kind == StateKind.Animation && st.ClipIndex >= 0)
                    {
                        usedClipIndices.Add(st.ClipIndex);
                    }
                }
            }

            var clips = Document.Animation.Clips;
            for (int i = 0; i < clips.Count; i++)
            {
                int clipIdx = i;
                var clip = clips[i];
                if (clip == null) continue;

                bool isInGraph = usedClipIndices.Contains(clipIdx);

                var card = new Border
                {
                    Background = KerfBrand.FigmaCardBrush,
                    BorderBrush = isInGraph ? new SolidColorBrush(Color.FromArgb(70, 0, 245, 160)) : KerfBrand.FigmaBorderBrush,
                    BorderThickness = new Thickness(1),
                    CornerRadius = new CornerRadius(5),
                    Padding = new Thickness(8, 6, 8, 6),
                    Margin = new Thickness(0, 0, 0, 6),
                    Cursor = Cursors.SizeAll,
                    ToolTip = "Drag onto State Machine canvas to create a state node, or click '+ State'"
                };
                card.Tag = clip.Name;

                var cardGrid = new Grid();
                cardGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                cardGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

                var infoStack = new StackPanel { VerticalAlignment = VerticalAlignment.Center };
                var topRow = new StackPanel { Orientation = Orientation.Horizontal };
                var icon = new TextBlock
                {
                    Text = "🎬",
                    FontSize = 10,
                    Margin = new Thickness(0, 0, 6, 0),
                    VerticalAlignment = VerticalAlignment.Center
                };
                var nameText = new TextBlock
                {
                    Text = clip.Name,
                    FontSize = 11,
                    FontWeight = FontWeights.SemiBold,
                    Foreground = Brushes.White,
                    TextTrimming = TextTrimming.CharacterEllipsis,
                    MaxWidth = 130,
                    VerticalAlignment = VerticalAlignment.Center,
                    Cursor = Cursors.Hand,
                    ToolTip = "Double-click to rename"
                };
                nameText.MouseLeftButtonDown += (s, e) =>
                {
                    if (e.ClickCount >= 2)
                    {
                        ShowRenameAnimationClipDialog(clip);
                        e.Handled = true;
                    }
                };
                topRow.Children.Add(icon);
                topRow.Children.Add(nameText);

                if (isInGraph)
                {
                    var inGraphBadge = new Border
                    {
                        Background = new SolidColorBrush(Color.FromArgb(35, 0, 245, 160)),
                        BorderBrush = new SolidColorBrush(Color.FromArgb(80, 0, 245, 160)),
                        BorderThickness = new Thickness(1),
                        CornerRadius = new CornerRadius(3),
                        Padding = new Thickness(4, 1, 4, 1),
                        Margin = new Thickness(6, 0, 0, 0),
                        VerticalAlignment = VerticalAlignment.Center
                    };
                    inGraphBadge.Child = new TextBlock
                    {
                        Text = "In Graph",
                        FontSize = 8.5,
                        FontWeight = FontWeights.SemiBold,
                        Foreground = KerfBrand.MintBrush
                    };
                    topRow.Children.Add(inGraphBadge);
                }

                infoStack.Children.Add(topRow);

                int trackCount = clip.Tracks != null ? clip.Tracks.Count : 0;
                string subDetails = clip.Duration.ToString("0.00") + "s · " + clip.Fps.ToString("0") + "fps · " + trackCount + (trackCount == 1 ? " track" : " tracks") + (clip.LoopMode == LoopMode.Loop ? " · Loop" : " · Once");
                var detailsText = new TextBlock
                {
                    Text = subDetails,
                    FontSize = 9,
                    Foreground = KerfBrand.TextMutedBrush,
                    Margin = new Thickness(16, 2, 0, 0)
                };
                infoStack.Children.Add(detailsText);

                Grid.SetColumn(infoStack, 0);
                cardGrid.Children.Add(infoStack);

                var rightStack = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center };

                var addBtn = KerfBrand.CreateSecondaryButton("+ State", () => AddClipAsStateToGraph(clipIdx, clip, null, null), 3);
                addBtn.Height = 20;
                addBtn.Padding = new Thickness(6, 1, 6, 1);
                addBtn.FontSize = 9.5;
                addBtn.ToolTip = "Add as a state node to the state machine canvas";
                rightStack.Children.Add(addBtn);

                var renameBtn = new TextBlock
                {
                    Text = "✎",
                    FontSize = 10,
                    Foreground = KerfBrand.TextMutedBrush,
                    Margin = new Thickness(6, 0, 0, 0),
                    Cursor = Cursors.Hand,
                    VerticalAlignment = VerticalAlignment.Center,
                    ToolTip = "Rename Animation"
                };
                renameBtn.MouseEnter += (s, e) => renameBtn.Foreground = Brushes.White;
                renameBtn.MouseLeave += (s, e) => renameBtn.Foreground = KerfBrand.TextMutedBrush;
                renameBtn.MouseLeftButtonDown += (s, e) =>
                {
                    ShowRenameAnimationClipDialog(clip);
                    e.Handled = true;
                };
                rightStack.Children.Add(renameBtn);

                var delBtn = new TextBlock
                {
                    Text = "✕",
                    FontSize = 10,
                    Foreground = KerfBrand.TextMutedBrush,
                    Margin = new Thickness(6, 0, 0, 0),
                    Cursor = Cursors.Hand,
                    VerticalAlignment = VerticalAlignment.Center,
                    ToolTip = "Delete Animation Clip"
                };
                delBtn.MouseEnter += (s, e) => delBtn.Foreground = new SolidColorBrush(Color.FromRgb(255, 107, 107));
                delBtn.MouseLeave += (s, e) => delBtn.Foreground = KerfBrand.TextMutedBrush;
                delBtn.MouseLeftButtonDown += (s, e) =>
                {
                    clips.RemoveAt(clipIdx);
                    if (clips.Count == 0)
                    {
                        var newClip = new Clip(100, "Default Animation", 2.0, 60.0, LoopMode.OneShot);
                        clips.Add(newClip);
                    }
                    if (_timelineController != null && _timelineController.ActiveClip == clip)
                    {
                        _timelineController.ActiveClip = clips[0];
                    }
                    if (History != null) History.MarkDirty();
                    BuildStateMachineStatesGraph();
                    BuildStateMachineAnimationsList();
                    RefreshPropertyInspector();
                    e.Handled = true;
                };
                rightStack.Children.Add(delBtn);

                var dragHint = new TextBlock
                {
                    Text = "⋮⋮",
                    FontSize = 13,
                    Foreground = KerfBrand.TextMutedBrush,
                    Margin = new Thickness(6, 0, 0, 0),
                    VerticalAlignment = VerticalAlignment.Center,
                    ToolTip = "Drag onto State Machine canvas, or drag over cards to reorder"
                };
                rightStack.Children.Add(dragHint);

                Grid.SetColumn(rightStack, 1);
                cardGrid.Children.Add(rightStack);

                card.Child = cardGrid;

                // Drag to reorder animations list
                card.AllowDrop = true;
                card.DragOver += (s, e) =>
                {
                    if (e.Data.GetDataPresent("KerfAnimationClipIndex"))
                    {
                        e.Effects = DragDropEffects.Move;
                        e.Handled = true;
                    }
                };
                card.Drop += (s, e) =>
                {
                    if (e.Data.GetDataPresent("KerfAnimationClipIndex"))
                    {
                        int sourceIdx = -1;
                        object val = e.Data.GetData("KerfAnimationClipIndex");
                        if (val is int) sourceIdx = (int)val;
                        else if (val != null) int.TryParse(val.ToString(), out sourceIdx);

                        int targetIdx = clipIdx;
                        if (sourceIdx >= 0 && sourceIdx < Document.Animation.Clips.Count && targetIdx >= 0 && targetIdx < Document.Animation.Clips.Count && sourceIdx != targetIdx)
                        {
                            var moved = Document.Animation.Clips[sourceIdx];
                            Document.Animation.Clips.RemoveAt(sourceIdx);
                            Document.Animation.Clips.Insert(targetIdx, moved);
                            if (History != null) History.MarkDirty();
                            BuildStateMachineAnimationsList();
                            RefreshPropertyInspector();
                            e.Handled = true;
                        }
                    }
                };

                card.MouseEnter += (s, e) =>
                {
                    card.Background = KerfBrand.FreezeBrush(new SolidColorBrush(Color.FromRgb(38, 43, 54)));
                    card.BorderBrush = KerfBrand.MintBrush;
                };
                card.MouseLeave += (s, e) =>
                {
                    card.Background = KerfBrand.FigmaCardBrush;
                    card.BorderBrush = isInGraph ? new SolidColorBrush(Color.FromArgb(70, 0, 245, 160)) : KerfBrand.FigmaBorderBrush;
                };

                card.MouseLeftButtonDown += (s, e) =>
                {
                    if (e.ClickCount >= 2)
                    {
                        SelectAnimationClip(clip);
                        e.Handled = true;
                        return;
                    }
                    _draggedClipIndex = clipIdx;
                    _draggedAnimationClip = clip;
                    _animDragStartPoint = e.GetPosition(this);
                };
                card.MouseMove += (s, e) =>
                {
                    if (e.LeftButton == MouseButtonState.Pressed && _draggedClipIndex == clipIdx)
                    {
                        Point current = e.GetPosition(this);
                        Vector diff = _animDragStartPoint - current;
                        if (Math.Abs(diff.X) > SystemParameters.MinimumHorizontalDragDistance ||
                            Math.Abs(diff.Y) > SystemParameters.MinimumVerticalDragDistance)
                        {
                            var dataObj = new DataObject("KerfAnimationClipIndex", clipIdx);
                            DragDrop.DoDragDrop(card, dataObj, DragDropEffects.Copy | DragDropEffects.Move);
                            _draggedClipIndex = -1;
                            _draggedAnimationClip = null;
                        }
                    }
                };
                card.MouseLeftButtonUp += (s, e) =>
                {
                    _draggedClipIndex = -1;
                    _draggedAnimationClip = null;
                };
                card.MouseRightButtonUp += (s, e) =>
                {
                    ShowAnimationClipContextMenu(card, clip, clipIdx);
                    e.Handled = true;
                };

                _stateMachineAnimationsStack.Children.Add(card);
            }
        }

        private void AddClipAsStateToGraph(int clipIndex, Clip clip, double? customX, double? customY)
        {
            if (clip == null) return;
            var sm = EnsureStateMachineRuntime();
            if (sm == null || sm.Definition == null) return;
            var layer = EnsureStateMachineGraphLayer(sm.Definition);
            if (layer == null) return;

            int smClipIndex = 0;
            if (sm.Clips != null)
            {
                smClipIndex = sm.Clips.IndexOf(clip);
                if (smClipIndex < 0)
                {
                    smClipIndex = sm.Clips.Count;
                    sm.Clips.Add(clip);
                }
            }

            if (Document.Animation.Clips == null) Document.Animation.Clips = new List<Clip>();
            if (!Document.Animation.Clips.Contains(clip)) Document.Animation.Clips.Add(clip);

            double posX = customX.HasValue ? customX.Value : 260.0;
            double posY = customY.HasValue ? customY.Value : 60.0;
            if (!customX.HasValue || !customY.HasValue)
            {
                if (layer.States != null && layer.States.Count > 0)
                {
                    double maxX = 60.0;
                    double maxY = 60.0;
                    for (int s = 0; s < layer.States.Count; s++)
                    {
                        var st = layer.States[s];
                        if (st != null)
                        {
                            if (st.GraphX > maxX) maxX = st.GraphX;
                            if (st.GraphY > maxY) maxY = st.GraphY;
                        }
                    }
                    posX = maxX + 150.0;
                    posY = Math.Min(maxY, 240.0);
                }
            }

            string stateName = !string.IsNullOrWhiteSpace(clip.Name) ? clip.Name : ("State " + (layer.States.Count + 1));
            int nextId = layer.States.Count;
            for (int i = 0; i < layer.States.Count; i++)
            {
                if (layer.States[i] != null && layer.States[i].Id >= nextId)
                {
                    nextId = layer.States[i].Id + 1;
                }
            }

            var newState = new MachineState(nextId, stateName, StateKind.Animation, smClipIndex)
            {
                GraphX = posX,
                GraphY = posY,
                Speed = 1.0,
                LoopMode = clip.LoopMode
            };

            var cmd = new CreateStateNodeCommand(layer, newState, () =>
            {
                _selectedGraphStateIndex = layer.States.IndexOf(newState);
                if (_selectedGraphStateIndices != null)
                {
                    _selectedGraphStateIndices.Clear();
                    if (_selectedGraphStateIndex >= 0) _selectedGraphStateIndices.Add(_selectedGraphStateIndex);
                }
                BuildStateMachineStatesGraph();
                BuildStateMachineAnimationsList();
                RefreshStateMachineInspector();
                RefreshStateMachineValidationBadge();
            });

            if (History != null)
            {
                History.Execute(cmd);
            }
            else
            {
                cmd.Execute();
            }

            int entryIndex = layer.States.FindIndex(st => st != null && st.Kind == StateKind.Entry);
            bool hasEntryTrans = false;
            if (entryIndex >= 0 && layer.Transitions != null)
            {
                for (int t = 0; t < layer.Transitions.Count; t++)
                {
                    var tr = layer.Transitions[t];
                    if (tr != null && tr.FromState == entryIndex)
                    {
                        hasEntryTrans = true;
                        break;
                    }
                }
            }
            if (entryIndex >= 0 && !hasEntryTrans)
            {
                int newStateIndex = layer.States.IndexOf(newState);
                if (newStateIndex >= 0)
                {
                    var transCmd = new CreateTransitionCommand(layer, new StateTransition(entryIndex, newStateIndex, 0.0), () =>
                    {
                        BuildStateMachineStatesGraph();
                        RefreshStateMachineInspector();
                        RefreshStateMachineValidationBadge();
                    });
                    if (History != null) History.Execute(transCmd);
                    else transCmd.Execute();
                }
            }

            _selectedGraphStateIndex = layer.States.IndexOf(newState);
            if (_selectedGraphStateIndices != null)
            {
                _selectedGraphStateIndices.Clear();
                if (_selectedGraphStateIndex >= 0) _selectedGraphStateIndices.Add(_selectedGraphStateIndex);
            }
            BuildStateMachineStatesGraph();
            BuildStateMachineAnimationsList();
            RefreshStateMachineInspector();
            RefreshStateMachineValidationBadge();
        }

        private void BuildStateMachineInputsControls()
        {
            if (_stateMachineInputsStack == null) return;
            _stateMachineInputsStack.Children.Clear();

            if (_timelineController == null || _timelineController.ActiveStateMachine == null)
            {
                EnsureTimelineControllerInitialized();
            }

            var sm = EnsureStateMachineRuntime();
            if (sm == null || sm.Definition == null) return;

            if (sm.Definition.Inputs != null)
            {
                var orderedInputs = sm.Definition.Inputs.Where(input => input != null)
                    .OrderBy(input => input.Kind == InputKind.Folder ? 0 : 1).ToList();
                for (int i = 0; i < orderedInputs.Count; i++)
                {
                    var input = orderedInputs[i];
                    int inIdx = sm.Definition.Inputs.IndexOf(input);
                    if (inIdx < 0) continue;

                    var card = new Border
                    {
                        Background = KerfBrand.FigmaCardBrush,
                        BorderBrush = KerfBrand.FigmaBorderBrush,
                        BorderThickness = new Thickness(1),
                        CornerRadius = new CornerRadius(5),
                        Padding = new Thickness(8, 6, 8, 6),
                        Margin = new Thickness(string.IsNullOrEmpty(input.ParentFolderId) ? 0 : 14, 0, 0, 6)
                    };
                    card.Tag = input.Name;

                    var cardStack = new StackPanel();

                    // Row 0: Badge + Name Box + Delete Button
                    var headerDock = new DockPanel { LastChildFill = true };

                    // Delete button on the right
                    var delBtn = new Border
                    {
                        Width = 18,
                        Height = 18,
                        Background = Brushes.Transparent,
                        Cursor = Cursors.Hand,
                        ToolTip = "Delete variable",
                        VerticalAlignment = VerticalAlignment.Center,
                        Margin = new Thickness(4, 0, 0, 0)
                    };
                    var delText = new TextBlock
                    {
                        Text = "×",
                        FontSize = 14,
                        Foreground = KerfBrand.TextMutedBrush,
                        HorizontalAlignment = HorizontalAlignment.Center,
                        VerticalAlignment = VerticalAlignment.Center
                    };
                    delBtn.Child = delText;
                    delBtn.MouseEnter += (s, e) => { delText.Foreground = new SolidColorBrush(Color.FromRgb(239, 68, 68)); };
                    delBtn.MouseLeave += (s, e) => { delText.Foreground = KerfBrand.TextMutedBrush; };
                    delBtn.MouseLeftButtonUp += (s, e) =>
                    {
                        var cmd = new DeleteInputCommand(sm.Definition, input, () =>
                        {
                            BuildStateMachineInputsControls();
                            BuildStateMachineStatesGraph();
                            BuildStateMachineAnimationsList();
                            RefreshStateMachineInspector();
                            RefreshStateMachineValidationBadge();
                        });
                        if (History != null) History.Execute(cmd);
                        else cmd.Execute();
                    };
                    DockPanel.SetDock(delBtn, Dock.Right);
                    headerDock.Children.Add(delBtn);

                    // Badge on the left
                    Border badge;
                    TextBlock badgeText;
                    if (input.Kind == InputKind.Folder)
                    {
                        badge = new Border
                        {
                            Background = new SolidColorBrush(Color.FromRgb(75, 85, 99)),
                            CornerRadius = new CornerRadius(4),
                            Padding = new Thickness(6, 2, 6, 2),
                            Margin = new Thickness(0, 0, 6, 0),
                            ToolTip = "Folder for organizing state machine inputs"
                        };
                        badgeText = new TextBlock { Text = "▰", FontSize = 10, FontWeight = FontWeights.Bold, Foreground = Brushes.White };
                        badge.Child = badgeText;
                    }
                    else if (input.Kind == InputKind.Trigger)
                    {
                        badge = new Border
                        {
                            Background = new SolidColorBrush(Color.FromRgb(139, 92, 246)), // Purple
                            CornerRadius = new CornerRadius(4),
                            Padding = new Thickness(6, 2, 6, 2),
                            Margin = new Thickness(0, 0, 6, 0),
                            Cursor = Cursors.Hand,
                            ToolTip = "Click to fire trigger impulse"
                        };
                        badgeText = new TextBlock { Text = "⚡", FontSize = 10, FontWeight = FontWeights.Bold, Foreground = Brushes.White };
                        badge.Child = badgeText;
                        badge.MouseLeftButtonUp += (s, e) =>
                        {
                            sm.FireTrigger(inIdx);
                            TriggerStateMachineStep(continuePlayback: true);
                        };
                    }
                    else if (input.Kind == InputKind.Bool)
                    {
                        bool isVal = input.Value > 0.5;
                        badge = new Border
                        {
                            Background = isVal ? new SolidColorBrush(Color.FromRgb(16, 185, 129)) : new SolidColorBrush(Color.FromRgb(37, 99, 235)),
                            CornerRadius = new CornerRadius(4),
                            Padding = new Thickness(6, 2, 6, 2),
                            Margin = new Thickness(0, 0, 6, 0),
                            Cursor = Cursors.Hand,
                            ToolTip = "Click to toggle live bool"
                        };
                        badgeText = new TextBlock { Text = isVal ? "⏻ ON" : "⏻ OFF", FontSize = 9, FontWeight = FontWeights.Bold, Foreground = Brushes.White };
                        badge.Child = badgeText;
                        badge.MouseLeftButtonUp += (s, e) =>
                        {
                            bool newVal = !(sm.GetInputValue(inIdx) > 0.5);
                            sm.SetBool(inIdx, newVal);
                            if (!string.IsNullOrEmpty(input.InputId)) sm.SetBool(input.InputId, newVal);
                            badgeText.Text = newVal ? "⏻ ON" : "⏻ OFF";
                            badge.Background = newVal ? new SolidColorBrush(Color.FromRgb(16, 185, 129)) : new SolidColorBrush(Color.FromRgb(37, 99, 235));
                            TriggerStateMachineStep(continuePlayback: true);
                        };
                    }
                    else // Number
                    {
                        badge = new Border
                        {
                            Background = new SolidColorBrush(Color.FromRgb(59, 130, 246)), // Blue
                            CornerRadius = new CornerRadius(4),
                            Padding = new Thickness(6, 2, 6, 2),
                            Margin = new Thickness(0, 0, 6, 0),
                            ToolTip = "Number variable"
                        };
                        badgeText = new TextBlock { Text = "🎚", FontSize = 10, FontWeight = FontWeights.Bold, Foreground = Brushes.White };
                        badge.Child = badgeText;
                    }
                    DockPanel.SetDock(badge, Dock.Left);
                    headerDock.Children.Add(badge);

                    // Name editing TextBox (fills center)
                    var nameBox = new TextBox
                    {
                        Text = input.Name,
                        FontSize = 11,
                        FontWeight = FontWeights.SemiBold,
                        Foreground = Brushes.White,
                        Background = Brushes.Transparent,
                        BorderThickness = new Thickness(0, 0, 0, 1),
                        BorderBrush = Brushes.Transparent,
                        VerticalAlignment = VerticalAlignment.Center,
                        Padding = new Thickness(2, 1, 2, 1)
                    };
                    nameBox.GotKeyboardFocus += (s, e) => { nameBox.BorderBrush = KerfBrand.MintBrush; };
                    Action commitName = () =>
                    {
                        nameBox.BorderBrush = Brushes.Transparent;
                        string newName = nameBox.Text.Trim();
                        if (!string.IsNullOrEmpty(newName) && !string.Equals(newName, input.Name, StringComparison.Ordinal))
                        {
                            var cmd = new ModifyInputCommand(input, input.Name, newName, input.InitialValue, input.InitialValue, () =>
                            {
                                BuildStateMachineInputsControls();
                                RefreshStateMachineInspector();
                                RefreshStateMachineValidationBadge();
                            });
                            if (History != null) History.Execute(cmd);
                            else cmd.Execute();
                        }
                    };
                    nameBox.LostKeyboardFocus += (s, e) => commitName();
                    nameBox.KeyDown += (s, e) =>
                    {
                        if (e.Key == Key.Enter)
                        {
                            commitName();
                            Keyboard.ClearFocus();
                        }
                    };
                    headerDock.Children.Add(nameBox);
                    cardStack.Children.Add(headerDock);

                    if (input.Kind != InputKind.Folder)
                    {
                        var folderRow = new DockPanel { Margin = new Thickness(0, 4, 0, 0) };
                        var folderLabel = new TextBlock
                        {
                            Text = "Folder",
                            Width = 46,
                            FontSize = 10,
                            Foreground = KerfBrand.TextMutedBrush,
                            VerticalAlignment = VerticalAlignment.Center
                        };
                        DockPanel.SetDock(folderLabel, Dock.Left);
                        folderRow.Children.Add(folderLabel);
                        var folderCombo = CreateModernComboBox(21);
                        folderCombo.Items.Add(CreateModernComboBoxItem("No folder", string.Empty));
                        int selectedFolderIndex = 0;
                        for (int fi = 0; fi < sm.Definition.Inputs.Count; fi++)
                        {
                            var folder = sm.Definition.Inputs[fi];
                            if (folder == null || folder.Kind != InputKind.Folder || folder.InputId == input.InputId) continue;
                            folderCombo.Items.Add(CreateModernComboBoxItem(folder.Name, folder.InputId));
                            if (string.Equals(folder.InputId, input.ParentFolderId, StringComparison.OrdinalIgnoreCase))
                                selectedFolderIndex = folderCombo.Items.Count - 1;
                        }
                        folderCombo.SelectedIndex = selectedFolderIndex;
                        folderCombo.SelectionChanged += (s, e) =>
                        {
                            var selectedFolder = folderCombo.SelectedItem as ComboBoxItem;
                            string folderId = selectedFolder != null ? (selectedFolder.Tag as string) : string.Empty;
                            folderId = folderId ?? string.Empty;
                            if (!string.Equals(input.ParentFolderId ?? string.Empty, folderId, StringComparison.OrdinalIgnoreCase))
                            {
                                var moveCmd = new ModifyInputFolderCommand(input, input.ParentFolderId, folderId, () =>
                                {
                                    BuildStateMachineInputsControls();
                                    RefreshStateMachineInspector();
                                });
                                if (History != null) History.Execute(moveCmd);
                                else moveCmd.Execute();
                            }
                        };
                        folderRow.Children.Add(folderCombo);
                        cardStack.Children.Add(folderRow);
                    }

                    // Row 1: Default / Initial / Live Controls
                    if (input.Kind == InputKind.Bool)
                    {
                        var boolPanel = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 4, 0, 0), VerticalAlignment = VerticalAlignment.Center };
                        boolPanel.Children.Add(new TextBlock { Text = "Default: ", FontSize = 10, Foreground = KerfBrand.TextMutedBrush, VerticalAlignment = VerticalAlignment.Center });
                        var chk = new CheckBox
                        {
                            Content = input.InitialValue > 0.5 ? "True" : "False",
                            IsChecked = input.InitialValue > 0.5,
                            FontSize = 10,
                            Foreground = Brushes.White,
                            VerticalAlignment = VerticalAlignment.Center,
                            Cursor = Cursors.Hand
                        };
                        chk.Click += (s, e) =>
                        {
                            double newInit = (chk.IsChecked == true) ? 1.0 : 0.0;
                            chk.Content = (newInit > 0.5) ? "True" : "False";
                            var cmd = new ModifyInputCommand(input, input.Name, input.Name, input.InitialValue, newInit, () =>
                            {
                                BuildStateMachineInputsControls();
                                RefreshStateMachineInspector();
                                RefreshStateMachineValidationBadge();
                            });
                            if (History != null) History.Execute(cmd);
                            else cmd.Execute();
                        };
                        boolPanel.Children.Add(chk);
                        cardStack.Children.Add(boolPanel);
                    }
                    else if (input.Kind == InputKind.Number)
                    {
                        var numGrid = new Grid { Margin = new Thickness(0, 4, 0, 0) };
                        numGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
                        numGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(45) });
                        numGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

                        var defLbl = new TextBlock { Text = "Default: ", FontSize = 10, Foreground = KerfBrand.TextMutedBrush, VerticalAlignment = VerticalAlignment.Center };
                        Grid.SetColumn(defLbl, 0);
                        numGrid.Children.Add(defLbl);

                        var initBox = new TextBox
                        {
                            Text = input.InitialValue.ToString("0.##", CultureInfo.InvariantCulture),
                            FontSize = 10,
                            Foreground = Brushes.White,
                            Background = KerfBrand.FigmaCanvasBrush,
                            BorderBrush = KerfBrand.FigmaBorderBrush,
                            Padding = new Thickness(2, 1, 2, 1),
                            Height = 20,
                            VerticalAlignment = VerticalAlignment.Center,
                            Margin = new Thickness(0, 0, 4, 0)
                        };
                        Action commitInit = () =>
                        {
                            double v;
                            if (double.TryParse(initBox.Text, NumberStyles.Float, CultureInfo.InvariantCulture, out v))
                            {
                                if (Math.Abs(v - input.InitialValue) > 0.0001)
                                {
                                    var cmd = new ModifyInputCommand(input, input.Name, input.Name, input.InitialValue, v, () =>
                                    {
                                        BuildStateMachineInputsControls();
                                        RefreshStateMachineInspector();
                                        RefreshStateMachineValidationBadge();
                                    });
                                    if (History != null) History.Execute(cmd);
                                    else cmd.Execute();
                                }
                            }
                        };
                        initBox.LostKeyboardFocus += (s, e) => commitInit();
                        initBox.KeyDown += (s, e) =>
                        {
                            if (e.Key == Key.Enter)
                            {
                                commitInit();
                                Keyboard.ClearFocus();
                            }
                        };
                        Grid.SetColumn(initBox, 1);
                        numGrid.Children.Add(initBox);

                        var slider = new Slider
                        {
                            Minimum = 0.0,
                            Maximum = Math.Max(10.0, Math.Max(input.InitialValue * 2.0, input.Value * 2.0)),
                            Value = input.Value,
                            VerticalAlignment = VerticalAlignment.Center,
                            Margin = new Thickness(4, 0, 0, 0)
                        };
                        slider.ValueChanged += (s, e) =>
                        {
                            sm.SetNumber(inIdx, slider.Value);
                            if (!string.IsNullOrEmpty(input.InputId)) sm.SetNumber(input.InputId, slider.Value);
                            TriggerStateMachineStep(continuePlayback: true);
                        };
                        Grid.SetColumn(slider, 2);
                        numGrid.Children.Add(slider);

                        cardStack.Children.Add(numGrid);
                    }

                    card.Child = cardStack;
                    _stateMachineInputsStack.Children.Add(card);
                }
            }

            if (_stateMachineInputSearch != null)
                FilterStateMachineItems(_stateMachineInputsStack, _stateMachineInputSearch.Text);
        }

        private void AddStateMachineInputElement(UIElement element, string name)
        {
            var framework = element as FrameworkElement;
            if (framework != null)
            {
                framework.Tag = name ?? string.Empty;
                framework.Margin = new Thickness(0, 2, 0, 2);
            }
            if (_stateMachineInputsStack != null && element != null) _stateMachineInputsStack.Children.Add(element);
        }

        private void AddStateMachineState()
        {
            if (_timelineController == null || _timelineController.ActiveStateMachine == null) return;
            var sm = _timelineController.ActiveStateMachine;
            if (sm.Definition == null || sm.Definition.Layers == null || sm.Definition.Layers.Count == 0) return;
            var layer = sm.Definition.Layers[0];
            string name = "State " + (layer.States.Count + 1);
            uint clipId = unchecked((uint)(DateTime.UtcNow.Ticks & 0xffffffff));
            var clip = new Clip(clipId, name, Math.Max(0.1, _timelineController.Duration), _timelineController.Fps, LoopMode.Loop);
            int clipIndex = sm.Clips.Count;
            sm.Clips.Add(clip);
            if (Document.Animation == null) Document.Animation = new AnimationProjectData();
            if (Document.Animation.Clips == null) Document.Animation.Clips = new List<Clip>();
            if (!ReferenceEquals(Document.Animation.Clips, sm.Clips)) Document.Animation.Clips.Add(clip);
            int stateIndex = layer.AddState(new MachineState(layer.States.Count, name, StateKind.Animation, clipIndex));
            int entryIndex = layer.States.FindIndex(state => state != null && state.Kind == StateKind.Entry);
            if (entryIndex >= 0 && !layer.Transitions.Any(transition => transition != null && transition.FromState == entryIndex))
                layer.AddTransition(new StateTransition(entryIndex, stateIndex, 0.0));
            _selectedGraphStateIndex = stateIndex;
            History.MarkDirty();
            BuildStateMachineStatesGraph();
            BuildStateMachineAnimationsList();
            RefreshTimelineUI();
        }

        private void ShowAddViewModelPropertyDialog()
        {
            if (_timelineController == null || _timelineController.ActiveStateMachine == null) return;
            var sm = _timelineController.ActiveStateMachine;
            var dialog = new Window
            {
                Title = "Add View Model Property",
                Width = 330,
                Height = 235,
                ResizeMode = ResizeMode.NoResize,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                Background = KerfBrand.FigmaPanelBrush,
                Foreground = Brushes.White
            };
            dialog.Resources[typeof(TextBox)] = KerfBrand.CreateDarkTextBoxStyle(6);
            dialog.Resources[typeof(ComboBox)] = KerfBrand.CreateDarkComboBoxStyle(6);
            var owner = Window.GetWindow(this);
            if (owner != null) dialog.Owner = owner;
            var form = new StackPanel { Margin = new Thickness(18) };
            var nameBox = new TextBox { Text = "newProperty", Height = 28, Margin = new Thickness(0, 0, 0, 10) };
            KerfBrand.ApplyDarkRoundedTextBoxStyle(nameBox, 6);
            form.Children.Add(CreateTransitionFormRow("Name", nameBox));
            var kindBox = CreateModernComboBox(30);
            foreach (var kind in new ViewModelPropertyKind[] { ViewModelPropertyKind.Boolean, ViewModelPropertyKind.Number, ViewModelPropertyKind.Trigger, ViewModelPropertyKind.Text })
                kindBox.Items.Add(new ComboBoxItem { Content = kind.ToString(), Tag = kind });
            kindBox.SelectedIndex = 0;
            form.Children.Add(CreateTransitionFormRow("Type", kindBox));
            var buttons = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 16, 0, 0) };
            var cancel = KerfBrand.CreateSecondaryButton("Cancel", () => dialog.Close(), 6);
            cancel.Width = 72;
            cancel.Height = 26;
            cancel.Padding = new Thickness(0);
            var create = KerfBrand.CreatePrimaryButton("Create", () =>
            {
                string propertyName = nameBox.Text.Trim();
                if (string.IsNullOrEmpty(propertyName)) return;
                if (sm.Definition.ViewModelProperties.Any(p => p != null && string.Equals(p.Name, propertyName, StringComparison.OrdinalIgnoreCase)))
                {
                    MessageBox.Show("A View Model property with this name already exists.", "State Machine", MessageBoxButton.OK, MessageBoxImage.Information);
                    return;
                }
                var selected = kindBox.SelectedItem as ComboBoxItem;
                var kind = selected != null ? (ViewModelPropertyKind)selected.Tag : ViewModelPropertyKind.Boolean;
                sm.Definition.AddViewModelProperty(new ViewModelPropertyDefinition(propertyName, kind));
                InputKind ik = (kind == ViewModelPropertyKind.Boolean) ? InputKind.Bool : ((kind == ViewModelPropertyKind.Number) ? InputKind.Number : InputKind.Trigger);
                if (sm.Definition.Inputs == null) sm.Definition.Inputs = new List<MachineInput>();
                if (!sm.Definition.Inputs.Any(inp => inp != null && string.Equals(inp.Name, propertyName, StringComparison.OrdinalIgnoreCase)))
                {
                    sm.Definition.AddInput(new MachineInput(propertyName, ik, 0.0));
                }
                sm.RebuildViewModel();
                History.MarkDirty();
                BuildStateMachineInputsControls();
                BuildStateMachineStatesGraph();
                dialog.Close();
            }, 6);
            create.Width = 78;
            create.Height = 26;
            create.Padding = new Thickness(0);
            create.Margin = new Thickness(8, 0, 0, 0);
            buttons.Children.Add(cancel);
            buttons.Children.Add(create);
            form.Children.Add(buttons);
            dialog.Content = form;
            dialog.ShowDialog();
        }

        private string GetNextListenerName(StateMachineDefinition definition)
        {
            int suffix = 1;
            var existing = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            if (definition != null && definition.Listeners != null)
            {
                for (int i = 0; i < definition.Listeners.Count; i++)
                {
                    var listener = definition.Listeners[i];
                    if (listener != null && !string.IsNullOrWhiteSpace(listener.Name)) existing.Add(listener.Name.Trim());
                }
            }
            while (existing.Contains("Listener" + suffix)) suffix++;
            return "Listener" + suffix;
        }

        private void ShowAddStateMachineListenerDialog()
        {
            if (_timelineController == null) EnsureTimelineControllerInitialized();
            var sm = EnsureStateMachineRuntime();
            if (sm == null || sm.Definition == null) return;

            var targetLayer = _selectedLayers != null ? _selectedLayers.FirstOrDefault(layer => layer != null) : null;
            var listener = new NodeListener(targetLayer != null ? PropertyBinder.GetNumericNodeId(targetLayer.Id) : 0u, PointerEventKind.None);
            listener.Name = GetNextListenerName(sm.Definition);
            listener.TargetLayerId = targetLayer != null ? targetLayer.Id : string.Empty;
            var addCmd = new AddListenerCommand(sm.Definition, listener, () =>
            {
                BuildStateMachineListeners();
                RefreshPropertyInspector();
                RefreshCanvas();
            });
            if (History != null) History.Execute(addCmd);
            else addCmd.Execute();
        }
        private void BuildStateMachineListeners()
        {
            if (_stateMachineListenersStack == null) return;
            _stateMachineListenersStack.Children.Clear();
            var sm = _timelineController != null ? _timelineController.ActiveStateMachine : null;
            if (sm == null || sm.Definition == null) return;
            if (sm.Definition.Listeners == null) sm.Definition.Listeners = new List<NodeListener>();

            foreach (var listener in sm.Definition.Listeners.ToList())
            {
                if (listener == null) continue;
                var card = BuildListenerCard(listener, sm.Definition);
                card.Tag = string.IsNullOrWhiteSpace(listener.Name) ? "Listener" : listener.Name;
                _stateMachineListenersStack.Children.Add(card);
            }

            if (_stateMachineListenerSearch != null)
                FilterStateMachineItems(_stateMachineListenersStack, _stateMachineListenerSearch.Text);
        }
