            cancelBtn.Height = 26;
            cancelBtn.Padding = new Thickness(12, 2, 12, 2);
            cancelBtn.FontSize = 11;
            DockPanel.SetDock(cancelBtn, Dock.Left);
            btnRow.Children.Add(cancelBtn);

            Action doSave = () =>
            {
                string newName = nameBox.Text.Trim();
                if (!string.IsNullOrEmpty(newName) && newName != clip.Name)
                {
                    string oldName = clip.Name;
                    clip.Name = newName;
                    var sm = _timelineController != null ? _timelineController.ActiveStateMachine : null;
                    if (sm != null && sm.Definition != null && sm.Definition.Layers != null)
                    {
                        foreach (var layer in sm.Definition.Layers)
                        {
                            if (layer != null && layer.States != null)
                            {
                                foreach (var st in layer.States)
                                {
                                    if (st != null && st.Kind == StateKind.Animation && (string.IsNullOrEmpty(st.Name) || st.Name == oldName))
                                    {
                                        st.Name = newName;
                                    }
                                }
                            }
                        }
                    }
                    if (History != null) History.MarkDirty();
                    BuildStateMachineAnimationsList();
                    BuildStateMachineStatesGraph();
                    RefreshPropertyInspector();
                }
                dialog.Close();
            };

            var saveBtn = KerfBrand.CreatePrimaryButton("Save", doSave, 4);
            saveBtn.Height = 26;
            saveBtn.Padding = new Thickness(14, 2, 14, 2);
            saveBtn.FontSize = 11;
            DockPanel.SetDock(saveBtn, Dock.Right);
            btnRow.Children.Add(saveBtn);

            root.Children.Add(btnRow);
            border.Child = root;
            dialog.Content = border;

            nameBox.KeyDown += (s, e) => { if (e.Key == Key.Enter) doSave(); else if (e.Key == Key.Escape) dialog.Close(); };
            dialog.KeyDown += (s, e) => { if (e.Key == Key.Escape) dialog.Close(); };

            dialog.ShowDialog();
        }

        private void ShowAnimationClipContextMenu(FrameworkElement anchor, Clip clip, int clipIndex)
        {
            if (clip == null || anchor == null) return;
            var menu = new ContextMenu
            {
                Background = KerfBrand.ObsidianBrush,
                BorderBrush = KerfBrand.FigmaBorderBrush,
                BorderThickness = new Thickness(1)
            };

            var renameItem = new MenuItem
            {
                Header = "✎  Rename Animation...",
                Foreground = Brushes.White,
                FontSize = 11,
                Background = KerfBrand.ObsidianBrush
            };
            renameItem.Click += (s, e) => ShowRenameAnimationClipDialog(clip);
            menu.Items.Add(renameItem);

            var openItem = new MenuItem
            {
                Header = "▶  Open in Timeline",
                Foreground = Brushes.White,
                FontSize = 11,
                Background = KerfBrand.ObsidianBrush
            };
            openItem.Click += (s, e) => SelectAnimationClip(clip);
            menu.Items.Add(openItem);

            var addStateItem = new MenuItem
            {
                Header = "+  Add as State to Canvas",
                Foreground = Brushes.White,
                FontSize = 11,
                Background = KerfBrand.ObsidianBrush
            };
            addStateItem.Click += (s, e) => AddClipAsStateToGraph(clipIndex, clip, null, null);
            menu.Items.Add(addStateItem);

            menu.Items.Add(new Separator { Background = KerfBrand.FigmaBorderBrush });

            var delItem = new MenuItem
            {
                Header = "✕  Delete Animation",
                Foreground = new SolidColorBrush(Color.FromRgb(255, 107, 107)),
                FontSize = 11,
                Background = KerfBrand.ObsidianBrush
            };
            delItem.Click += (s, e) =>
            {
                if (Document != null && Document.Animation != null && Document.Animation.Clips != null)
                {
                    var clips = Document.Animation.Clips;
                    if (clipIndex >= 0 && clipIndex < clips.Count)
                    {
                        clips.RemoveAt(clipIndex);
                        if (clips.Count == 0)
                        {
                            clips.Add(new Clip(100, "Default Animation", 2.0, 60.0, LoopMode.OneShot));
                        }
                        if (_timelineController != null && _timelineController.ActiveClip == clip)
                        {
                            _timelineController.ActiveClip = clips[0];
                        }
                        if (History != null) History.MarkDirty();
                        BuildStateMachineStatesGraph();
                        BuildStateMachineAnimationsList();
                        RefreshPropertyInspector();
                    }
                }
            };
            menu.Items.Add(delItem);

            menu.PlacementTarget = anchor;
            menu.Placement = PlacementMode.Bottom;
            menu.IsOpen = true;
        }

        public void ToggleAnimationPlayback()
        {
            if (_timelineController == null) EnsureTimelineControllerInitialized();
            if (_timelineController.IsPlaying)
            {
                PauseAnimation();
            }
            else
            {
                PlayAnimation();
            }
        }

        public void PlayAnimation()
        {
            if (_timelineController == null) EnsureTimelineControllerInitialized();
            _timelineController.Play();
            if (_timelinePlayBtnText != null) _timelinePlayBtnText.Text = "⏸ Pause";
            StartAnimationTimer();
        }

        public void PauseAnimation()
        {
            if (_timelineController != null) _timelineController.Pause();
            if (_timelinePlayBtnText != null) _timelinePlayBtnText.Text = "▶ Play";
            if (_interactiveEventDispatcher != null) _interactiveEventDispatcher.Reset();
            bool keepTimer = _timelineController != null &&
                             _timelineController.UseStateMachine &&
                             _interactiveCanvasEnabled &&
                             _currentStudioMode == StudioMode.Animate;
            if (!keepTimer && _animationTimer != null) _animationTimer.Stop();
        }

        public void StopAnimationPlayback()
        {
            PauseAnimation();
            if (_interactiveEventDispatcher != null) _interactiveEventDispatcher.Reset();
            if (_timelineController != null)
            {
                _timelineController.Stop();
                if (_timelineController.UseStateMachine)
                    UpdateStateMachineStatusUI();
                UpdateTimelineTimeReadout();
                UpdateTimelineScrubberPosition();
                RefreshTimelineCanvas();
            }
        }

        private void StartAnimationTimer()
        {
            if (_animationTimer == null)
            {
                _animationTimer = new DispatcherTimer(DispatcherPriority.Render);
                _animationTimer.Interval = TimeSpan.FromMilliseconds(16); // ~60 FPS
                _animationTimer.Tick += (s, e) =>
                {
                    if (_timelineController != null)
                    {
                        bool wasPlaying = _timelineController.IsPlaying;
                        bool smHasTransitions = _timelineController.UseStateMachine &&
                                                _timelineController.ActiveStateMachine != null &&
                                                _timelineController.ActiveStateMachine.HasActiveTransitions();
                        bool isPreviewActive = _timelineController.UseStateMachine && _interactiveCanvasEnabled && _currentStudioMode == StudioMode.Animate;

                        if (wasPlaying || smHasTransitions || isPreviewActive)
                        {
                            DateTime now = DateTime.UtcNow;
                            double dt = _lastAnimationTickUtc == DateTime.MinValue
                                ? 1.0 / Math.Max(1.0, _timelineController.Fps)
                                : Math.Max(0.0, Math.Min(0.1, (now - _lastAnimationTickUtc).TotalSeconds));
                            _lastAnimationTickUtc = now;
                            _timelineController.Step(dt);

                            if (wasPlaying && !_timelineController.IsPlaying)
                            {
                                PauseAnimation();
                            }

                            if (_timelineController.UseStateMachine)
                                UpdateStateMachineStatusUI();

                            if (wasPlaying)
                            {
                                UpdateTimelineTimeReadout();
                                UpdateTimelineScrubberPosition();
                                RefreshTimelineCanvas();
                            }
                        }
                        else
                        {
                            if (wasPlaying)
                            {
                                PauseAnimation();
                            }
                            else if (_animationTimer != null)
                            {
                                _animationTimer.Stop();
                            }
                        }
                    }
                };
            }
            if (!_animationTimer.IsEnabled)
            {
                _lastAnimationTickUtc = DateTime.UtcNow;
                _animationTimer.Start();
            }
        }

        private void CaptureAnimationRestPose()
        {
            if (Document == null) return;
            _animationRestPose.Clear();
            _animationNodesById.Clear();
            var page = Document.GetActivePage();
            if (page == null) return;
            foreach (var layer in page.GetAllLayersFlat())
            {
                CaptureAnimationRestPoseForLayer(layer);
            }
            SyncStateMachineRestPose();
        }

        private void CaptureAnimationRestPoseForLayer(LayerNode layer)
        {
            if (layer == null) return;
            uint id = PropertyBinder.GetNumericNodeId(layer.Id);
            _animationRestPose[layer] = new AnimationRestPose
            {
                X = layer.X,
                Y = layer.Y,
                Width = layer.Width,
                Height = layer.Height,
                Rotation = layer.Rotation,
                Opacity = layer.Opacity,
                CornerRadius = layer.CornerRadius,
                CornerRadiusTopLeft = layer.CornerRadiusTopLeft,
                CornerRadiusTopRight = layer.CornerRadiusTopRight,
                CornerRadiusBottomRight = layer.CornerRadiusBottomRight,
                CornerRadiusBottomLeft = layer.CornerRadiusBottomLeft,
                Geometry = layer.Geometry != null ? layer.Geometry.Clone() : null
            };
            _animationNodesById[id] = layer;
        }

        private void SyncStateMachineRestPose()
        {
            if (_timelineController == null || _timelineController.ActiveStateMachine == null) return;
            var restPose = new Dictionary<uint, Dictionary<ushort, double>>();
            foreach (var kvp in _animationRestPose)
            {
                LayerNode layer = kvp.Key;
                AnimationRestPose p = kvp.Value;
                if (layer == null || p == null) continue;
                uint id = PropertyBinder.GetNumericNodeId(layer.Id);
                var dict = new Dictionary<ushort, double>();
                dict[(ushort)PropKey.X] = p.X;
                dict[(ushort)PropKey.Y] = p.Y;
                dict[(ushort)PropKey.Width] = p.Width;
                dict[(ushort)PropKey.Height] = p.Height;
                dict[(ushort)PropKey.VisualWidth] = p.Width;
                dict[(ushort)PropKey.VisualHeight] = p.Height;
                dict[(ushort)PropKey.Rotation] = p.Rotation;
                dict[(ushort)PropKey.Opacity] = p.Opacity;
                dict[(ushort)PropKey.CornerRadius] = p.CornerRadius;
                dict[(ushort)PropKey.ScaleX] = 1.0;
                dict[(ushort)PropKey.ScaleY] = 1.0;
                dict[(ushort)PropKey.AnchorX] = 0.5;
                dict[(ushort)PropKey.AnchorY] = 0.5;
                restPose[id] = dict;
            }
            _timelineController.ActiveStateMachine.RestPose = restPose;
        }

        private void RestoreAnimationRestPose()
        {
            foreach (var pair in _animationRestPose)
            {
                LayerNode layer = pair.Key;
                AnimationRestPose pose = pair.Value;
                if (layer == null || pose == null) continue;
                layer.X = pose.X;
                layer.Y = pose.Y;
                layer.Width = pose.Width;
                layer.Height = pose.Height;
                layer.Rotation = pose.Rotation;
                layer.Opacity = pose.Opacity;
                layer.CornerRadius = pose.CornerRadius;
                layer.CornerRadiusTopLeft = pose.CornerRadiusTopLeft;
                layer.CornerRadiusTopRight = pose.CornerRadiusTopRight;
                layer.CornerRadiusBottomRight = pose.CornerRadiusBottomRight;
                layer.CornerRadiusBottomLeft = pose.CornerRadiusBottomLeft;
                if (pose.Geometry != null) layer.Geometry = pose.Geometry.Clone();
                if (layer.RenderTransform != null) layer.RenderTransform.Reset();
            }
        }

        private void ApplyAnimationPose(Kerf.Model.Page page, Dictionary<uint, Dictionary<ushort, double>> pose)
        {
            if (page == null) return;
            var layers = page.GetAllLayersFlat().ToList();
            ConstraintsEngine.ForgetSolvedTransforms(layers);
            foreach (var layer in layers)
            {
                uint id = PropertyBinder.GetNumericNodeId(layer.Id);
                _animationNodesById[id] = layer;
                if (layer.RenderTransform == null) layer.RenderTransform = new RenderTransform();
                layer.RenderTransform.Reset();

                AnimationRestPose rest;
                if (_animationRestPose.TryGetValue(layer, out rest) && rest != null)
                {
                    layer.CornerRadius = rest.CornerRadius;
                    layer.CornerRadiusTopLeft = rest.CornerRadiusTopLeft;
                    layer.CornerRadiusTopRight = rest.CornerRadiusTopRight;
                    layer.CornerRadiusBottomRight = rest.CornerRadiusBottomRight;
                    layer.CornerRadiusBottomLeft = rest.CornerRadiusBottomLeft;
                    layer.Opacity = rest.Opacity;
                    if (rest.Geometry != null) layer.Geometry = rest.Geometry.Clone();
                }
            }

            if (pose != null)
            {
                foreach (var item in pose)
                {
                    LayerNode layer;
                    if (_animationNodesById.TryGetValue(item.Key, out layer))
                        PropertyBinder.ApplyPoseToLayer(layer, item.Key, pose);
                }
            }

            // Listener-driven pointer alignment overlays the sampled state-machine pose and is
            // clamped by any Distance constraint attached to the aligned object.
            StateMachineRuntime stateMachine = _timelineController != null ? _timelineController.ActiveStateMachine : null;
            if (stateMachine != null && stateMachine.PointerAlignmentTargets != null)
            {
                foreach (var target in stateMachine.PointerAlignmentTargets)
                {
                    LayerNode layer;
                    if (!_animationNodesById.TryGetValue(target.Key, out layer) || layer == null || layer.Type == ElementType.Frame) continue;
                    if (layer.RenderTransform == null) layer.RenderTransform = new RenderTransform();
                    Point center = ConstraintsEngine.ClampPointerCenter(page, layer, target.Value);
                    layer.RenderTransform.TranslationX = center.X - layer.X - layer.Width * 0.5;
                    layer.RenderTransform.TranslationY = center.Y - layer.Y - layer.Height * 0.5;
                }
            }
        }

        private void ApplyAnimationGeometryPose(Kerf.Model.Page page, Dictionary<uint, VectorGeometry> geometryPose)
        {
            if (page == null || geometryPose == null || geometryPose.Count == 0) return;
            foreach (var item in geometryPose)
            {
                LayerNode layer;
                if (!_animationNodesById.TryGetValue(item.Key, out layer) || layer == null || layer.Type != ElementType.Path || item.Value == null) continue;
                layer.Geometry = item.Value.Clone();
            }
        }

        private void ApplyAnimatedParentTransformToChildren(LayerNode parent)
        {
            // Non-destructive transform: Direct2D and WPF composition automatically apply the parent's
            // RenderTransform to all visual children without mutating layout geometry or vector points.
        }

        private static bool IsLegacyPresetDemoTrack(AnimTrack track)
        {
            if (track == null || track.Keys == null) return false;
            // Legacy preset rotation: any track containing 180° or 360° keyframes from the starter demo
            if (track.Prop == (ushort)PropKey.Rotation)
            {
                if (track.Keys.Any(k => Math.Abs(k.Value - 180.0) < 0.1 || Math.Abs(k.Value - 360.0) < 0.1))
                {
                    return true;
                }
            }
            // Legacy preset opacity: any track containing 0.5 opacity at 1.0s from the starter demo
            if (track.Prop == (ushort)PropKey.Opacity)
            {
                if (track.Keys.Any(k => Math.Abs(k.Time - 1.0) < 0.1 && Math.Abs(k.Value - 0.5) < 0.05))
                {
                    return true;
                }
            }
            return false;
        }

        private void SanitizeAnimationClips(KerfDocument doc)
        {
            if (doc == null || doc.Animation == null || doc.Animation.Clips == null) return;
            bool removedAny = false;
            foreach (var clip in doc.Animation.Clips)
            {
                if (clip == null || clip.Tracks == null) continue;
                int countBefore = clip.Tracks.Count;
                clip.Tracks.RemoveAll(IsLegacyPresetDemoTrack);
                if (clip.Tracks.Count != countBefore) removedAny = true;
            }
            if (removedAny && History != null)
            {
                History.MarkDirty();
            }
        }

        private double GetEvaluatedPropertyRaw(LayerNode layer, ushort prop)
        {
            if (layer == null) return 0.0;
            switch ((PropKey)prop)
            {
                case PropKey.X: return layer.X + (layer.RenderTransform != null ? layer.RenderTransform.TranslationX : 0.0);
                case PropKey.Y: return layer.Y + (layer.RenderTransform != null ? layer.RenderTransform.TranslationY : 0.0);
                case PropKey.ScaleX: return layer.RenderTransform != null ? layer.RenderTransform.ScaleX : 1.0;
                case PropKey.ScaleY: return layer.RenderTransform != null ? layer.RenderTransform.ScaleY : 1.0;
                case PropKey.Rotation: return layer.Rotation + (layer.RenderTransform != null ? layer.RenderTransform.Rotation : 0.0);
                case PropKey.AnchorX: return layer.RenderTransform != null ? layer.RenderTransform.AnchorX : 0.0;
                case PropKey.AnchorY: return layer.RenderTransform != null ? layer.RenderTransform.AnchorY : 0.0;
                case PropKey.Opacity: return layer.Opacity;
                case PropKey.Width:
                case PropKey.VisualWidth: return layer.RenderTransform != null && layer.RenderTransform.VisualWidth > 0 ? layer.RenderTransform.VisualWidth : layer.Width;
                case PropKey.Height:
                case PropKey.VisualHeight: return layer.RenderTransform != null && layer.RenderTransform.VisualHeight > 0 ? layer.RenderTransform.VisualHeight : layer.Height;
                case PropKey.CornerRadius: return layer.CornerRadius;
                case PropKey.StrokeWidth: return (layer.Strokes != null && layer.Strokes.Count > 0) ? layer.Strokes[0].Width : 0.0;
                case PropKey.StrokeTrimStart: return (layer.Strokes != null && layer.Strokes.Count > 0) ? layer.Strokes[0].TrimStart : 0.0;
                case PropKey.StrokeTrimEnd: return (layer.Strokes != null && layer.Strokes.Count > 0) ? layer.Strokes[0].TrimEnd : 1.0;
                case PropKey.StrokeTrimOffset: return (layer.Strokes != null && layer.Strokes.Count > 0) ? layer.Strokes[0].TrimOffset : 0.0;
                case PropKey.StrokeTaperStart: return (layer.Strokes != null && layer.Strokes.Count > 0) ? layer.Strokes[0].TaperStart : 0.0;
                case PropKey.StrokeTaperEnd: return (layer.Strokes != null && layer.Strokes.Count > 0) ? layer.Strokes[0].TaperEnd : 0.0;
                default: return 0.0;
            }
        }

        private void EnsureTimelineControllerInitialized()
        {
            if (_timelineController != null) return;

            _timelineController = new AnimationTimelineController(2.0, 60.0);
            _timelineController.FrameUpdated += (s, pose) =>
            {
                var page = Document != null ? Document.GetActivePage() : null;
                if (page != null)
                {
                    ApplyAnimationPose(page, pose);
                    _sceneGraph.InvalidateAll();
                    RefreshCanvas();
                }
            };
            _timelineController.GeometryFrameUpdated += (s, geometryPose) =>
            {
                var page = Document != null ? Document.GetActivePage() : null;
                if (page != null && geometryPose != null && geometryPose.Count > 0)
                {
                    ApplyAnimationGeometryPose(page, geometryPose);
                    _sceneGraph.InvalidateAll();
                    RefreshCanvas();
                }
            };
            _timelineController.PlaybackStopped += (s, e) =>
            {
                RestoreAnimationRestPose();
                _sceneGraph.InvalidateAll();
                RefreshCanvas();
            };

            if (Document.Animation == null) Document.Animation = new AnimationProjectData();
            if (Document.Animation.Clips == null) Document.Animation.Clips = new List<Clip>();
            SanitizeAnimationClips(Document);

            if (Document.Animation.StateMachine != null)
            {
                Clip activeClip = null;
                if (Document.Animation.Clips.Count > 0)
                {
                    activeClip = Document.Animation.Clips.FirstOrDefault(c => c.Id == Document.Animation.ActiveClipId);
                    if (activeClip == null) activeClip = Document.Animation.Clips[0];
                    Document.Animation.ActiveClipId = activeClip.Id;
                    _timelineController.ActiveClip = activeClip;
                    _timelineController.Duration = Math.Max(0.001, activeClip.Duration);
                }
                _timelineController.ActiveStateMachine = new StateMachineRuntime(Document.Animation.StateMachine, Document.Animation.Clips);
                if (_timelineScrubber != null) _timelineScrubber.Maximum = _timelineController.Duration;
                if (_timelineClipText != null && activeClip != null) _timelineClipText.Text = "Clip: " + activeClip.Name;
                SyncStateMachineRestPose();
                BuildStateMachineInputsControls();
                BuildStateMachineStatesGraph();
                return;
            }

            if (Document.Animation.Clips.Count > 0)
            {
                Clip activeClip = Document.Animation.Clips.FirstOrDefault(c => c.Id == Document.Animation.ActiveClipId);
                if (activeClip == null) activeClip = Document.Animation.Clips[0];
                Document.Animation.ActiveClipId = activeClip.Id;
                _timelineController.ActiveClip = activeClip;
                _timelineController.Duration = Math.Max(0.001, activeClip.Duration);
                var smDefExisting = new StateMachineDefinition("State Machine 1");
                var smLayerExisting = new MachineLayer("Base Layer");
                smLayerExisting.AddState(new MachineState(0, "Entry", StateKind.Entry) { GraphX = 80, GraphY = 80 });
                smLayerExisting.AddState(new MachineState(1, "Any State", StateKind.Any) { GraphX = 80, GraphY = 180 });
                smLayerExisting.AddState(new MachineState(2, "Exit", StateKind.Exit) { GraphX = 380, GraphY = 80 });
                smDefExisting.AddLayer(smLayerExisting);
                Document.Animation.StateMachine = smDefExisting;
                _timelineController.ActiveStateMachine = new StateMachineRuntime(smDefExisting, Document.Animation.Clips);
                if (_timelineScrubber != null) _timelineScrubber.Maximum = _timelineController.Duration;
                if (_timelineClipText != null) _timelineClipText.Text = "Clip: " + activeClip.Name;
                SyncStateMachineRestPose();
                BuildStateMachineInputsControls();
                BuildStateMachineStatesGraph();
                return;
            }

            var defaultClip = new Clip(100, "Default Animation", 2.0, 60.0, LoopMode.OneShot);
            // Start with an empty clip: no animations applied before the user explicitly creates keyframes
            defaultClip.Tracks.Clear();

            _timelineController.ActiveClip = defaultClip;
            _timelineController.Duration = defaultClip.Duration;

            // Minimal, editable starter graph: Entry → Idle, plus an input-driven interrupt state.
            var smDef = new StateMachineDefinition("State Machine 1");
            var smLayer = new MachineLayer("Base Layer");
            smLayer.AddState(new MachineState(0, "Entry", StateKind.Entry) { GraphX = 80, GraphY = 80 });
            smLayer.AddState(new MachineState(1, "Any State", StateKind.Any) { GraphX = 80, GraphY = 180 });
            smLayer.AddState(new MachineState(2, "Exit", StateKind.Exit) { GraphX = 380, GraphY = 80 });
            smDef.AddLayer(smLayer);
            var clips = new List<Clip> { defaultClip };
            _timelineController.ActiveStateMachine = new StateMachineRuntime(smDef, clips);
            Document.Animation.Clips = clips;
            Document.Animation.StateMachine = smDef;
            Document.Animation.ActiveClipId = defaultClip.Id;
            if (_timelineScrubber != null) _timelineScrubber.Maximum = _timelineController.Duration;
            if (_timelineClipText != null) _timelineClipText.Text = "Clip: " + defaultClip.Name;
            SyncStateMachineRestPose();
            BuildStateMachineInputsControls();
            BuildStateMachineStatesGraph();
        }

        private void AddKeyframeForSelectedLayer()
        {
            if (_timelineController == null) EnsureTimelineControllerInitialized();
            var clip = _timelineController.ActiveClip;
            if (clip == null)
            {
                clip = new Clip(100, "Default Animation", _timelineController.Duration);
                _timelineController.ActiveClip = clip;
            }

            var sel = _selectedLayers.FirstOrDefault();
            if (sel == null)
            {
                MessageBox.Show("Please select a layer on canvas or in the layers list to record animation keyframes.", "Kerf - Animation", MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }

            double time = _timelineController.CurrentTime;
            uint nodeId = PropertyBinder.GetNumericNodeId(sel.Id);

            var existingTracks = clip.GetTracksForNode(nodeId);
            if (sel.Type == ElementType.Frame && (existingTracks == null || existingTracks.Count == 0)) return;
            bool openedHistoryBatch = History != null && !History.IsBatching;
            if (openedHistoryBatch) History.BeginBatch("Keyframe Layer");
            if (sel.Type == ElementType.Path && sel.Geometry != null)
                RecordPathKeyframe(clip, sel, time, null);

            if (existingTracks != null && existingTracks.Count > 0)
            {
                foreach (var tr in existingTracks)
                {
                    if (tr.Prop == (ushort)PropKey.Path || tr.Prop == (ushort)PropKey.PathNode) continue;
                    if (sel.Type == ElementType.Frame && IsFrameTransformProperty((PropKey)tr.Prop)) continue;
                    double propVal = GetEvaluatedPropertyRaw(sel, tr.Prop);
                    AddOrUpdateTrackKeyframe(clip, nodeId, tr.Prop, time, propVal);
                }
            }
            else
            {
                if (sel.Type == ElementType.Frame) return;
                // No tracks yet: key ScaleX and ScaleY (or Position if translated),
                // without adding uninvited rotation or opacity presets.
                double sx = sel.RenderTransform != null ? sel.RenderTransform.ScaleX : 1.0;
                double sy = sel.RenderTransform != null ? sel.RenderTransform.ScaleY : 1.0;
                AddOrUpdateTrackKeyframe(clip, nodeId, (ushort)PropKey.ScaleX, time, sx);
                AddOrUpdateTrackKeyframe(clip, nodeId, (ushort)PropKey.ScaleY, time, sy);
            }

            if (Document.Animation == null) Document.Animation = new AnimationProjectData();
            if (Document.Animation.Clips == null) Document.Animation.Clips = new List<Clip>();
            if (!Document.Animation.Clips.Contains(clip)) Document.Animation.Clips.Add(clip);
            Document.Animation.ActiveClipId = clip.Id;
            _timelineController.UseStateMachine = false;
            if (openedHistoryBatch) History.EndBatch();

            RefreshTimelineUI();
        }

        private FrameworkElement CreatePathKeyframeControl(LayerNode layer)
        {
            var button = new Button
            {
                Content = "◇ Keyframe Path",
                Background = KerfBrand.FigmaCardBrush,
                Foreground = KerfBrand.MintBrush,
                BorderBrush = KerfBrand.MintBrush,
                BorderThickness = new Thickness(1),
                FontWeight = FontWeights.SemiBold,
                FontSize = 11,
                Height = 30,
                Margin = new Thickness(0, 0, 0, 8),
                Cursor = Cursors.Hand,
                ToolTip = "Record or update the selected vector path at the current playhead time",
                Template = CreateRoundedButtonTemplate(6)
            };
            button.Click += (s, e) => SetPathKeyframe(layer);
            return button;
        }

        private void SetPathKeyframe(LayerNode layer)
        {
            if (layer == null || layer.Type != ElementType.Path || layer.Geometry == null) return;
            if (_timelineController == null) EnsureTimelineControllerInitialized();
            if (_timelineController == null) return;

            Clip clip = _timelineController.ActiveClip;
            if (clip == null)
            {
                clip = new Clip(100, "Default Animation", _timelineController.Duration);
                _timelineController.ActiveClip = clip;
            }
            if (Document.Animation == null) Document.Animation = new AnimationProjectData();
            if (Document.Animation.Clips == null) Document.Animation.Clips = new List<Clip>();
            if (!Document.Animation.Clips.Contains(clip)) Document.Animation.Clips.Add(clip);
            Document.Animation.ActiveClipId = clip.Id;
            _timelineController.UseStateMachine = false;

            RecordPathKeyframe(clip, layer, _timelineController.CurrentTime, () =>
            {
                _sceneGraph.InvalidateNode(layer.Id);
                RefreshCanvas();
                RefreshTimelineUI();
                RefreshPropertyInspector();
            });
            RefreshTimelineUI();
            RefreshPropertyInspector();
        }

        private void RecordPathKeyframe(Clip clip, LayerNode layer, double time, Action onRender)
        {
            ExecuteAnimationCommands("Keyframe Path", BuildPathKeyframeCommands(clip, layer, time, layer != null ? layer.Geometry : null), onRender);
        }

        private List<Kerf.Engine.ICommand> BuildPathKeyframeCommands(Clip clip, LayerNode layer, double time, VectorGeometry geometry)
        {
            var commands = new List<Kerf.Engine.ICommand>();
            if (clip == null || layer == null || layer.Type != ElementType.Path || geometry == null) return commands;
            uint nodeId = PropertyBinder.GetNumericNodeId(layer.Id);
            AnimTrack track = clip.GetTrack(nodeId, (ushort)PropKey.Path);
            bool isNewTrack = track == null;
            if (isNewTrack) track = new AnimTrack(nodeId, (ushort)PropKey.Path, layer.Id, "Path");

            Keyframe keyframe = track.FindKeyframeAt(time, 0.02);
            if (keyframe != null)
            {
                if (!VectorGeometriesEqual(keyframe.GeometryValue, geometry))
                    commands.Add(new ModifyKeyframeGeometryCommand(keyframe, keyframe.GeometryValue, geometry));
                return commands;
            }

            if (isNewTrack) commands.Add(new AddTrackCommand(clip, track));
            commands.Add(new AddKeyframeCommand(track, new Keyframe(time, 0.0, _defaultInterpolationMode,
                _defaultInterpolationX1, _defaultInterpolationY1, _defaultInterpolationX2, _defaultInterpolationY2)
            {
                GeometryValue = geometry.Clone()
            }));
            return commands;
        }

        private List<Kerf.Engine.ICommand> BuildGeometryNodeKeyframeCommands(Clip clip, LayerNode layer, double time,
            VectorGeometry geometry, IEnumerable<int> nodeIndices, VectorGeometry baseGeometry)
        {
            var commands = new List<Kerf.Engine.ICommand>();
            if (clip == null || layer == null || layer.Type != ElementType.Path || geometry == null || geometry.Nodes == null || nodeIndices == null)
                return commands;

            uint nodeId = PropertyBinder.GetNumericNodeId(layer.Id);
            AnimTrack pathTrack = clip.GetTrack(nodeId, (ushort)PropKey.Path);
            bool needsBase = pathTrack == null || pathTrack.Keys == null || !pathTrack.Keys.Any(key => key != null && key.GeometryValue != null);
            if (pathTrack == null)
            {
                pathTrack = new AnimTrack(nodeId, (ushort)PropKey.Path, layer.Id, "Path");
                commands.Add(new AddTrackCommand(clip, pathTrack));
            }
            if (needsBase)
            {
                VectorGeometry baseline = baseGeometry != null ? baseGeometry : geometry;
                commands.Add(new AddKeyframeCommand(pathTrack, new Keyframe(time, 0.0, InterpMode.Hold)
                {
                    GeometryValue = baseline.Clone()
                }));
            }

            var uniqueIndices = new HashSet<int>();
            foreach (int nodeIndex in nodeIndices)
            {
                if (nodeIndex < 0 || nodeIndex >= geometry.Nodes.Count || !uniqueIndices.Add(nodeIndex)) continue;
                BezierNode nodeValue = geometry.Nodes[nodeIndex];
                if (nodeValue == null) continue;

                AnimTrack nodeTrack = clip.GetGeometryNodeTrack(nodeId, nodeIndex);
                bool isNewTrack = nodeTrack == null;
                if (isNewTrack)
                {
                    nodeTrack = new AnimTrack(nodeId, (ushort)PropKey.PathNode, layer.Id,
                        string.Format(CultureInfo.InvariantCulture, "Path.Nodes[{0}] · Node {1}", nodeIndex, nodeIndex + 1), nodeIndex);
                    commands.Add(new AddTrackCommand(clip, nodeTrack));
                }

                // A track's first value is held before its first key. Seed the node's
                // pre-edit pose at the clip/work-area start (or the nearest earlier path
                // key) so adding a node key later in the timeline does not change earlier
                // frames or make the node jump as soon as the clip starts.
                bool hasEarlierNodeKey = nodeTrack.Keys != null && nodeTrack.Keys.Any(key =>
                    key != null && key.GeometryNodeValue != null && key.Time < time - 1e-6);
                double workStart = clip.GetNormalizedWorkAreaStart();
                if (!hasEarlierNodeKey && time > workStart + 1e-6)
                {
                    double baselineTime = workStart;
                    if (pathTrack.Keys != null)
                    {
                        foreach (Keyframe pathKey in pathTrack.Keys)
                        {
                            if (pathKey != null && pathKey.GeometryValue != null &&
                                pathKey.Time >= workStart && pathKey.Time < time - 1e-6 && pathKey.Time > baselineTime)
                                baselineTime = pathKey.Time;
                        }
                    }

                    bool hasBaselineAtTime = nodeTrack.Keys != null && nodeTrack.Keys.Any(key =>
                        key != null && key.GeometryNodeValue != null && Math.Abs(key.Time - baselineTime) <= 1e-6);
                    if (!hasBaselineAtTime && baselineTime < time - 1e-6)
                    {
                        VectorGeometry baselineGeometry = pathTrack.SampleGeometry(baselineTime) ?? baseGeometry ?? geometry;
                        if (baselineGeometry.Nodes != null && nodeIndex < baselineGeometry.Nodes.Count && baselineGeometry.Nodes[nodeIndex] != null)
                        {
                            commands.Add(new AddKeyframeCommand(nodeTrack, new Keyframe(baselineTime, 0.0, _defaultInterpolationMode,
                                _defaultInterpolationX1, _defaultInterpolationY1, _defaultInterpolationX2, _defaultInterpolationY2)
                            {
                                GeometryNodeValue = baselineGeometry.Nodes[nodeIndex].Clone()
                            }));
                        }
                    }
                }

                Keyframe keyframe = nodeTrack.FindKeyframeAt(time, 0.02);
                if (keyframe != null)
                {
                    if (!BezierNodesEqual(keyframe.GeometryNodeValue, nodeValue))
                        commands.Add(new ModifyKeyframeGeometryNodeCommand(keyframe, keyframe.GeometryNodeValue, nodeValue));
                }
                else
                {
                    commands.Add(new AddKeyframeCommand(nodeTrack, new Keyframe(time, 0.0, _defaultInterpolationMode,
                        _defaultInterpolationX1, _defaultInterpolationY1, _defaultInterpolationX2, _defaultInterpolationY2)
                    {
                        GeometryNodeValue = nodeValue.Clone()
                    }));
                }
            }
            return commands;
        }

        private void ExecuteAnimationCommands(string description, List<Kerf.Engine.ICommand> commands, Action onCompleted)
        {
            if (commands == null || commands.Count == 0) return;
            var composite = new CompositeCommand(description, commands, onCompleted);
            if (History != null) History.Execute(composite);
            else composite.Execute();
        }

        private void RecordGeometryNodeKeyframes(LayerNode layer, IEnumerable<int> nodeIndices, VectorGeometry baseGeometry)
        {
            if (_currentStudioMode != StudioMode.Animate || layer == null || layer.Type != ElementType.Path || layer.Geometry == null) return;
            if (_timelineController == null) EnsureTimelineControllerInitialized();
            if (_timelineController == null) return;
            Clip clip = _timelineController.ActiveClip;
            if (clip == null)
            {
                clip = new Clip(100, "Default Animation", _timelineController.Duration);
                _timelineController.ActiveClip = clip;
            }
            if (Document.Animation == null) Document.Animation = new AnimationProjectData();
            if (Document.Animation.Clips == null) Document.Animation.Clips = new List<Clip>();
            if (!Document.Animation.Clips.Contains(clip)) Document.Animation.Clips.Add(clip);
            Document.Animation.ActiveClipId = clip.Id;
            _timelineController.UseStateMachine = false;

            double time = _timelineController.CurrentTime;
            var commands = BuildGeometryNodeKeyframeCommands(clip, layer, time, layer.Geometry, nodeIndices, baseGeometry);
            ExecuteAnimationCommands("Keyframe Path Nodes", commands, () => RefreshAnimationGeometry(layer));
            RefreshTimelineUI();
        }

        private void RefreshAnimationGeometry(LayerNode layer)
        {
            if (layer != null && _sceneGraph != null) _sceneGraph.InvalidateSubtree(layer.Id);
            if (_timelineController != null) _timelineController.Seek(_timelineController.CurrentTime);
            RefreshCanvas();
            RefreshTimelineUI();
            RefreshPropertyInspector();
        }

        private static bool BezierNodesEqual(BezierNode a, BezierNode b)
        {
            if (a == null || b == null) return a == b;
            return a.Type == b.Type && Math.Abs(a.Anchor.X - b.Anchor.X) < 1e-7 && Math.Abs(a.Anchor.Y - b.Anchor.Y) < 1e-7 &&
                Math.Abs(a.InHandle.X - b.InHandle.X) < 1e-7 && Math.Abs(a.InHandle.Y - b.InHandle.Y) < 1e-7 &&
                Math.Abs(a.OutHandle.X - b.OutHandle.X) < 1e-7 && Math.Abs(a.OutHandle.Y - b.OutHandle.Y) < 1e-7;
        }

        private static bool VectorGeometriesEqual(VectorGeometry a, VectorGeometry b)
        {
            if (a == null || b == null) return a == b;
            if (a.IsClosed != b.IsClosed || a.SvgPathData != b.SvgPathData || a.Nodes == null || b.Nodes == null || a.Nodes.Count != b.Nodes.Count) return false;
            for (int i = 0; i < a.Nodes.Count; i++)
                if (!BezierNodesEqual(a.Nodes[i], b.Nodes[i])) return false;
            return true;
        }

        private static List<int> GetChangedVectorNodeIndices(VectorGeometry before, VectorGeometry after)
        {
            if (before == null || after == null || before.Nodes == null || after.Nodes == null || before.Nodes.Count != after.Nodes.Count)
                return null;
            var changed = new List<int>();
            for (int i = 0; i < before.Nodes.Count; i++)
                if (!BezierNodesEqual(before.Nodes[i], after.Nodes[i])) changed.Add(i);
            return changed;
        }

        private void CommitVectorGeometryEdit(VectorGeometry before, VectorGeometry after, string description)
        {
            LayerNode layer = _editingVectorNode;
            if (layer == null || before == null || after == null || VectorGeometriesEqual(before, after)) return;
            var commands = new List<Kerf.Engine.ICommand>
            {
                new ModifyVectorGeometryCommand(layer, before, after, null)
            };

            if (_currentStudioMode == StudioMode.Animate)
            {
                if (_timelineController == null) EnsureTimelineControllerInitialized();
                Clip clip = _timelineController != null ? _timelineController.ActiveClip : null;
                if (clip == null && _timelineController != null)
                {
                    clip = new Clip(100, "Default Animation", _timelineController.Duration);
                    _timelineController.ActiveClip = clip;
                }
                if (clip != null)
                {
                    if (Document.Animation == null) Document.Animation = new AnimationProjectData();
                    if (Document.Animation.Clips == null) Document.Animation.Clips = new List<Clip>();
                    if (!Document.Animation.Clips.Contains(clip)) Document.Animation.Clips.Add(clip);
                    Document.Animation.ActiveClipId = clip.Id;
                    _timelineController.UseStateMachine = false;

                    List<int> changedNodes = GetChangedVectorNodeIndices(before, after);
                    if (changedNodes != null && changedNodes.Count > 0)
                        commands.AddRange(BuildGeometryNodeKeyframeCommands(clip, layer, _timelineController.CurrentTime, after, changedNodes, before));
                    else
                        commands.AddRange(BuildPathKeyframeCommands(clip, layer, _timelineController.CurrentTime, after));
                }
            }

            ExecuteAnimationCommands(description, commands, () => RefreshAnimationGeometry(layer));
        }

        private void ApplyVectorGeometryEdit(string description, Action mutation)
        {
            if (_editingVectorNode == null || _editingVectorNode.Geometry == null || mutation == null) return;
            VectorGeometry before = _editingVectorNode.Geometry.Clone();
            mutation();
            VectorGeometry after = _editingVectorNode.Geometry.Clone();
            CommitVectorGeometryEdit(before, after, description);
        }

        private static bool IsFrameTransformProperty(PropKey property)
        {
            switch (property)
            {
                case PropKey.X:
                case PropKey.Y:
                case PropKey.Width:
                case PropKey.Height:
                case PropKey.Rotation:
                case PropKey.ScaleX:
                case PropKey.ScaleY:
                case PropKey.AnchorX:
                case PropKey.AnchorY:
                case PropKey.VisualWidth:
                case PropKey.VisualHeight:
                    return true;
                default:
                    return false;
            }
        }

        private static bool IsFixedFrameTransform(LayerNode layer, PropKey property)
        {
            return layer != null && layer.Type == ElementType.Frame && IsFrameTransformProperty(property);
        }

        private FrameworkElement CreateAnimatedPropertyField(FrameworkElement field, LayerNode layer, PropKey property)
        {
            if (field == null || _currentStudioMode != StudioMode.Animate) return field;
            bool fixedFrameTransform = layer != null && layer.Type == ElementType.Frame && IsFrameTransformProperty(property);
            if (fixedFrameTransform)
            {
                field.IsEnabled = false;
                field.ToolTip = "Frame bounds stay fixed in Animate mode. Animate the contents inside the frame.";
                return field;
            }
            var grid = new Grid { Margin = new Thickness(0) };
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) }); // Input field
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(16) }); // Jump Prev ◀
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(20) }); // Diamond ◆/◇
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(16) }); // Jump Next ▶
            Grid.SetColumn(field, 0);
            grid.Children.Add(field);

            uint nodeId = layer != null ? PropertyBinder.GetNumericNodeId(layer.Id) : 0;
            var clip = _timelineController != null ? _timelineController.ActiveClip : null;
            AnimTrack track = (clip != null && nodeId != 0) ? clip.GetTrack(nodeId, (ushort)property) : null;
            bool hasTrack = (track != null && track.Keys != null && track.Keys.Count > 0);
            double currentTime = _timelineController != null ? _timelineController.CurrentTime : 0.0;
            Keyframe existingKey = (track != null) ? track.FindKeyframeAt(currentTime, 0.02) : null;
            bool hasKey = (existingKey != null);

            // Prev Button
            var prevBtn = new Button
            {
                Content = "◀",
                Width = 14,
                Height = 22,
                Padding = new Thickness(0),
                Margin = new Thickness(1, 0, 1, 0),
                BorderThickness = new Thickness(0),
                Background = Brushes.Transparent,
                Foreground = hasTrack ? new SolidColorBrush(Color.FromRgb(140, 160, 195)) : new SolidColorBrush(Color.FromRgb(60, 70, 90)),
                FontSize = 8,
                Cursor = hasTrack ? Cursors.Hand : Cursors.Arrow,
                ToolTip = "Jump to previous keyframe"
            };
            prevBtn.Click += (s, e) =>
            {
                if (track != null)
                {
                    double? prev = track.GetPreviousKeyframeTime(currentTime);
                    if (prev.HasValue && _timelineController != null)
                    {
                        _timelineController.Seek(prev.Value);
                        UpdateTimelineTimeReadout();
                        UpdateTimelineScrubberPosition();
                        RefreshTimelineCanvas();
                        RefreshPropertyInspector();
                    }
                }
            };
            Grid.SetColumn(prevBtn, 1);
            grid.Children.Add(prevBtn);

            // Diamond Button
            var diamondBtn = new Button
            {
                Content = hasKey ? "◆" : "◇",
                Width = 18,
                Height = 22,
                Padding = new Thickness(0),
                Margin = new Thickness(1, 0, 1, 0),
                BorderThickness = new Thickness(0),
                Background = Brushes.Transparent,
                Foreground = hasKey
                    ? KerfBrand.MintBrush // Solid Mint ◆
                    : hasTrack
                        ? new SolidColorBrush(Color.FromRgb(70, 239, 177)) // Hollow Mint ◇
                        : new SolidColorBrush(Color.FromRgb(100, 115, 135)), // Dim Gray ◇
                FontSize = 13,
                FontWeight = FontWeights.Bold,
                Cursor = Cursors.Hand,
                ToolTip = hasKey
                    ? "Keyframe at playhead (click to delete keyframe)"
                    : hasTrack
                        ? "Property animated (click to insert keyframe at playhead)"
                        : "Not keyed (click to insert keyframe and create track)"
            };
            diamondBtn.Click += (s, e) =>
            {
                if (hasKey)
                {
                    if (track != null)
                    {
                        var keysToDelete = new Dictionary<Keyframe, AnimTrack>();
                        if (existingKey != null) keysToDelete[existingKey] = track;
                        if (layer != null && layer.LockAspectRatio)
                        {
                            PropKey pairedProp = PropKey.X;
                            bool hasPaired = false;
                            if (property == PropKey.Width) { pairedProp = PropKey.Height; hasPaired = true; }
                            else if (property == PropKey.Height) { pairedProp = PropKey.Width; hasPaired = true; }
                            else if (property == PropKey.VisualWidth) { pairedProp = PropKey.VisualHeight; hasPaired = true; }
                            else if (property == PropKey.VisualHeight) { pairedProp = PropKey.VisualWidth; hasPaired = true; }
                            else if (property == PropKey.ScaleX) { pairedProp = PropKey.ScaleY; hasPaired = true; }
                            else if (property == PropKey.ScaleY) { pairedProp = PropKey.ScaleX; hasPaired = true; }
                            if (hasPaired && clip != null)
                            {
                                var pairedTrack = clip.GetTrack(nodeId, (ushort)pairedProp);
                                Keyframe pairedKey = pairedTrack != null ? pairedTrack.FindKeyframeAt(currentTime, 0.02) : null;
                                if (pairedTrack != null && pairedKey != null) keysToDelete[pairedKey] = pairedTrack;
                            }
                        }
                        if (keysToDelete.Count > 0)
                        {
                            History.Execute(new DeleteKeyframesCommand(keysToDelete, () =>
                            {
                                if (_timelineController != null) _timelineController.Seek(currentTime);
                                RefreshTimelineUI();
                                RefreshPropertyInspector();
                            }));
                        }
                    }
                }
                else
                {
                    double val = GetPropertyValue(layer, property);
                    AddKeyframeForProperty(layer, property, val);
                    RefreshTimelineUI();
                    RefreshPropertyInspector();
                }
            };
            Grid.SetColumn(diamondBtn, 2);
            grid.Children.Add(diamondBtn);

            // Next Button
            var nextBtn = new Button
            {
                Content = "▶",
                Width = 14,
                Height = 22,
                Padding = new Thickness(0),
                Margin = new Thickness(1, 0, 1, 0),
                BorderThickness = new Thickness(0),
                Background = Brushes.Transparent,
                Foreground = hasTrack ? new SolidColorBrush(Color.FromRgb(140, 160, 195)) : new SolidColorBrush(Color.FromRgb(60, 70, 90)),
                FontSize = 8,
                Cursor = hasTrack ? Cursors.Hand : Cursors.Arrow,
                ToolTip = "Jump to next keyframe"
            };
            nextBtn.Click += (s, e) =>
            {
                if (track != null)
                {
                    double? next = track.GetNextKeyframeTime(currentTime);
                    if (next.HasValue && _timelineController != null)
                    {
                        _timelineController.Seek(next.Value);
                        UpdateTimelineTimeReadout();
                        UpdateTimelineScrubberPosition();
                        RefreshTimelineCanvas();
                        RefreshPropertyInspector();
                    }
                }
            };
            Grid.SetColumn(nextBtn, 3);
            grid.Children.Add(nextBtn);

            return grid;
        }

        private bool IsPropertyAnimated(LayerNode layer, PropKey property)
        {
            var clip = _timelineController != null ? _timelineController.ActiveClip : null;
            uint nodeId = layer != null ? PropertyBinder.GetNumericNodeId(layer.Id) : 0;
            return clip != null && clip.Tracks != null && clip.Tracks.Any(t => t != null && t.NodeId == nodeId && t.Prop == (ushort)property);
        }

        private bool HasPropertyKeyAtPlayhead(LayerNode layer, PropKey property)
        {
            var clip = _timelineController != null ? _timelineController.ActiveClip : null;
            if (clip == null || layer == null) return false;
            uint nodeId = PropertyBinder.GetNumericNodeId(layer.Id);
            var track = clip.Tracks.FirstOrDefault(t => t != null && t.NodeId == nodeId && t.Prop == (ushort)property);
            return track != null && track.Keys != null && track.Keys.Any(k => Math.Abs(k.Time - _timelineController.CurrentTime) <= 0.02);
        }

        private static double GetPropertyValue(LayerNode layer, PropKey property)
        {
            if (layer == null) return 0.0;
            switch (property)
            {
                case PropKey.X:
                    return layer.X + (layer.RenderTransform != null ? layer.RenderTransform.TranslationX : 0.0);
                case PropKey.Y:
                    return layer.Y + (layer.RenderTransform != null ? layer.RenderTransform.TranslationY : 0.0);
                case PropKey.ScaleX:
                    return layer.RenderTransform != null ? layer.RenderTransform.ScaleX : 1.0;
                case PropKey.ScaleY:
                    return layer.RenderTransform != null ? layer.RenderTransform.ScaleY : 1.0;
                case PropKey.Rotation:
                    return layer.Rotation + (layer.RenderTransform != null ? layer.RenderTransform.Rotation : 0.0);
                case PropKey.AnchorX:
                    return layer.RenderTransform != null ? layer.RenderTransform.AnchorX : 0.0;
                case PropKey.AnchorY:
                    return layer.RenderTransform != null ? layer.RenderTransform.AnchorY : 0.0;
                case PropKey.Width:
                case PropKey.VisualWidth:
                    return layer.RenderTransform != null && layer.RenderTransform.VisualWidth > 0 ? layer.RenderTransform.VisualWidth : layer.Width;
                case PropKey.Height:
                case PropKey.VisualHeight:
                    return layer.RenderTransform != null && layer.RenderTransform.VisualHeight > 0 ? layer.RenderTransform.VisualHeight : layer.Height;
                case PropKey.Opacity:
                    return layer.Opacity;
                case PropKey.CornerRadius:
                    return layer.CornerRadius;
                case PropKey.StrokeWidth:
                    return (layer.Strokes != null && layer.Strokes.Count > 0) ? layer.Strokes[0].Width : 0.0;
                case PropKey.StrokeTrimStart:
                    return (layer.Strokes != null && layer.Strokes.Count > 0) ? layer.Strokes[0].TrimStart : 0.0;
                case PropKey.StrokeTrimEnd:
                    return (layer.Strokes != null && layer.Strokes.Count > 0) ? layer.Strokes[0].TrimEnd : 1.0;
                case PropKey.StrokeTrimOffset:
                    return (layer.Strokes != null && layer.Strokes.Count > 0) ? layer.Strokes[0].TrimOffset : 0.0;
                case PropKey.StrokeTaperStart:
                    return (layer.Strokes != null && layer.Strokes.Count > 0) ? layer.Strokes[0].TaperStart : 0.0;
                case PropKey.StrokeTaperEnd:
                    return (layer.Strokes != null && layer.Strokes.Count > 0) ? layer.Strokes[0].TaperEnd : 0.0;
                default:
                    return 0.0;
            }
        }

        private void AutoKeyPropertyLivePreview(LayerNode layer, PropKey property, double value)
        {
            if (_currentStudioMode != StudioMode.Animate || layer == null || IsFixedFrameTransform(layer, property)) return;
            if (_sceneGraph != null) _sceneGraph.InvalidateSubtree(layer.Id);
            RefreshCanvas();
        }

        public void CommitKeyframeValueChange(LayerNode layer, PropKey property, double startVal, double finalVal)
        {
            if (_currentStudioMode != StudioMode.Animate || layer == null || IsFixedFrameTransform(layer, property)) return;
            if (Math.Abs(finalVal - startVal) <= 1e-6) return;
            if (_timelineController == null) EnsureTimelineControllerInitialized();
            if (_timelineController == null) return;

            var clip = _timelineController.ActiveClip;
            if (clip == null)
            {
                clip = new Clip(100, "Default Animation", _timelineController.Duration);
                _timelineController.ActiveClip = clip;
            }
            if (Document.Animation == null) Document.Animation = new AnimationProjectData();
            if (Document.Animation.Clips == null) Document.Animation.Clips = new List<Clip>();
            if (!Document.Animation.Clips.Contains(clip)) Document.Animation.Clips.Add(clip);
            Document.Animation.ActiveClipId = clip.Id;

            uint nodeId = PropertyBinder.GetNumericNodeId(layer.Id);
            AnimTrack track = null;
            if (clip.Tracks != null)
            {
                for (int i = 0; i < clip.Tracks.Count; i++)
                {
                    if (clip.Tracks[i].NodeId == nodeId && clip.Tracks[i].Prop == (ushort)property)
                    {
                        track = clip.Tracks[i];
                        break;
                    }
                }
            }

            bool isNewTrack = false;
            if (track == null)
            {
                track = new AnimTrack(nodeId, (ushort)property);
                isNewTrack = true;
            }

            double curTime = _timelineController.CurrentTime;
            Keyframe existing = track.FindKeyframeAt(curTime, 0.02);

            Action onRender = () =>
            {
                InvalidateAndRefresh(layer);
                RefreshTimelineCanvas();
                RefreshTimelineTracks();
                RefreshGraphEditor();
            };

            if (existing != null)
            {
                var cmd = new ModifyKeyframeValueCommand(existing, startVal, finalVal, onRender);
                History.Execute(cmd);
            }
            else
            {
                var newKf = new Keyframe(curTime, finalVal, _defaultInterpolationMode, _defaultInterpolationX1, _defaultInterpolationY1, _defaultInterpolationX2, _defaultInterpolationY2);
                if (isNewTrack)
                {
                    bool wasBatching = History.IsBatching;
                    if (!wasBatching) History.BeginBatch("Add Track & Keyframe");
                    History.Execute(new AddTrackCommand(clip, track, null));
                    History.Execute(new AddKeyframeCommand(track, newKf, onRender));
                    if (!wasBatching) History.EndBatch();
                }
                else
                {
                    History.Execute(new AddKeyframeCommand(track, newKf, onRender));
                }
            }
        }

        private void AutoKeyProperty(LayerNode layer, PropKey property, double value)
        {
            if (_currentStudioMode != StudioMode.Animate || layer == null || IsFixedFrameTransform(layer, property)) return;
            AddKeyframeForProperty(layer, property, value);
        }

        private void AddKeyframeForProperty(LayerNode layer, PropKey property, double value)
        {
            if (_currentStudioMode != StudioMode.Animate || layer == null || IsFixedFrameTransform(layer, property)) return;
            bool openedHistoryBatch = History != null && !History.IsBatching;
            if (openedHistoryBatch) History.BeginBatch("Keyframe " + property);
            AddKeyframeForPropertyInternal(layer, property, value);

            if (layer != null && layer.LockAspectRatio)
            {
                if (property == PropKey.Width)
                {
                    AddKeyframeForPropertyInternal(layer, PropKey.Height, layer.Height);
                }
                else if (property == PropKey.Height)
                {
                    AddKeyframeForPropertyInternal(layer, PropKey.Width, layer.Width);
                }
                else if (property == PropKey.VisualWidth)
                {
                    double vh = layer.RenderTransform != null && layer.RenderTransform.VisualHeight > 0 ? layer.RenderTransform.VisualHeight : layer.Height;
                    AddKeyframeForPropertyInternal(layer, PropKey.VisualHeight, vh);
                }
                else if (property == PropKey.VisualHeight)
                {
                    double vw = layer.RenderTransform != null && layer.RenderTransform.VisualWidth > 0 ? layer.RenderTransform.VisualWidth : layer.Width;
                    AddKeyframeForPropertyInternal(layer, PropKey.VisualWidth, vw);
                }
                else if (property == PropKey.ScaleX)
                {
                    double sy = layer.RenderTransform != null ? layer.RenderTransform.ScaleY : 1.0;
                    AddKeyframeForPropertyInternal(layer, PropKey.ScaleY, sy);
                }
                else if (property == PropKey.ScaleY)
                {
                    double sx = layer.RenderTransform != null ? layer.RenderTransform.ScaleX : 1.0;
                    AddKeyframeForPropertyInternal(layer, PropKey.ScaleX, sx);
                }
            }
            if (openedHistoryBatch) History.EndBatch();
        }

        private void AddKeyframeForPropertyInternal(LayerNode layer, PropKey property, double value)
        {
            if (_currentStudioMode != StudioMode.Animate || layer == null || IsFixedFrameTransform(layer, property)) return;
            if (_timelineController == null) EnsureTimelineControllerInitialized();
            if (_timelineController == null) return;
            var clip = _timelineController.ActiveClip;
            if (clip == null)
            {
                clip = new Clip(100, "Default Animation", _timelineController.Duration);
                _timelineController.ActiveClip = clip;
            }
            uint nodeId = PropertyBinder.GetNumericNodeId(layer.Id);
            AddOrUpdateTrackKeyframe(clip, nodeId, (ushort)property, _timelineController.CurrentTime, value);
            if (Document.Animation == null) Document.Animation = new AnimationProjectData();
            if (Document.Animation.Clips == null) Document.Animation.Clips = new List<Clip>();
            if (!Document.Animation.Clips.Contains(clip)) Document.Animation.Clips.Add(clip);
            Document.Animation.ActiveClipId = clip.Id;
            _timelineController.UseStateMachine = false;
            RefreshTimelineCanvas();
        }

        private void AddOrUpdateTrackKeyframe(Clip clip, uint nodeId, ushort propertyId, double time, double val)
        {
            if (clip == null) return;
            if (clip.Tracks == null) clip.Tracks = new List<AnimTrack>();
            AnimTrack track = null;
            for (int i = 0; i < clip.Tracks.Count; i++)
            {
                if (clip.Tracks[i].NodeId == nodeId && clip.Tracks[i].Prop == propertyId)
                {
                    track = clip.Tracks[i];
                    break;
                }
            }

            var commands = new List<Kerf.Engine.ICommand>();
            if (track == null)
            {
                track = new AnimTrack(nodeId, propertyId);
                commands.Add(new AddTrackCommand(clip, track));
            }

            Keyframe existing = track.FindKeyframeAt(time, 0.02);
            if (existing != null)
            {
                if (Math.Abs(existing.Value - val) > 1e-9)
                    commands.Add(new ModifyKeyframeValueCommand(existing, existing.Value, val));
            }
            else
            {
                commands.Add(new AddKeyframeCommand(track, new Keyframe(time, val, _defaultInterpolationMode,
                    _defaultInterpolationX1, _defaultInterpolationY1, _defaultInterpolationX2, _defaultInterpolationY2)));
            }
            ExecuteAnimationCommands("Keyframe Property", commands, null);
        }

        private string GetActiveStateNameForClip(Clip clip)
        {
            if (clip == null || Document == null || Document.Animation == null || Document.Animation.StateMachine == null)
                return null;

            var sm = Document.Animation.StateMachine;
            int clipIdx = Document.Animation.Clips != null ? Document.Animation.Clips.IndexOf(clip) : -1;
            if (clipIdx >= 0)
            {
                foreach (var layer in sm.Layers)
                {
                    foreach (var state in layer.States)
                    {
                        if (state.Kind == StateKind.Animation && state.ClipIndex == clipIdx)
                        {
                            return state.Name;
                        }
                    }
                }
            }
            return null;
        }

        private void RefreshTimelineStateTabs()
        {
            if (_timelineStateTabsStack == null) return;
            _timelineStateTabsStack.Children.Clear();

            var sm = Document != null && Document.Animation != null ? Document.Animation.StateMachine : null;
            if (sm == null || sm.Layers.Count == 0 || Document.Animation.Clips == null) return;

            var layer = sm.Layers[0];
            var activeClip = _timelineController != null ? _timelineController.ActiveClip : null;

            foreach (var state in layer.States)
            {
                if (state.Kind != StateKind.Animation) continue;

                bool isActive = false;
                if (activeClip != null && state.ClipIndex >= 0 && state.ClipIndex < Document.Animation.Clips.Count)
                {
                    isActive = ReferenceEquals(Document.Animation.Clips[state.ClipIndex], activeClip);
                }

                var tab = new Border
                {
                    Background = isActive ? KerfBrand.MintBrush : KerfBrand.DarkSlateBrush,
                    BorderBrush = isActive ? KerfBrand.MintBrush : KerfBrand.TealBrush,
                    BorderThickness = new Thickness(1),
                    CornerRadius = new CornerRadius(4),
                    Padding = new Thickness(8, 3, 8, 3),
                    Margin = new Thickness(0, 0, 4, 0),
                    Cursor = Cursors.Hand,
                    ToolTip = "State: " + state.Name + " (Click to open state timeline)"
                };

                var tabText = new TextBlock
                {
                    Text = (isActive ? "◉ " : "○ ") + state.Name,
                    FontSize = 10.5,
                    FontWeight = isActive ? FontWeights.Bold : FontWeights.SemiBold,
                    Foreground = isActive ? KerfBrand.TextBlackBrush : KerfBrand.TextWhiteBrush
                };
                tab.Child = tabText;

                var capturedState = state;
                tab.MouseLeftButtonUp += (s, e) =>
                {
                    OpenStateTimeline(capturedState);
                };

                _timelineStateTabsStack.Children.Add(tab);
            }

            var addStateBtn = new Border
            {
                Background = Brushes.Transparent,
                BorderBrush = KerfBrand.TealBrush,
                BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(4),
                Padding = new Thickness(6, 3, 6, 3),
                Cursor = Cursors.Hand,
                ToolTip = "Add a new animation state and open its timeline"
            };
            addStateBtn.Child = new TextBlock
            {
                Text = "+ State",
                FontSize = 10.5,
                Foreground = KerfBrand.MintBrush
            };
            addStateBtn.MouseLeftButtonUp += (s, e) =>
            {
                AddNewStateWithTimeline();
            };
            _timelineStateTabsStack.Children.Add(addStateBtn);

            if (_timelineClipText != null && activeClip != null)
            {
                string stateName = GetActiveStateNameForClip(activeClip);
                _timelineClipText.Text = !string.IsNullOrEmpty(stateName)
                    ? "State: [" + stateName + "] · Clip: " + activeClip.Name
                    : "Clip: " + activeClip.Name;
            }
        }

        private void AddNewStateWithTimeline()
        {
            if (_timelineController == null) EnsureTimelineControllerInitialized();
            var sm = EnsureStateMachineRuntime();
            if (sm == null || sm.Definition == null || sm.Definition.Layers.Count == 0) return;

            var layer = sm.Definition.Layers[0];
            int nextIndex = layer.States.Count;
            string stateName = "State " + nextIndex;

            if (Document.Animation == null) Document.Animation = new AnimationProjectData();
            if (Document.Animation.Clips == null) Document.Animation.Clips = new List<Clip>();

            uint clipId = Document.Animation.Clips.Count == 0 ? 100u : Document.Animation.Clips.Max(c => c == null ? 0u : c.Id) + 1u;
            var newClip = new Clip(clipId, stateName, Math.Max(0.1, _timelineController.Duration), _timelineController.Fps, LoopMode.Loop);
            Document.Animation.Clips.Add(newClip);
            if (!sm.Clips.Contains(newClip)) sm.Clips.Add(newClip);

            var newState = new MachineState(nextIndex, stateName, StateKind.Animation, sm.Clips.IndexOf(newClip));
            layer.AddState(newState);

            History.MarkDirty();
            BuildStateMachineStatesGraph();
            SelectAnimationClip(newClip);
        }

        public void RefreshTimelineUI()
        {
            UpdateTimelineWorkAreaFields();
            RefreshTimelineTracks();
            RefreshTimelineCanvas();
            RefreshInterpolationGraphPanels();
            UpdateTimelineTimeReadout();
            UpdateTimelineScrubberPosition();
            RefreshTimelineStateTabs();
            BuildStateMachineAnimationsList();
        }

        private void RefreshTimelineTracks()
        {
            if (_timelineTracksStack == null) return;
            _timelineTracksStack.Children.Clear();

            // 1. Top Ruler Header Spacer (Height: 22px)
            var rulerHeader = new Border
            {
                Height = 22,
                Background = new SolidColorBrush(Color.FromRgb(15, 20, 28)),
                BorderBrush = new SolidColorBrush(Color.FromRgb(42, 48, 66)),
                BorderThickness = new Thickness(0, 0, 0, 1),
                Padding = new Thickness(8, 0, 8, 0)
            };
            string stateTitle = GetActiveStateNameForClip(_timelineController != null ? _timelineController.ActiveClip : null);
            string rulerTitle = !string.IsNullOrEmpty(stateTitle)
                ? "STATE: " + stateTitle.ToUpper() + " · TRACKS"
                : "OBJECTS / TRACKS";
            var headerText = new TextBlock
            {
                Text = rulerTitle,
                FontSize = 10,
                FontWeight = FontWeights.Bold,
                Foreground = !string.IsNullOrEmpty(stateTitle) ? KerfBrand.MintBrush : new SolidColorBrush(Color.FromRgb(140, 160, 195)),
                VerticalAlignment = VerticalAlignment.Center
            };
            rulerHeader.Child = headerText;
            _timelineTracksStack.Children.Add(rulerHeader);

            var lanes = BuildTimelineLanes();
            if (lanes.Count == 0)
            {
                var hint = new TextBlock
                {
                    Text = "Select a layer on canvas or create keyframes to view tracks.",
                    FontSize = 10,
                    Foreground = new SolidColorBrush(Color.FromRgb(120, 135, 160)),
                    Margin = new Thickness(8, 12, 8, 8),
                    TextWrapping = TextWrapping.Wrap
                };
                _timelineTracksStack.Children.Add(hint);
                return;
            }

            foreach (var lane in lanes)
            {
                if (lane.IsMaster)
                {
                    bool isExpanded = !_collapsedTimelineObjects.Contains(lane.NodeId);
                    _timelineTracksStack.Children.Add(CreateMasterObjectRow(lane.NodeId, isExpanded));
                }
                else
                {
                    _timelineTracksStack.Children.Add(CreatePropertyTrackRow(lane.NodeId, lane.Track));
                }
            }
        }

        private List<TimelineLaneInfo> BuildTimelineLanes()
        {
            var lanes = new List<TimelineLaneInfo>();
            if (_timelineController == null || _timelineController.ActiveClip == null) return lanes;

            var nodeIds = GetTimelineObjectNodeIds();
            double currentY = 22.0; // Starts immediately below 22px ruler

            foreach (var nodeId in nodeIds)
            {
                lanes.Add(new TimelineLaneInfo
                {
                    IsMaster = true,
                    NodeId = nodeId,
                    Track = null,
                    Y = currentY,
                    Height = 22.0
                });
                currentY += 22.0;

                if (!_collapsedTimelineObjects.Contains(nodeId))
                {
                    var tracks = _timelineController.ActiveClip.GetTracksForNode(nodeId);
                    foreach (var track in tracks)
                    {
                        lanes.Add(new TimelineLaneInfo
                        {
                            IsMaster = false,
                            NodeId = nodeId,
                            Track = track,
                            Y = currentY,
                            Height = 22.0
                        });
                        currentY += 22.0;
                    }
                }
            }

            return lanes;
        }

        private List<uint> GetTimelineObjectNodeIds()
        {
            var list = new List<uint>();
            if (_timelineController != null && _timelineController.ActiveClip != null)
            {
                var sel = _selectedLayers.FirstOrDefault();
                uint selId = sel != null ? PropertyBinder.GetNumericNodeId(sel.Id) : 0;
                if (selId != 0)
                {
                    list.Add(selId);
                }
                foreach (var track in _timelineController.ActiveClip.Tracks)
                {
                    if (track.NodeId != 0 && !list.Contains(track.NodeId))
                    {
                        list.Add(track.NodeId);
                    }
                }
            }
            return list;
        }

        private LayerNode FindLayerByNumericId(uint nodeId)
        {
            var page = Document != null ? Document.GetActivePage() : null;
            if (page == null) return null;
            return page.GetAllLayersFlat().FirstOrDefault(l => PropertyBinder.GetNumericNodeId(l.Id) == nodeId);
        }

        private static string GetLayerTypeBadge(LayerNode layer)
        {
            if (layer == null) return "•";
            switch (layer.Type)
            {
                case ElementType.Frame: return "F";
                case ElementType.Group: return "G";
                case ElementType.Rectangle: return "R";
                case ElementType.Ellipse: return "O";
                case ElementType.Text: return "T";
                case ElementType.Path:
                case ElementType.Line:
                case ElementType.Arrow:
                case ElementType.Polygon:
                case ElementType.Star: return "V";
                case ElementType.Image: return "I";
                case ElementType.ComponentInstance: return "C";
                default: return "■";
            }
        }

        private static string GetPropertyName(ushort prop)
        {
            switch ((PropKey)prop)
            {
                case PropKey.X: return "Position X";
                case PropKey.Y: return "Position Y";
                case PropKey.ScaleX: return "Scale X";
                case PropKey.ScaleY: return "Scale Y";
                case PropKey.Rotation: return "Rotation";
                case PropKey.AnchorX: return "Anchor X";
                case PropKey.AnchorY: return "Anchor Y";
                case PropKey.Opacity: return "Opacity";
                case PropKey.Width: return "Width";
                case PropKey.Height: return "Height";
                case PropKey.VisualWidth: return "Visual Width";
                case PropKey.VisualHeight: return "Visual Height";
                case PropKey.CornerRadius: return "Corner Radius";
                case PropKey.StrokeWidth: return "Stroke Width";
                case PropKey.StrokeTrimStart: return "Trim Start";
                case PropKey.StrokeTrimEnd: return "Trim End";
                case PropKey.StrokeTrimOffset: return "Trim Offset";
                case PropKey.StrokeTaperStart: return "Taper Start";
                case PropKey.StrokeTaperEnd: return "Taper End";
                case PropKey.Path: return "Path Geometry";
                case PropKey.PathNode: return "Path Node";
                default: return ((PropKey)prop).ToString();
            }
        }

        private string GetEvaluatedPropertyString(uint nodeId, ushort prop)
        {
            var layer = FindLayerByNumericId(nodeId);
            if (prop == (ushort)PropKey.PathNode)
            {
                var nodeTrack = _timelineController != null && _timelineController.ActiveClip != null
                    ? _timelineController.ActiveClip.Tracks.FirstOrDefault(track => track != null && track.NodeId == nodeId && track.Prop == prop)
                    : null;
                if (nodeTrack != null && nodeTrack.GeometryNodeIndex >= 0)
                {
                    BezierNode sampledNode = nodeTrack.SampleGeometryNode(_timelineController.CurrentTime);
                    if (sampledNode == null && layer != null && layer.Geometry != null && layer.Geometry.Nodes != null && nodeTrack.GeometryNodeIndex < layer.Geometry.Nodes.Count)
                        sampledNode = layer.Geometry.Nodes[nodeTrack.GeometryNodeIndex];
                    if (sampledNode != null)
                        return string.Format(CultureInfo.InvariantCulture, "X {0:F1} · Y {1:F1}", sampledNode.Anchor.X, sampledNode.Anchor.Y);
                }
                return "Path node";
            }
            if (prop == (ushort)PropKey.Path)
            {
                var pathTrack = _timelineController != null && _timelineController.ActiveClip != null
                    ? _timelineController.ActiveClip.GetTrack(nodeId, prop)
                    : null;
                VectorGeometry sampled = pathTrack != null ? pathTrack.SampleGeometry(_timelineController.CurrentTime) : null;
                VectorGeometry geometry = sampled ?? (layer != null ? layer.Geometry : null);
                int nodeCount = geometry != null && geometry.Nodes != null ? geometry.Nodes.Count : 0;
                return nodeCount > 0 ? string.Format("{0} nodes", nodeCount) : "SVG path";
            }
            double val = 0.0;
            bool hasVal = false;

            if (_timelineController != null && _timelineController.ActiveClip != null)
            {
                var track = _timelineController.ActiveClip.GetTrack(nodeId, prop);
                if (track != null && track.Keys.Count > 0)
                {
                    val = track.Sample(_timelineController.CurrentTime);
                    hasVal = true;
                }
            }

            if (!hasVal && layer != null)
            {
                switch ((PropKey)prop)
                {
                    case PropKey.X: val = layer.X + (layer.RenderTransform != null ? layer.RenderTransform.TranslationX : 0); break;
                    case PropKey.Y: val = layer.Y + (layer.RenderTransform != null ? layer.RenderTransform.TranslationY : 0); break;
                    case PropKey.ScaleX: val = layer.RenderTransform != null ? layer.RenderTransform.ScaleX : 1.0; break;
                    case PropKey.ScaleY: val = layer.RenderTransform != null ? layer.RenderTransform.ScaleY : 1.0; break;
                    case PropKey.Rotation: val = layer.Rotation + (layer.RenderTransform != null ? layer.RenderTransform.Rotation : 0); break;
                    case PropKey.AnchorX: val = layer.RenderTransform != null ? layer.RenderTransform.AnchorX : 0.0; break;
                    case PropKey.AnchorY: val = layer.RenderTransform != null ? layer.RenderTransform.AnchorY : 0.0; break;
                    case PropKey.Opacity: val = layer.Opacity; break;
                    case PropKey.Width:
                    case PropKey.VisualWidth: val = layer.RenderTransform != null && layer.RenderTransform.VisualWidth > 0 ? layer.RenderTransform.VisualWidth : layer.Width; break;
                    case PropKey.Height:
                    case PropKey.VisualHeight: val = layer.RenderTransform != null && layer.RenderTransform.VisualHeight > 0 ? layer.RenderTransform.VisualHeight : layer.Height; break;
                    case PropKey.CornerRadius: val = layer.CornerRadius; break;
                    case PropKey.StrokeWidth: val = (layer.Strokes != null && layer.Strokes.Count > 0) ? layer.Strokes[0].Width : 0.0; break;
                    case PropKey.StrokeTrimStart: val = (layer.Strokes != null && layer.Strokes.Count > 0) ? layer.Strokes[0].TrimStart : 0.0; break;
                    case PropKey.StrokeTrimEnd: val = (layer.Strokes != null && layer.Strokes.Count > 0) ? layer.Strokes[0].TrimEnd : 1.0; break;
                    case PropKey.StrokeTrimOffset: val = (layer.Strokes != null && layer.Strokes.Count > 0) ? layer.Strokes[0].TrimOffset : 0.0; break;
                    case PropKey.StrokeTaperStart: val = (layer.Strokes != null && layer.Strokes.Count > 0) ? layer.Strokes[0].TaperStart : 0.0; break;
                    case PropKey.StrokeTaperEnd: val = (layer.Strokes != null && layer.Strokes.Count > 0) ? layer.Strokes[0].TaperEnd : 0.0; break;
                }
            }

            switch ((PropKey)prop)
            {
                case PropKey.X:
                case PropKey.Y:
                case PropKey.Width:
                case PropKey.Height:
                case PropKey.VisualWidth:
                case PropKey.VisualHeight:
                case PropKey.CornerRadius:
                case PropKey.StrokeWidth:
                    return string.Format("{0:F1} px", val);
                case PropKey.Rotation:
                    return string.Format("{0:F1} °", val);
                case PropKey.Opacity:
                case PropKey.StrokeTrimStart:
                case PropKey.StrokeTrimEnd:
                case PropKey.StrokeTrimOffset:
                case PropKey.StrokeTaperStart:
                case PropKey.StrokeTaperEnd:
                    return string.Format("{0:F0} %", val * 100);
                case PropKey.ScaleX:
                case PropKey.ScaleY:
                case PropKey.AnchorX:
                case PropKey.AnchorY:
                    return string.Format("{0:F2}", val);
                default:
                    return string.Format("{0:F1}", val);
            }
        }

        private FrameworkElement CreateMasterObjectRow(uint nodeId, bool isExpanded)
        {
            var layer = FindLayerByNumericId(nodeId);
            string layerName = layer != null ? layer.Name : string.Format("Object #{0}", nodeId);
            string typeBadge = GetLayerTypeBadge(layer);
            var tracks = (_timelineController != null && _timelineController.ActiveClip != null)
                ? _timelineController.ActiveClip.GetTracksForNode(nodeId)
                : new List<AnimTrack>();

            bool isSelected = _selectedLayers.Any(l => PropertyBinder.GetNumericNodeId(l.Id) == nodeId);

            var grid = new Grid
            {
                Height = 22,
                Background = isSelected
                    ? new SolidColorBrush(Color.FromRgb(24, 48, 64))
                    : new SolidColorBrush(Color.FromRgb(16, 20, 28)),
                Cursor = Cursors.Hand
            };
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(20) }); // Expander button
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(18) }); // Icon badge
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) }); // Name
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto }); // Track count

            // 1. Expander arrow
            var expandBtn = new Border
            {
                Width = 16,
                Height = 16,
                Background = Brushes.Transparent,
                Child = new TextBlock
                {
                    Text = isExpanded ? "▼" : "▶",
                    FontSize = 9,
                    Foreground = new SolidColorBrush(Color.FromRgb(140, 160, 195)),
                    HorizontalAlignment = HorizontalAlignment.Center,
                    VerticalAlignment = VerticalAlignment.Center
                }
            };
            expandBtn.MouseLeftButtonDown += (s, e) =>
            {
                if (_collapsedTimelineObjects.Contains(nodeId))
                    _collapsedTimelineObjects.Remove(nodeId);
                else
                    _collapsedTimelineObjects.Add(nodeId);

                RefreshTimelineUI();
                e.Handled = true;
            };
            Grid.SetColumn(expandBtn, 0);
            grid.Children.Add(expandBtn);

            // 2. Type badge
            var badge = new Border
            {
                Width = 14,
                Height = 14,
                CornerRadius = new CornerRadius(2),
                Background = new SolidColorBrush(Color.FromRgb(32, 40, 56)),
                Child = new TextBlock
                {
                    Text = typeBadge,
                    FontSize = 8,
                    FontWeight = FontWeights.Bold,
                    Foreground = KerfBrand.MintBrush,
                    HorizontalAlignment = HorizontalAlignment.Center,
                    VerticalAlignment = VerticalAlignment.Center
                }
            };
            Grid.SetColumn(badge, 1);
            grid.Children.Add(badge);

            // 3. Name
            var nameBlock = new TextBlock
            {
                Text = layerName,
                FontSize = 11,
                FontWeight = FontWeights.SemiBold,
                Foreground = isSelected ? KerfBrand.MintBrush : Brushes.White,
                VerticalAlignment = VerticalAlignment.Center,
                Margin = new Thickness(4, 0, 4, 0),
                TextTrimming = TextTrimming.CharacterEllipsis
            };
            Grid.SetColumn(nameBlock, 2);
            grid.Children.Add(nameBlock);

            // 4. Track count badge
            var countBlock = new TextBlock
            {
                Text = string.Format("({0})", tracks.Count),
                FontSize = 9,
                Foreground = new SolidColorBrush(Color.FromRgb(100, 120, 150)),
                VerticalAlignment = VerticalAlignment.Center,
                Margin = new Thickness(0, 0, 8, 0)
            };
            Grid.SetColumn(countBlock, 3);
            grid.Children.Add(countBlock);

            grid.MouseLeftButtonDown += (s, e) =>
            {
                if (layer != null)
                {
                    _selectedLayers.Clear();
                    _selectedLayers.Add(layer);
                    OnSelectionChanged();
                    RefreshCanvas();
                    RefreshTimelineUI();
                }
            };

            return grid;
        }

